use serde_yaml::{Value, Mapping};
fn py(v:&Value, out:&mut String, indent:usize){
 match v{
  Value::Null=>out.push_str("None"),
  Value::Bool(b)=>out.push_str(if *b{"True"}else{"False"}),
  Value::Number(n)=>{ if let Some(i)=n.as_i64(){out.push_str(&i.to_string())} else if let Some(u)=n.as_u64(){out.push_str(&u.to_string())} else if let Some(f)=n.as_f64(){out.push_str(&format!("{:?}",f))} else {out.push_str("None")} },
  Value::String(s)=>{ out.push_str(&format!("{:?}", s)); },
  Value::Sequence(seq)=>{ if seq.is_empty(){out.push_str("[]")} else { out.push_str("[\n"); for it in seq{ out.push_str(&" ".repeat(indent+2)); py(it,out,indent+2); out.push_str(",\n"); } out.push_str(&" ".repeat(indent)); out.push_str("]"); } },
  Value::Mapping(m)=>{ if m.is_empty(){out.push_str("{}")} else { out.push_str("{\n"); for (k,val) in m{ out.push_str(&" ".repeat(indent+2)); py(k,out,indent+2); out.push_str(": "); py(val,out,indent+2); out.push_str(",\n"); } out.push_str(&" ".repeat(indent)); out.push_str("}"); } },
  Value::Tagged(t)=>{ py(&t.value,out,indent); }
 }
}
fn main(){
 let path=std::env::args().nth(1).unwrap(); let key=std::env::args().nth(2).unwrap();
 let txt=std::fs::read_to_string(path).unwrap(); let v:Value=serde_yaml::from_str(&txt).unwrap();
