{"command":"mkdir -p app
cat > app/yamlmini.py << 'PYEOF'
import re

class YamlError(Exception):
    pass

class YScalar:
    __slots__=("value","style","line","col","end_line","end_col","tag","raw")
    def __init__(self,value,style="plain",line=1,col=1,end_line=None,end_col=None,tag=None,raw=None):
        self.value=value; self.style=style; self.line=line; self.col=col
        self.end_line=end_line if end_line is not None else line
        self.end_col=end_col if end_col is not None else col
        self.tag=tag; self.raw=value if raw is None else raw
    def __repr__(self): return f"YScalar({self.value!r},{self.style})"
class YSeq:
    __slots__=("items","line","col","flow")
    def __init__(self,items,line=1,col=1,flow=False): self.items=items; self.line=line; self.col=col; self.flow=flow
    def __repr__(self): return f"YSeq({self.items!r})"
class YMap:
    __slots__=("pairs","line","col","flow","end_line","end_col")
    def __init__(self,pairs,line=1,col=1,flow=False,end_line=None,end_col=None): self.pairs=pairs; self.line=line; self.col=col; self.flow=flow; self.end_line=end_line; self.end_col=end_col
    def __repr__(self): return f"YMap({self.pairs!r})"

# Helpers for serde_yaml-like plain scalar resolution
_INT_RE=re.compile(r'^(?:[-+]?[0-9]+|0x[0-9a-fA-F]+|0o[0-7]+|0b[01]+)$')
def resolve_plain_scalar(text):
    if text in ("", "~", "null", "Null", "NULL"):
        return None
    if text in ("true","True","TRUE"): return True
    if text in ("false","False","FALSE"): return False
    # integers, excluding leading zero decimals with length>1 (01, 007)
    if _INT_RE.match(text):
        # decimal leading zero check
        t=text
        sign=1
        if t[0] in "+-":
            if t[0]=='-': sign=-1
            t2=t[1:]
        else:
            t2=t
        if re.match(r'^0[0-9]+$', t2):
            return text
        try:
            if t2.startswith("0x"): return sign*int(t2[2:],16)
            if t2.startswith("0o"): return sign*int(t2[2:],8)
            if t2.startswith("0b"): return sign*int(t2[2:],2)
            return int(text)
        except Exception:
            return text
    # floats
    low=text.lower()
    if low in (".inf","+.inf"): return float("inf")
    if low=="-.inf": return float("-inf")
    if low in (".nan",): return float("nan")
    if re.match(r'^[-+]?(?:[0-9]+\.[0-9]*|\.[0-9]+|[0-9]+)(?:[eE][-+]?[0-9]+)?$', text) and ('.' in text or 'e' in text or 'E' in text):
        # leading zero like 01.0 ? serde-yaml probably floats; allow
        try: return float(text)
        except Exception: return text
    return text

def generic_value(node):
    if isinstance(node, YScalar):
        if node.tag in ("!!str","tag:yaml.org,2002:str"):
            return node.value
        if node.style=="plain":
            return resolve_plain_scalar(node.value)
        return node.value
    if isinstance(node,YSeq):
        return [generic_value(x) for x in node.items]
    if isinstance(node,YMap):
        d={}
        for k,v in node.pairs:
            gv=generic_value(v)
            gk=generic_value(k)
            # JSON keys must be strings; serde_yaml Value Mapping keys can be non-string, converting to JSON via serde may stringify in jf?
            # Keep as string representation for boolean/null/number keys like serde_json Map conversion would fail? Rare.
            if isinstance(gk,bool): key="true" if gk else "false"
            elif gk is None: key="null"
            elif isinstance(gk,(list,dict)): key=str(gk)
            else: key=gk if isinstance(gk,str) else str(gk)
            d[key]=gv
        return d
    return node

def _strip_comment_plain(s):
    # remove ' #...' comment in plain context
    i=0
    while i < len(s):
        if s[i]=='#' and i>0 and s[i-1] in ' \t':
            return s[:i].rstrip()
        i+=1
    return s

class _Line:
    __slots__=("text","num")
    def __init__(self,text,num): self.text=text; self.num=num
    @property
    def indent(self):
        n=0
        for ch in self.text:
            if ch==' ': n+=1
            elif ch=='\t': n+=1
            else: break
        return n
    @property
    def stripped(self): return self.text.strip()
    @property
    def content(self): return self.text[self.indent:]

class Parser:
    def __init__(self, text):
        # control characters check as in libyaml
        for i,ch in enumerate(text):
            o=ord(ch)
            if (o<0x20 and ch not in "\n\t\r") or o==0x7f:
                raise YamlError(f"control characters are not allowed at position {i}")
        # Normalize CRLF
        text=text.replace("\r\n","\n").replace("\r","\n")
        self.raw_lines=text.split("\n")
        self.lines=[_Line(t,i+1) for i,t in enumerate(self.raw_lines)]
        self.pos=0
        self.anchors={}

    def error(self,msg,line=None,col=None):
        if line is not None:
            raise YamlError(f"{msg} at line {line} column {col}")
        raise YamlError(msg)

    def peek(self):
        while self.pos < len(self.lines):
            l=self.lines[self.pos]
            if l.stripped=="" or l.stripped.startswith("#"):
                self.pos+=1; continue
            return l
        return None

    def parse(self):
        # directives
        l=self.peek()
        if l is None:
            return YScalar("", "plain", 1,1)
        if l.content.startswith("%"):
            # directive
            name=l.content[1:].split()[0] if len(l.content)>1 else ""
            # libyaml: found unknown directive name at line1 col3? approximate
            self.error("found unknown directive name", l.num, 3)
        if l.stripped=="---" or l.stripped.startswith("--- "):
            # consume marker, inline remainder handling simple
            if l.stripped=="---":
                self.pos+=1
            else:
                # replace line content after ---
                idx=l.text.find("---")
                rest=l.text[idx+3:].lstrip()
                self.lines[self.pos]=_Line(" "*l.indent+rest,l.num)
            l=self.peek()
            if l is None:
                return YScalar("", "plain", 1,1)
        node=self.parse_block(l.indent)
        # leftover check
        l2=self.peek()
        if l2 is not None and l2.stripped not in ("...","---"):
            # mapping values not allowed etc if contains colon
            # try mimic: if a plain scalar document then mapping line etc
            # For many cases serde_yaml errors: mapping values are not allowed in this context
            txt=l2.content
            col=find_mapping_colon(txt)
            if col>=0:
                raise YamlError(f"mapping values are not allowed in this context at line {l2.num} column {l2.indent+col+1}")
            else:
                # did not find expected <document start> ?
                raise YamlError(f"did not find expected <document start> at line {l2.num} column {l2.indent+1}")
        return node

    def parse_block(self, min_indent):
        l=self.peek()
        if l is None:
            return YScalar("", "plain", 1,1)
        indent=l.indent
        content=l.content
        # sequence
        if content=="-" or content.startswith("- "):
            return self.parse_block_seq(indent)
        # mapping?
        if find_mapping_colon(content)>=0 or content.startswith("? "):
            return self.parse_block_map(indent)
        # scalar (maybe flow/quoted/etc on this line)
        return self.parse_scalar_block_line()

    def parse_block_seq(self, indent):
        start_line=self.peek().num; start_col=indent+1
        items=[]
        while True:
            l=self.peek()
            if l is None or l.indent!=indent: break
            c=l.content
            if not (c=="-" or c.startswith("- ")): break
            # consume line
            self.pos+=1
            after=c[1:].lstrip(" ")
            after_indent=indent + (len(c)-len(c[1:].lstrip(" "))) + (1 if False else 0)
            # effective indent for content: position of after in original line
            content_col = l.text.find(after, indent+1) if after else indent+2
            if after=="":
                # nested block on following lines
                nl=self.peek()
                if nl is None or nl.indent<=indent:
                    items.append(YScalar("", "plain", l.num, indent+1))
                else:
                    items.append(self.parse_block(nl.indent))
            elif find_mapping_colon(after)>=0 and not after.startswith(("{","[","'",'"')):
                # inline map starting on this line, treat as a map with first key here and subsequent keys at content_col indent
                # insert virtual line
                virtual=_Line(" "*content_col+after, l.num)
                self.lines.insert(self.pos, virtual)
                items.append(self.parse_block_map(content_col, first_virtual=True))
            else:
                items.append(self.parse_inline_or_scalar(after, l.num, content_col+1, current_line_indent=indent))
        return YSeq(items,start_line,start_col)

    def parse_block_map(self, indent, first_virtual=False):
        start=self.peek(); start_line=start.num; start_col=indent+1
        pairs=[]
        while True:
            l=self.peek()
            if l is None: break
            if l.indent!=indent: break
            c=l.content
            if c=="-" or c.startswith("- "): break
            col=find_mapping_colon(c)
            if col<0:
                # explicit key ? not supporting
                break
            key_text=c[:col].rstrip()
            after=c[col+1:]
            if after and not after.startswith(" "):
                # colon without space in plain? find_mapping_colon only accepted colon followed space/Eol generally
                pass
            after_stripped=after.lstrip(" ")
            after_col=indent+col+2 + (len(after)-len(after_stripped))
            self.pos+=1
            key=self.parse_key(key_text, l.num, indent+1)
            if after_stripped=="" or after_stripped.startswith("#"):
                # nested value
                nl=self.peek()
                if nl is None:
                    val=YScalar("", "plain", l.num, after_col)
                elif nl.indent>indent:
                    val=self.parse_block(nl.indent)
                elif nl.indent==indent and (nl.content=="-" or nl.content.startswith("- ")):
                    val=self.parse_block_seq(indent)
                else:
                    val=YScalar("", "plain", l.num, after_col)
            else:
                val=self.parse_inline_or_scalar(after_stripped, l.num, after_col+1, current_line_indent=indent)
            pairs.append((key,val))
            if first_virtual:
                # subsequent lines will be handled if they align; parse_block_map loop continues naturally because virtual inserted line consumed
                first_virtual=False
        return YMap(pairs,start_line,start_col)

    def parse_key(self, text, line_num, col):
        text=text.strip()
        if text.startswith("'") or text.startswith('"'):
            node,_=parse_quoted(text,0,line_num,col)
            return node
        if text.startswith("[") or text.startswith("{"):
            # flow key unlikely
            node,_=FlowParser(text,line_num,col,self).parse_value(0)
            return node
        return YScalar(text,"plain",line_num,col,end_col=col+len(text))

    def parse_scalar_block_line(self):
        l=self.peek(); self.pos+=1
        text=l.content
        node=self.parse_inline_or_scalar(text, l.num, l.indent+1, current_line_indent=l.indent, scalar_block_first=True)
        return node

    def parse_inline_or_scalar(self, text, line_num, col, current_line_indent=0, scalar_block_first=False):
        # anchors/tags prefix
        anchor=None; tag=None
        orig_text=text
        while True:
            if text.startswith("&"):
                m=re.match(r'&([^\s\[\]{},]+)\s*(.*)$', text, re.S)
                if m: anchor=m.group(1); text=m.group(2); col+=len(orig_text)-len(text); orig_text=text; continue
            if text.startswith("!"):
                m=re.match(r'(!{1,2}[^\s]*)\s+(.*)$', text, re.S)
                if m: tag=m.group(1); text=m.group(2); col+=len(orig_text)-len(text); orig_text=text; continue
            break
        if text=="" or text.startswith("#"):
            node=YScalar("","plain",line_num,col,tag=tag)
            if anchor: self.anchors[anchor]=node
            return node
        if text.startswith("*"):
            m=re.match(r'\*([^\s\[\]{},]+)',text)
            name=m.group(1) if m else ""
            if name not in self.anchors:
                raise YamlError(f"unknown anchor at line {line_num} column {col}")
            return self.anchors[name]
        if text[0] in "[{":
            # flow, may span multiple lines in block context. Gather continuation lines until balanced
            full=text
            # strip trailing comment risk ignored
            while not flow_balanced(full):
                nl=self.peek()
                if nl is None:
                    break
                self.pos+=1
                full+="\n"+nl.text
            fp=FlowParser(full,line_num,col,self)
            node,idx=fp.parse_value(0)
            rest=full[idx:].strip()
            if rest and not rest.startswith("#"):
                # extra tokens after flow could be error; ignore for now
                pass
            if anchor: self.anchors[anchor]=node
            return node
        if text[0] in "'\"":
            # quoted may span lines
            full=text
            while True:
                try:
                    node,idx=parse_quoted(full,0,line_num,col)
                    break
                except YamlError as e:
                    if "unterminated" in str(e):
                        nl=self.peek()
                        if nl is None: raise
                        self.pos+=1; full+="\n"+nl.text; continue
                    raise
            # after quoted, may be comment etc.
            if tag: node.tag=tag
            if anchor: self.anchors[anchor]=node
            return node
        if text[0] in "|>":
            # block scalar
            node=self.parse_block_scalar(text,line_num,col,current_line_indent)
            node.tag=tag
            if anchor: self.anchors[anchor]=node
            return node
        # Plain scalar. Check invalid leading characters like libyaml
        if text[0]=='%' :
            raise YamlError(f"found character that cannot start any token at line {line_num} column {col}, while scanning for the next token")
        if text[0] in ",[]{}#&*!|>'\"%@`":
            raise YamlError(f"found character that cannot start any token at line {line_num} column {col}, while scanning for the next token")
        # Plain scalar ends at ' #' comment, newline continuation
        val=_strip_comment_plain(text).rstrip()
        # multiline plain continuation: following indented lines that aren't map/seq at parent indent
        while True:
            # peek without consuming blank? use raw peek index
            save=self.pos
            nl=self.peek()
            if nl is None: break
            if nl.indent<=current_line_indent: break
            # If next line looks like map at deeper indent, it could be continuation only in scalar doc context. For initial scalar doc, this would be error later.
            if not scalar_block_first:
                break
            # consume as folded continuation if no mapping colon?
            if find_mapping_colon(nl.content)>=0:
                break
            self.pos+=1
            val=val+" "+_strip_comment_plain(nl.content).strip()
        node=YScalar(val,"plain",line_num,col,end_col=col+len(val),tag=tag)
        if anchor: self.anchors[anchor]=node
        return node

    def parse_block_scalar(self, header, line_num, col, parent_indent):
        style=header[0]
        rest=header[1:].strip()
        chomp=None; indent_indicator=None
        for ch in rest.split("#")[0].strip():
            if ch in "+-": chomp=ch
            elif ch.isdigit(): indent_indicator=int(ch)
        # collect following lines with indent > parent or blank
        collected=[]
        block_indent=None
        while self.pos < len(self.lines):
            l=self.lines[self.pos]
            if l.stripped=="":
                collected.append(l); self.pos+=1; continue
            if block_indent is None:
                if indent_indicator is not None:
                    block_indent=parent_indent+indent_indicator
                else:
                    if l.indent<=parent_indent: break
                    block_indent=l.indent
            if l.indent<block_indent:
                break
            collected.append(l); self.pos+=1
        if block_indent is None: block_indent=parent_indent+1
        # trim trailing blank lines handled by chomping below but retain lines internal
        texts=[]
        for l in collected:
            if l.stripped=="": texts.append("")
            else: texts.append(l.text[block_indent:] if len(l.text)>=block_indent else "")
        # remove trailing blanks for processing then add according to chomp
        trailing=0
        while texts and texts[-1]=="":
            trailing+=1; texts.pop()
        if style=="|":
            body="\n".join(texts)
            if texts:
                if chomp=="-": pass
                elif chomp=="+": body+="\n"+"\n"*trailing
                else: body+="\n"
            else:
                body=""
        else: # folded >
            # fold single newlines to space, blank lines to newline
            out=[]
            for i,t in enumerate(texts):
                if t=="":
                    out.append("\n")
                else:
                    if i>0 and texts[i-1]!="" :
                        out.append(" ")
                    elif i>0 and texts[i-1]=="" and out and not out[-1].endswith("\n"):
                        out.append("\n")
                    out.append(t)
            body="".join(out)
            if texts:
                if chomp=="-": pass
                elif chomp=="+": body+="\n"+"\n"*trailing
                else: body+="\n"
            else:
                body=""
        return YScalar(body, "literal" if style=="|" else "folded", line_num, col)

def find_mapping_colon(s):
    # returns index of ':' that separates key, plain keys; colon must be followed by space or Eol (or for flow?) in block context
    i=0; depth=0; quote=None
    while i<len(s):
        ch=s[i]
        if quote:
            if quote=="'":
                if ch=="'":
                    if i+1<len(s) and s[i+1]=="'": i+=2; continue
                    quote=None
            elif quote=='"':
                if ch=='\\': i+=2; continue
                if ch=='"': quote=None
            i+=1; continue
        if ch in "'\"": quote=ch; i+=1; continue
        if ch in "[{": depth+=1
        elif ch in "]}": depth-=1
        elif ch==':' and depth==0:
            if i+1>=len(s) or s[i+1] in " \t":
                return i
            # colon within plain scalar like a:b not mapping
        elif ch=='#' and i>0 and s[i-1] in " \t":
            return -1
        i+=1
    return -1

def flow_balanced(s):
    depth=0; quote=None; i=0
    while i<len(s):
        ch=s[i]
        if quote:
            if quote=="'":
                if ch=="'":
                    if i+1<len(s) and s[i+1]=="'": i+=2; continue
                    quote=None
            else:
                if ch=='\\': i+=2; continue
                if ch=='"': quote=None
            i+=1; continue
        if ch in "'\"": quote=ch
        elif ch in "[{": depth+=1
        elif ch in "]}": depth-=1
        i+=1
    return depth<=0 and quote is None

def parse_quoted(s, i, line_num, col):
    q=s[i]; start_col=col+i
    if q=="'":
        out=[]; j=i+1
        while j<len(s):
            ch=s[j]
            if ch=="'":
                if j+1<len(s) and s[j+1]=="'": out.append("'"); j+=2; continue
                return YScalar("".join(out),"single",line_num,start_col,end_col=start_col+(j-i)+1), j+1
            out.append(ch); j+=1
        raise YamlError("unterminated quoted string")
    else:
        out=[]; j=i+1
        while j<len(s):
            ch=s[j]
            if ch=='"':
                return YScalar("".join(out),"double",line_num,start_col,end_col=start_col+(j-i)+1), j+1
            if ch=='\\':
                if j+1>=len(s): break
                e=s[j+1]
                mapping={'0':'\0','a':'\a','b':'\b','t':'\t','\t':'\t','n':'\n','v':'\v','f':'\f','r':'\r','e':'\x1b',' ':' ','"':'"','/':'/','\\':'\\','N':'\x85','_':'\xa0'}
                if e in mapping: out.append(mapping[e]); j+=2; continue
                if e=='x':
                    out.append(chr(int(s[j+2:j+4],16))); j+=4; continue
                if e=='u':
                    out.append(chr(int(s[j+2:j+6],16))); j+=6; continue
                if e=='U':
                    out.append(chr(int(s[j+2:j+10],16))); j+=10; continue
                if e=='\n': j+=2; continue
                out.append(e); j+=2; continue
            out.append(ch); j+=1
        raise YamlError("unterminated quoted string")

class FlowParser:
    def __init__(self,s,line_num,col,parser):
        self.s=s; self.line=line_num; self.col=col; self.parser=parser
    def pos_info(self, idx):
        before=self.s[:idx]
        lines=before.split("\n")
        if len(lines)==1: return self.line, self.col+idx
        return self.line+len(lines)-1, len(lines[-1])+1
    def skip_ws(self,i):
        while i<len(self.s):
            if self.s[i] in " \t\n": i+=1; continue
            if self.s[i]=='#':
                while i<len(self.s) and self.s[i]!='\n': i+=1
                continue
            break
        return i
    def parse_value(self,i):
        i=self.skip_ws(i)
        if i>=len(self.s):
            line,col=self.pos_info(i); return YScalar("","plain",line,col), i
        # anchor/tag
        anchor=None; tag=None
        while i<len(self.s) and self.s[i] in "&!":
            if self.s[i]=='&':
                m=re.match(r'&([^\s\[\]{},]+)',self.s[i:]); anchor=m.group(1); i+=len(m.group(0)); i=self.skip_ws(i)
            else:
                m=re.match(r'(!{1,2}[^\s\[\]{},]*)',self.s[i:]); tag=m.group(1); i+=len(m.group(0)); i=self.skip_ws(i)
        line,col=self.pos_info(i)
        ch=self.s[i] if i<len(self.s) else ""
        if ch=="*":
            m=re.match(r'\*([^\s\[\]{},]+)',self.s[i:]); name=m.group(1)
            if name not in self.parser.anchors:
                raise YamlError(f"unknown anchor at line {line} column {col}")
            return self.parser.anchors[name], i+len(m.group(0))
        if ch=="[":
            items=[]; i+=1
            while True:
                i=self.skip_ws(i)
                if i>=len(self.s):
                    raise YamlError(f"did not find expected ',' or ']' at line {self.pos_info(i)[0]} column {self.pos_info(i)[1]}, while parsing a flow sequence")
                if self.s[i]=="]": i+=1; break
                val,i=self.parse_flow_node(i)
                items.append(val)
                i=self.skip_ws(i)
                if i<len(self.s) and self.s[i]==",": i+=1; continue
                if i<len(self.s) and self.s[i]=="]": continue
                if i>=len(self.s):
                    raise YamlError(f"did not find expected ',' or ']' at line {self.pos_info(i)[0]} column {self.pos_info(i)[1]}, while parsing a flow sequence")
                # error
                el,ec=self.pos_info(i); raise YamlError(f"did not find expected ',' or ']' at line {el} column {ec}, while parsing a flow sequence")
            node=YSeq(items,line,col,True)
        elif ch=="{":
            pairs=[]; i+=1
            while True:
                i=self.skip_ws(i)
                if i>=len(self.s):
                    el,ec=self.pos_info(i); raise YamlError(f"did not find expected ',' or '}}' at line {el} column {ec}, while parsing a flow mapping")
                if self.s[i]=="}": i+=1; break
                key,i=self.parse_flow_node(i, in_key=True)
                i=self.skip_ws(i)
                if i<len(self.s) and self.s[i]==":":
                    i+=1; val,i=self.parse_flow_node(i)
                else:
                    # key with null value? In yaml flow {a} means {a: null}
                    kl,kc=self.pos_info(i); val=YScalar("","plain",kl,kc)
                pairs.append((key,val))
                i=self.skip_ws(i)
                if i<len(self.s) and self.s[i]==",": i+=1; continue
                if i<len(self.s) and self.s[i]=="}": continue
                if i>=len(self.s):
                    el,ec=self.pos_info(i); raise YamlError(f"did not find expected ',' or '}}' at line {el} column {ec}, while parsing a flow mapping")
                el,ec=self.pos_info(i); raise YamlError(f"did not find expected ',' or '}}' at line {el} column {ec}, while parsing a flow mapping")
            el,ec=self.pos_info(i-1)
            node=YMap(pairs,line,col,True,end_line=el,end_col=ec)
        elif ch in "'\"":
            node,i=parse_quoted(self.s,i,line,col)
        else:
            # plain scalar until , ] } or : in key
            start=i
            while i<len(self.s):
                c=self.s[i]
                if c in ",]}": break
                if c=='#' and i>start and self.s[i-1] in " \t": break
                i+=1
            text=self.s[start:i].strip()
            # Note if scalar contained colon for map (in_key handled by parse_flow_node)
            node=YScalar(text,"plain",line,col,end_col=col+(i-start))
        if tag and isinstance(node,YScalar): node.tag=tag
        if anchor: self.parser.anchors[anchor]=node
        return node,i
    def parse_flow_node(self,i,in_key=False):
        # if in_key, plain scalar ends at ':' followed by space/comma etc
        i0=self.skip_ws(i)
        if i0<len(self.s) and self.s[i0] not in "[{'\"&!*":
            # scan plain, but need detect colon
            start=i0; j=i0
            # anchor handling above omitted for keys rare
            while j<len(self.s):
                c=self.s[j]
                if c in ",]}": break
                if in_key and c==":" and (j+1>=len(self.s) or self.s[j+1] in " \t,]}"): break
                if (not in_key) and c==":" and (j+1<len(self.s) and self.s[j+1] in " \t"):
                    # This would be a nested mapping in flow value? Plain scalar in flow cannot contain ': ' – treat as error context but for our messages values like args strings no
                    break
                j+=1
            line,col=self.pos_info(start)
            text=self.s[start:j].strip()
            # check if text contains ': ' in non-key: if so above break leaves colon handling caller? For our usage may be scalar with colon no space only.
            return YScalar(text,"plain",line,col,end_col=col+len(self.s[start:j].rstrip())), j
        return self.parse_value(i)

def parse_yaml(text):
    return Parser(text).parse()

# YAML emitter à la serde_yaml
def _needs_quote(s):
    if s=="": return True
    if s!=s.strip(): return True
    if s in ("null","Null","NULL","~","true","True","TRUE","false","False","FALSE"): return True
    # numbers
    if resolve_plain_scalar(s) is not None and not isinstance(resolve_plain_scalar(s),str): return True
    # Special leading chars
    if s[0] in "-?:,[]{}#&*!|>'\"%@`": 
        # '-' followed by space etc, '?' similar, ':' etc. serde_yaml conservatively quotes many single-char keys like ':' '?'
        return True
    if ": " in s or s.endswith(":") or " #" in s: return True
    if "\n" in s or "\t" in s: return True
    # control / nonprintable
    for ch in s:
        if ord(ch)<0x20 or ord(ch)==0x7f: return True
    return False

def _quote(s):
    # serde_yaml uses single quotes when needing quoting (mostly), double quotes for strings with special escapes/newlines
    if "\n" in s or "\t" in s or any(ord(c)<0x20 or ord(c)==0x7f for c in s):
        out='"'
        for ch in s:
            if ch=='"': out+='\\"'
            elif ch=='\\': out+='\\\\'
            elif ch=='\n': out+='\\n'
            elif ch=='\t': out+='\\t'
            elif ch=='\r': out+='\\r'
            elif ord(ch)<0x20 or ord(ch)==0x7f: out+=f"\\x{ord(ch):02X}"
            else: out+=ch
        return out+'"'
    return "'" + s.replace("'","''") + "'"

def scalar_to_yaml(v):
    if v is None: return "null"
    if v is True: return "true"
    if v is False: return "false"
    if isinstance(v,int): return str(v)
    if isinstance(v,float):
        if v!=v: return ".nan"
        if v==float('inf'): return ".inf"
        if v==float('-inf'): return "-.inf"
        # serde_yaml formats with ryu, ensures decimal?
        r=repr(float(v))
        return r
    s=str(v)
    return _quote(s) if _needs_quote(s) else s

