    if isinstance(node, YScalar):
        if node.tag in ("!!str","tag:yaml.org,2002:str"):
            return node.value
        if node.style=="plain":
            return resolve_plain_scalar(node.value)
        return node.value
    if isinstance(node,YSeq):
        return [generic_value(x) for x in node.items]
    if isinstance(node,YMap):
        d={}
        for k,v in node.pairs:
            gv=generic_value(v)
            gk=generic_value(k)
            # JSON keys must be strings; serde_yaml Value Mapping keys can be non-string, converting to JSON via serde may stringify in jf?
            # Keep as string representation for boolean/null/number keys like serde_json Map conversion would fail? Rare.
            if isinstance(gk,bool): key="true" if gk else "false"
            elif gk is None: key="null"
            elif isinstance(gk,(list,dict)): key=str(gk)
            else: key=gk if isinstance(gk,str) else str(gk)
            d[key]=gv
