def find_mapping_colon(s):
    # returns index of ':' that separates key, plain keys; colon must be followed by space or Eol (or for flow?) in block context
    i=0; depth=0; quote=None
    while i<len(s):
        ch=s[i]
        if quote:
            if quote=="'":
                if ch=="'":
                    if i+1<len(s) and s[i+1]=="'": i+=2; continue
                    quote=None
            elif quote=='"':
                if ch=='\\': i+=2; continue
                if ch=='"': quote=None
            i+=1; continue
        if ch in "'\"": quote=ch; i+=1; continue
        if ch in "[{": depth+=1
        elif ch in "]}": depth-=1
        elif ch==':' and depth==0:
            if i+1>=len(s) or s[i+1] in " \t":
                return i
            # colon within plain scalar like a:b not mapping
        elif ch=='#' and i>0 and s[i-1] in " \t":
            return -1
        i+=1
    return -1

def flow_balanced(s):
    depth=0; quote=None; i=0
    while i<len(s):
        ch=s[i]
        if quote:
            if quote=="'":
                if ch=="'":
                    if i+1<len(s) and s[i+1]=="'": i+=2; continue
                    quote=None
            else:
                if ch=='\\': i+=2; continue
                if ch=='"': quote=None
            i+=1; continue
        if ch in "'\"": quote=ch
        elif ch in "[{": depth+=1
        elif ch in "]}": depth-=1
        i+=1
    return depth<=0 and quote is None

def parse_quoted(s, i, line_num, col):
    q=s[i]; start_col=col+i
    if q=="'":
