    return Parser(text).parse()

# YAML emitter à la serde_yaml
def _needs_quote(s):
    if s=="": return True
    if s!=s.strip(): return True
    if s in ("null","Null","NULL","~","true","True","TRUE","false","False","FALSE"): return True
    # numbers
    if resolve_plain_scalar(s) is not None and not isinstance(resolve_plain_scalar(s),str): return True
    # Special leading chars
    if s[0] in "-?:,[]{}#&*!|>'\"%@`": 
        # '-' followed by space etc, '?' similar, ':' etc. serde_yaml conservatively quotes many single-char keys like ':' '?'
        return True
    if ": " in s or s.endswith(":") or " #" in s: return True
    if "\n" in s or "\t" in s: return True
    # control / nonprintable
    for ch in s:
        if ord(ch)<0x20 or ord(ch)==0x7f: return True
    return False

def _quote(s):
    # serde_yaml uses single quotes when needing quoting (mostly), double quotes for strings with special escapes/newlines
    if "\n" in s or "\t" in s or any(ord(c)<0x20 or ord(c)==0x7f for c in s):
        out='"'
        for ch in s:
            if ch=='"': out+='\\"'
            elif ch=='\\': out+='\\\\'
            elif ch=='\n': out+='\\n'
            elif ch=='\t': out+='\\t'
            elif ch=='\r': out+='\\r'
            elif ord(ch)<0x20 or ord(ch)==0x7f: out+=f"\\x{ord(ch):02X}"
            else: out+=ch
        return out+'"'
    return "'" + s.replace("'","''") + "'"

def scalar_to_yaml(v):
    if v is None: return "null"
    if v is True: return "true"
    if v is False: return "false"
    if isinstance(v,int): return str(v)
    if isinstance(v,float):
        if v!=v: return ".nan"
        if v==float('inf'): return ".inf"
        if v==float('-inf'): return "-.inf"
        # serde_yaml formats with ryu, ensures decimal?
        r=repr(float(v))
        return r
    s=str(v)
    return _quote(s) if _needs_quote(s) else s

def to_yaml(value, indent=0):
    lines=[]
    _emit(value, indent, lines, top=True)
    return "\n".join(lines)+"\n" if lines else ""

def _emit(v, indent, lines, top=False, key_prefix=None):
    pad=" "*indent
    if isinstance(v, dict):
        if not v:
            lines.append(pad+(key_prefix or "")+"{}"); return
        if key_prefix is not None:
            lines.append(pad+key_prefix.rstrip())
            # Actually caller handles; this path unused
        for k,val in v.items():
            ks=scalar_to_yaml(k) if isinstance(k,str) else scalar_to_yaml(k)
            if isinstance(val, dict):
                if not val: lines.append(f"{pad}{ks}: {{}}")
                else:
                    lines.append(f"{pad}{ks}:")
                    _emit(val, indent+2, lines)
            elif isinstance(val, (list,tuple)):
                if not val: lines.append(f"{pad}{ks}: []")
                else:
                    lines.append(f"{pad}{ks}:")
                    _emit_list(val, indent, lines)  # serde_yaml lists indent at same level as key
            else:
                lines.append(f"{pad}{ks}: {scalar_to_yaml(val)}")
    elif isinstance(v,(list,tuple)):
        _emit_list(v,indent,lines)
    else:
        lines.append(pad+scalar_to_yaml(v))

def _emit_list(lst, indent, lines):
    pad=" "*indent
    for item in lst:
        if isinstance(item,dict):
            if not item: lines.append(f"{pad}- {{}}"); continue
            first=True
            for k,val in item.items():
                ks=scalar_to_yaml(k)
                prefix=f"{pad}- " if first else f"{pad}  "
                first=False
                if isinstance(val,dict):
                    if not val: lines.append(f"{prefix}{ks}: {{}}")
                    else:
                        lines.append(f"{prefix}{ks}:")
                        _emit(val, indent+4, lines)
                elif isinstance(val,(list,tuple)):
                    if not val: lines.append(f"{prefix}{ks}: []")
                    else:
                        lines.append(f"{prefix}{ks}:")
                        _emit_list(val, indent+2, lines)
                else:
                    lines.append(f"{prefix}{ks}: {scalar_to_yaml(val)}")
        elif isinstance(item,(list,tuple)):
            if not item: lines.append(f"{pad}- []")
            else:
                # nested list: serde gives "- - item" style? Approximation
                sub=[]
                _emit_list(item, indent+2, sub)
                if sub:
                    lines.append(f"{pad}- {sub[0].strip() if False else ''}".rstrip())
                    # simpler: first sub line replace leading pad
                    # redo:
                    lines.pop()
                    for j,sl in enumerate(sub):
                        if j==0:
                            lines.append(f"{pad}- "+sl[indent+2:])
                        else:
                            lines.append(sl)
        else:
            lines.append(f"{pad}- {scalar_to_yaml(item)}")
