import re

class YamlError(Exception):
    pass

class YScalar:
    __slots__=("value","style","line","col","end_line","end_col","tag","raw")
    def __init__(self,value,style="plain",line=1,col=1,end_line=None,end_col=None,tag=None,raw=None):
        self.value=value; self.style=style; self.line=line; self.col=col
        self.end_line=end_line if end_line is not None else line
        self.end_col=end_col if end_col is not None else col
        self.tag=tag; self.raw=value if raw is None else raw
    def __repr__(self): return f"YScalar({self.value!r},{self.style})"
class YSeq:
    __slots__=("items","line","col","flow")
    def __init__(self,items,line=1,col=1,flow=False): self.items=items; self.line=line; self.col=col; self.flow=flow
    def __repr__(self): return f"YSeq({self.items!r})"
class YMap:
    __slots__=("pairs","line","col","flow","end_line","end_col")
    def __init__(self,pairs,line=1,col=1,flow=False,end_line=None,end_col=None): self.pairs=pairs; self.line=line; self.col=col; self.flow=flow; self.end_line=end_line; self.end_col=end_col
    def __repr__(self): return f"YMap({self.pairs!r})"

# Helpers for serde_yaml-like plain scalar resolution
_INT_RE=re.compile(r'^(?:[-+]?[0-9]+|0x[0-9a-fA-F]+|0o[0-7]+|0b[01]+)$')
def resolve_plain_scalar(text):
    if text in ("", "~", "null", "Null", "NULL"):
        return None
    if text in ("true","True","TRUE"): return True
    if text in ("false","False","FALSE"): return False
    # integers, excluding leading zero decimals with length>1 (01, 007)
    if _INT_RE.match(text):
        # decimal leading zero check
        t=text
        sign=1
        if t[0] in "+-":
            if t[0]=='-': sign=-1
            t2=t[1:]
        else:
            t2=t
        if re.match(r'^0[0-9]+$', t2):
            return text
        try:
            if t2.startswith("0x"): return sign*int(t2[2:],16)
            if t2.startswith("0o"): return sign*int(t2[2:],8)
            if t2.startswith("0b"): return sign*int(t2[2:],2)
            return int(text)
        except Exception:
            return text
    # floats
    low=text.lower()
    if low in (".inf","+.inf"): return float("inf")
    if low=="-.inf": return float("-inf")
    if low in (".nan",): return float("nan")
    if re.match(r'^[-+]?(?:[0-9]+\.[0-9]*|\.[0-9]+|[0-9]+)(?:[eE][-+]?[0-9]+)?$', text) and ('.' in text or 'e' in text or 'E' in text):
        # leading zero like 01.0 ? serde-yaml probably floats; allow
        try: return float(text)
        except Exception: return text
    return text

def generic_value(node):
    if isinstance(node, YScalar):
        if node.tag in ("!!str","tag:yaml.org,2002:str"):
            return node.value
        if node.style=="plain":
            return resolve_plain_scalar(node.value)
        return node.value
    if isinstance(node,YSeq):
        return [generic_value(x) for x in node.items]
    if isinstance(node,YMap):
        d={}
        for k,v in node.pairs:
            gv=generic_value(v)
            gk=generic_value(k)
            # JSON keys must be strings; serde_yaml Value Mapping keys can be non-string, converting to JSON via serde may stringify in jf?
            # Keep as string representation for boolean/null/number keys like serde_json Map conversion would fail? Rare.
            if isinstance(gk,bool): key="true" if gk else "false"
            elif gk is None: key="null"
            elif isinstance(gk,(list,dict)): key=str(gk)
            else: key=gk if isinstance(gk,str) else str(gk)
            d[key]=gv
        return d
    return node

def _strip_comment_plain(s):
    # remove ' #...' comment in plain context
    i=0
    while i < len(s):
        if s[i]=='#' and i>0 and s[i-1] in ' \t':
            return s[:i].rstrip()
        i+=1
    return s

class _Line:
    __slots__=("text","num")
    def __init__(self,text,num): self.text=text; self.num=num
    @property
    def indent(self):
        n=0
        for ch in self.text:
            if ch==' ': n+=1
            elif ch=='\t': n+=1
            else: break
        return n
    @property
    def stripped(self): return self.text.strip()
    @property
    def content(self): return self.text[self.indent:]

class Parser:
    def __init__(self, text):
        # control characters check as in libyaml
        for i,ch in enumerate(text):
            o=ord(ch)
            if (o<0x20 and ch not in "\n\t\r") or o==0x7f:
                raise YamlError(f"control characters are not allowed at position {i}")
        # Normalize CRLF
        text=text.replace("\r\n","\n").replace("\r","\n")
        self.raw_lines=text.split("\n")
        self.lines=[_Line(t,i+1) for i,t in enumerate(self.raw_lines)]
        self.pos=0
        self.anchors={}

    def error(self,msg,line=None,col=None):
        if line is not None:
            raise YamlError(f"{msg} at line {line} column {col}")
        raise YamlError(msg)

    def peek(self):
        while self.pos < len(self.lines):
            l=self.lines[self.pos]
            if l.stripped=="" or l.stripped.startswith("#"):
                self.pos+=1; continue
            return l
        return None

    def parse(self):
        # directives
        l=self.peek()
        if l is None:
            return YScalar("", "plain", 1,1)
        if l.content.startswith("%"):
            # directive
            name=l.content[1:].split()[0] if len(l.content)>1 else ""
