                else:
                    items.append(self.parse_block(nl.indent))
            elif find_mapping_colon(after)>=0 and not after.startswith(("{","[","'",'"')):
                # inline map starting on this line, treat as a map with first key here and subsequent keys at content_col indent
                # insert virtual line
                virtual=_Line(" "*content_col+after, l.num)
                self.lines.insert(self.pos, virtual)
                items.append(self.parse_block_map(content_col, first_virtual=True))
            else:
