    def parse_block_map(self, indent, first_virtual=False):
        start=self.peek(); start_line=start.num; start_col=indent+1
        pairs=[]
        while True:
            l=self.peek()
            if l is None: break
            if l.indent!=indent: break
            c=l.content
            if c=="-" or c.startswith("- "): break
