    def parse_inline_or_scalar(self, text, line_num, col, current_line_indent=0, scalar_block_first=False):
        # anchors/tags prefix
        anchor=None; tag=None
        orig_text=text
        while True:
            if text.startswith("&"):
                m=re.match(r'&([^\s\[\]{},]+)\s*(.*)$', text, re.S)
