SORTERS=["ByRelativePath","ByIRelativePath","ByExtension","ByIsDir","ByIsFile","ByIsSymlink","ByIsBroken","ByIsReadonly","ByMimeEssence","BySize","ByCreated","ByLastModified","ByCanonicalAbsolutePath","ByICanonicalAbsolutePath","ByCanonicalExtension","ByCanonicalIsDir","ByCanonicalIsFile","ByCanonicalIsReadonly","ByCanonicalMimeEssence","ByCanonicalSize","ByCanonicalCreated","ByCanonicalLastModified","BySymlinkAbsolutePath","ByISymlinkAbsolutePath","BySymlinkExtension","BySymlinkIsDir","BySymlinkIsFile","BySymlinkIsReadonly","BySymlinkMimeEssence","BySymlinkSize","BySymlinkCreated","BySymlinkLastModified"]
INPUT_OPS_UNIT=["GoToPreviousCharacter","GoToNextCharacter","GoToPreviousWord","GoToNextWord","GoToStart","GoToEnd","DeletePreviousCharacter","DeleteNextCharacter","DeletePreviousWord","DeleteNextWord","DeleteLine","DeleteTillEnd"]
INPUT_OPS_ALL=["SetCursor","InsertCharacter"]+INPUT_OPS_UNIT

STRING_VARIANTS={
"FocusPath","FocusByFileName","ChangeDirectory","SetVroot","SetInputPrompt","BufferInput","SetInputBuffer",
"SwitchMode","SwitchModeKeepingInputBuffer","SwitchModeBuiltin","SwitchModeBuiltinKeepingInputBuffer","SwitchModeCustom","SwitchModeCustomKeepingInputBuffer",
"SwitchLayout","SwitchLayoutBuiltin","SwitchLayoutCustom",
"BashExec","BashExec0","BashExecSilently","BashExecSilently0","CallLua","CallLuaSilently","LuaEval","LuaEvalSilently",
"SelectPath","UnSelectPath","ToggleSelectionByPath",
"Search","SearchFuzzy","SearchFuzzyUnordered","SearchRegex","SearchRegexUnordered",
"StartFifo","ToggleFifo","LogInfo","LogSuccess","LogWarning","LogError","Debug"}
USIZE_VARIANTS={"FocusNextByRelativeIndex","FocusPreviousByRelativeIndex","FocusByIndex"}
COMMAND_VARIANTS={"Call","Call0","CallSilently","CallSilently0"}
FILTER_STRUCT_VARIANTS={"AddNodeFilter","RemoveNodeFilter","ToggleNodeFilter"}
FILTER_ENUM_VARIANTS={"AddNodeFilterFromInput","RemoveNodeFilterFromInput"}
SORTER_STRUCT_VARIANTS={"AddNodeSorter","ToggleNodeSorter"}
SORTER_ENUM_VARIANTS={"RemoveNodeSorter","ReverseNodeSorter"}
UNIT_VARIANTS=[v for v in VARIANTS if v not in STRING_VARIANTS and v not in USIZE_VARIANTS and v not in COMMAND_VARIANTS and v not in FILTER_STRUCT_VARIANTS and v not in FILTER_ENUM_VARIANTS and v not in SORTER_STRUCT_VARIANTS and v not in SORTER_ENUM_VARIANTS and v!="UpdateInputBuffer"]

def variants_list_str(variants):
    return ", ".join(f"`{v}`" for v in variants)

class MsgError(Exception):
    pass

def unexpected_str(v):
    # serde Unexpected display for generic JSON values
    if v is None: return "null"
    if isinstance(v,bool): return f"boolean `{'true' if v else 'false'}`"
    if isinstance(v,int): return f"integer `{v}`"
    if isinstance(v,float): return f"floating point `{format_float(v)}`"
    if isinstance(v,str): return f'string "{v}"'
    if isinstance(v,list): return "sequence"
    if isinstance(v,dict): return "map"
    return str(v)

def format_float(v):
    if v!=v: return "NaN"
    if v==float('inf'): return "inf"
    if v==float('-inf'): return "-inf"
    r=repr(float(v))
    return r

# ---------- YAML direct validation helpers ----------
def y_node_type_unexpected(node):
    if isinstance(node,YSeq): return "sequence"
    if isinstance(node,YMap): return "map"
    # scalar: resolved type for plain, quoted are strings
    if node.style!="plain":
        return f'string "{node.value}"'
    g=resolve_plain_scalar(node.value)
    if isinstance(g,str): return f'string "{g}"'
    return unexpected_str(g)

def y_err(path,msg,node=None):
    prefix=f"{path}: " if path else ""
    if node is not None and hasattr(node,'line'):
        raise MsgError(f"{prefix}{msg} at line {node.line} column {node.col}")
    raise MsgError(f"{prefix}{msg}")

def y_scalar_string(node,path,expected="a string"):
    if isinstance(node,YScalar):
        # serde_yaml -> String uses raw scalar content regardless plain type resolution
        return node.value
    y_err(path,f"invalid type: {y_node_type_unexpected(node)}, expected {expected}",node)

def y_scalar_bool(node,path):
    if isinstance(node,YScalar) and node.style=="plain":
        if node.value in ("true","True","TRUE"): return True
        if node.value in ("false","False","FALSE"): return False
        g=resolve_plain_scalar(node.value)
        y_err(path,f"invalid type: {unexpected_str(g) if not isinstance(g,str) else f'string \"{g}\"'}, expected a boolean",node)
    if isinstance(node,YScalar):
        y_err(path,f'invalid type: string "{node.value}", expected a boolean',node)
    y_err(path,f"invalid type: {y_node_type_unexpected(node)}, expected a boolean",node)

def y_scalar_usize(node,path):
    if isinstance(node,YScalar):
        if node.style!="plain":
            y_err(path,f'invalid type: string "{node.value}", expected usize',node)
        g=resolve_plain_scalar(node.value)
        if isinstance(g,int) and not isinstance(g,bool):
            if g>=0: return g
            y_err(path,f"invalid type: integer `{g}`, expected usize",node)
        if isinstance(g,float):
            y_err(path,f"invalid type: floating point `{format_float(g)}`, expected usize",node)
        if isinstance(g,bool):
            y_err(path,f"invalid type: boolean `{'true' if g else 'false'}`, expected usize",node)
        if g is None:
            y_err(path,f"invalid type: null, expected usize",node)
        y_err(path,f'invalid type: string "{node.value}", expected usize',node)
    y_err(path,f"invalid type: {y_node_type_unexpected(node)}, expected usize",node)

def y_scalar_char(node,path):
    if isinstance(node,YScalar):
        s=node.value
        if len(s)==1: return s
        # serde_yaml: invalid value: string "...", expected a character
        y_err(path,f'invalid value: string "{s}", expected a character',node)
    y_err(path,f"invalid type: {y_node_type_unexpected(node)}, expected a character",node)

def y_enum(node,path,variants, enum_name=None):
    if isinstance(node,YScalar):
        # Enum identifier in serde_yaml: if plain resolved non-string -> invalid type expected enum X
        if node.style=="plain":
            g=resolve_plain_scalar(node.value)
            if not isinstance(g,str):
                exp=f"enum {enum_name}" if enum_name else "variant identifier"
                y_err(path,f"invalid type: {unexpected_str(g)}, expected {exp}",node)
        s=node.value
        if s in variants: return s
        # unknown variant - nested paths usually have position, top-level filters? For scalar node in struct use pos
        y_err(path,f"unknown variant `{s}`, expected one of {variants_list_str(variants)}",node)
    # map /seq
    if isinstance(node,YSeq):
        y_err(path,"invalid type: sequence, expected variant identifier",node)
    y_err(path,f"invalid type: {y_node_type_unexpected(node)}, expected variant identifier",node)

def y_map_pairs(node,path, struct_name):
    if not isinstance(node,YMap):
        y_err(path,f"invalid type: {y_node_type_unexpected(node)}, expected struct {struct_name}",node)
    return node

def y_struct_fields(node,path,struct_name, allowed):
    y_map_pairs(node,path,struct_name)
    out={}
    for k,v in node.pairs:
        if not isinstance(k,YScalar):
            y_err(path,f"invalid type: {y_node_type_unexpected(k)}, expected field identifier",k)
        ks=k.value
        if ks not in allowed:
            exp = " or ".join(f"`{a}`" for a in allowed) if len(allowed)<=2 else ", ".join(f"`{a}`" for a in allowed[:-1])+f", or `{allowed[-1]}`"
            # serde presence format for 2: expected `a` or `b`; for >2 check later
            # Rust serde expected format uses "expected one of ..." for ??? Struct unknown field in serde_yaml observed: expected `command` or `args`
            y_err(path,f"unknown field `{ks}`, expected {exp}",k)
        out[ks]=v
    return out

def validate_from_yaml_node(node):
    # returns canonical msg representation str or dict
    # scalar top-level
    if isinstance(node,YScalar):
        if node.style=="plain" and node.value=="":
            raise MsgError("invalid type: Option value, expected enum ExternalMsg")
        if node.style=="plain":
            g=resolve_plain_scalar(node.value)
            if not isinstance(g,str):
                raise MsgError(f"invalid type: {unexpected_str(g)}, expected enum ExternalMsg")
        name=node.value
        if name not in VARIANTS:
            raise MsgError(f"unknown variant `{name}`, expected one of {variants_list_str(VARIANTS)}")
        if name in UNIT_VARIANTS:
            return name
        raise MsgError("invalid type: unit variant, expected newtype variant")
    if isinstance(node,YSeq):
        raise MsgError("invalid type: sequence, expected enum ExternalMsg")
    if isinstance(node,YMap):
        if len(node.pairs)==0:
            raise MsgError("invalid value: map, expected map with a single key")
        # serde_yaml externally tagged: first key determines variant even if map incomplete syntax had
        k,v=node.pairs[0]
        if not isinstance(k,YScalar):
            raise MsgError(f"invalid type: {y_node_type_unexpected(k)}, expected variant identifier")
        # key scalar resolved non-string?
        name=k.value
        if k.style=="plain":
            g=resolve_plain_scalar(name)
            if not isinstance(g,str):
                raise MsgError(f"invalid type: {unexpected_str(g)}, expected variant identifier")
        if name not in VARIANTS:
            raise MsgError(f"unknown variant `{name}`, expected one of {variants_list_str(VARIANTS)}")
        if len(node.pairs)!=1:
            # serde_yaml for yaml maps: unit variant check happens first? Test multi-map FocusPath etc? approximate:
            if name in UNIT_VARIANTS:
                raise MsgError("invalid type: map, expected unit variant")
            raise MsgError("invalid value: map, expected map with a single key")
        if name in UNIT_VARIANTS:
            raise MsgError("invalid type: map, expected unit variant")
        payload=validate_payload_yaml(name,v)
        return {name:payload}
    raise MsgError("invalid type, expected enum ExternalMsg")

def validate_payload_yaml(name, v):
    path=name
    if name in STRING_VARIANTS:
        return y_scalar_string(v,path)
    if name in USIZE_VARIANTS:
        return y_scalar_usize(v,path)
    if name in COMMAND_VARIANTS:
        fields=y_struct_fields(v,path,"Command",["command","args"])
        if "command" not in fields:
            # column points map start
            y_err(path,"missing field `command`",v)
        cmd=y_scalar_string(fields["command"],path+".command")
        out={"command":cmd}
        if "args" in fields:
            args_node=fields["args"]
            if not isinstance(args_node,YSeq):
                y_err(path+".args",f"invalid type: {y_node_type_unexpected(args_node)}, expected a sequence",args_node)
            out["args"]=[y_scalar_string(x,path+".args") for x in args_node.items]
        return out
    if name in FILTER_STRUCT_VARIANTS:
        fields=y_struct_fields(v,path,"NodeFilterApplicableDeserializer",["filter","input"])
        for req in ("filter","input"):
            if req not in fields: y_err(path,f"missing field `{req}`",v)
        return {"filter":y_enum(fields["filter"],path+".filter",FILTERS), "input":y_scalar_string(fields["input"],path+".input")}
    if name in FILTER_ENUM_VARIANTS:
        return y_enum(v,path,FILTERS)
    if name in SORTER_STRUCT_VARIANTS:
        fields=y_struct_fields(v,path,"NodeSorterApplicable",["sorter","reverse"])
        if "sorter" not in fields: y_err(path,"missing field `sorter`",v)
        out={"sorter":y_enum(fields["sorter"],path+".sorter",SORTERS)}
        if "reverse" in fields: out["reverse"]=y_scalar_bool(fields["reverse"],path+".reverse")
        return out
    if name in SORTER_ENUM_VARIANTS:
        return y_enum(v,path,SORTERS, enum_name="NodeSorter")
    if name=="UpdateInputBuffer":
        return validate_input_op_yaml(v,path)
    raise MsgError(f"unhandled variant {name}")

def validate_input_op_yaml(v,path):
    if isinstance(v,YScalar):
        if v.style=="plain":
            g=resolve_plain_scalar(v.value)
            if not isinstance(g,str):
                y_err(path,f"invalid type: {unexpected_str(g)}, expected enum InputOperation",v)  # approx
        s=v.value
        if s not in INPUT_OPS_ALL:
            y_err(path,f"unknown variant `{s}`, expected one of {variants_list_str(INPUT_OPS_ALL)}",v)
        if s in INPUT_OPS_UNIT:
            return s
        raise MsgError("invalid type: unit variant, expected newtype variant")
    if isinstance(v,YMap):
        if len(v.pairs)!=1:
            y_err(path,"invalid value: map, expected map with a single key",v)
        k,val=v.pairs[0]; name=k.value if isinstance(k,YScalar) else None
        if name not in INPUT_OPS_ALL:
            y_err(path,f"unknown variant `{name}`, expected one of {variants_list_str(INPUT_OPS_ALL)}",k)
        if name in INPUT_OPS_UNIT:
            raise MsgError("invalid type: map, expected unit variant")
        if name=="SetCursor":
            return {"SetCursor": y_scalar_usize(val,path+".SetCursor")}
        if name=="InsertCharacter":
            return {"InsertCharacter": y_scalar_char(val,path+".InsertCharacter")}
    if isinstance(v,YSeq):
        y_err(path,"invalid type: sequence, expected variant identifier",v)
    y_err(path,f"invalid type: {y_node_type_unexpected(v)}, expected variant identifier",v)

# ---------- JSON validation (for -m) ----------
class JNode:
    __slots__=("value","start","end","kind","children")
    def __init__(self,value,start,end,kind,children=None): self.value=value; self.start=start; self.end=end; self.kind=kind; self.children=children or {}

def parse_json_nodes(text):
    # Use json decoder with object_pairs_hook impossible positions; write tiny parser
    i=0
    def skip(i):
        while i<len(text) and text[i] in " \t\n\r": i+=1
        return i
    def parse_val(i):
        i=skip(i); start=i
        if i>=len(text): raise MsgError("expected value at line 1 column 1")
        ch=text[i]
        if ch=='"':
            # find using json decoder raw_decode
            val,end=json.JSONDecoder().raw_decode(text,i)
            return JNode(val,start,end,"string"),end
        if ch=='{':
            i+=1; obj={}; children={}; order=[]
            i=skip(i)
            if i<len(text) and text[i]=='}': return JNode(obj,start,i+1,"map",children),i+1
            while True:
                i=skip(i); key_node,i=parse_val(i); i=skip(i)
                if i>=len(text) or text[i]!=':': raise MsgError("expected `:` at line 1 column "+str(i+1))
                i+=1; val_node,i=parse_val(i); obj[key_node.value]=val_node.value; children[key_node.value]=(key_node,val_node); order.append(key_node.value)
                i=skip(i)
                if i<len(text) and text[i]==',': i+=1; continue
                if i<len(text) and text[i]=='}': i+=1; break
                raise MsgError("expected `,` or `}` at line 1 column "+str(i+1))
            node=JNode(obj,start,i,"map",children); node.children['_order']=order; return node,i
        if ch=='[':
            i+=1; arr=[]; children=[]
            i=skip(i)
            if i<len(text) and text[i]==']': return JNode(arr,start,i+1,"seq",children),i+1
            while True:
                val_node,i=parse_val(i); arr.append(val_node.value); children.append(val_node); i=skip(i)
                if i<len(text) and text[i]==',': i+=1; continue
                if i<len(text) and text[i]==']': i+=1; break
                raise MsgError("expected `,` or `]` at line 1 column "+str(i+1))
            return JNode(arr,start,i,"seq",children),i
        if text.startswith("true",i): return JNode(True,start,i+4,"bool"),i+4
        if text.startswith("false",i): return JNode(False,start,i+5,"bool"),i+5
        if text.startswith("null",i): return JNode(None,start,i+4,"null"),i+4
        m=re.match(r'-?[0-9]+(?:\.[0-9]+)?(?:[eE][-+]?[0-9]+)?',text[i:])
        if m:
            tok=m.group(0); val=float(tok) if ('.' in tok or 'e' in tok or 'E' in tok) else int(tok)
            return JNode(val,start,i+len(tok),"float" if isinstance(val,float) else "int"),i+len(tok)
        # serde_json expected value at col = start+1
        raise MsgError(f"expected value at line 1 column {start+1}")
    node,i=parse_val(0)
    return node

def j_col(node):
    # serde_json error column for scalar token end (last char 1based) = end offset (0based exclusive)
    if node.kind in ("map","seq"):
        return node.start  # 0based start = 1based previous char (colon etc)
    return node.end

def j_err(msg,node):
    col=j_col(node)
    if col<=0: col=1
    raise MsgError(f"{msg} at line 1 column {col}")

def j_unexpected(node):
    return unexpected_str(node.value)

def j_string(node):
    if node.kind=="string": return node.value
    j_err(f"invalid type: {j_unexpected(node)}, expected a string",node)
def j_bool(node):
    if node.kind=="bool": return node.value
    j_err(f"invalid type: {j_unexpected(node)}, expected a boolean",node)
def j_usize(node):
    if node.kind=="int":
        if node.value>=0: return node.value
        j_err(f"invalid value: integer `{node.value}`, expected usize",node)
    if node.kind=="float":
        j_err(f"invalid type: floating point `{format_float(node.value)}`, expected usize",node)
    j_err(f"invalid type: {j_unexpected(node)}, expected usize",node)
def j_char(node):
    if node.kind=="string":
        if len(node.value)==1: return node.value
        j_err(f'invalid value: string "{node.value}", expected a character',node)
    j_err(f"invalid type: {j_unexpected(node)}, expected a character",node)
def j_enum(node,variants):
    if node.kind=="string":
        if node.value in variants: return node.value
        j_err(f"unknown variant `{node.value}`, expected one of {variants_list_str(variants)}",node)
    # seq/map etc
    if node.kind=="seq": j_err("invalid type: sequence, expected variant identifier",node)
    j_err(f"invalid type: {j_unexpected(node)}, expected variant identifier",node)
def j_struct(node,struct_name,allowed):
    if node.kind!="map":
        j_err(f"invalid type: {j_unexpected(node)}, expected struct {struct_name}",node)
    out={}
    for k in node.children.get('_order',[]):
        kn,vn=node.children[k]
        if k not in allowed:
            exp=" or ".join(f"`{a}`" for a in allowed) if len(allowed)<=2 else ", ".join(f"`{a}`" for a in allowed[:-1])+f", or `{allowed[-1]}`"
            j_err(f"unknown field `{k}`, expected {exp}",kn)
        out[k]=vn
    return out

def j_missing(node,field):
    # approximate serde_json missing field column
    col=node.end-1 if node.children.get('_order') else node.end
    # node.end exclusive after } ; col as 1based? For {"Call":{"args":[]}} inner node end=20 (0based after } pos20?) compute: missing col19 seen = end-1? let's use max(1,col)
    raise MsgError(f"missing field `{field}` at line 1 column {col}")

def validate_from_json_text(text):
    # text is JSON generated by jf
    try:
        root=parse_json_nodes(text)
    except MsgError:
        raise
    except Exception as e:
        raise MsgError(str(e))
    # top
    if root.kind=="string":
        name=root.value
        if name not in VARIANTS:
            j_err(f"unknown variant `{name}`, expected one of {variants_list_str(VARIANTS)}",root)
        if name in UNIT_VARIANTS: return name
        raise MsgError("invalid type: unit variant, expected newtype variant")
    if root.kind=="map":
        order=root.children.get('_order',[])
        if len(order)!=1:
            # serde_json: for empty map expected value at col2; multi-key expected value at second key token position approx col?
            if len(order)==0:
                raise MsgError("expected value at line 1 column 2")
            # focus on first variant: if unit, error expected value at position after null? approximate by second key node start
            second_key=root.children[order[1]][0]
            raise MsgError(f"expected value at line 1 column {second_key.start}")
        name=order[0]; kn,vn=root.children[name]
        if name not in VARIANTS:
            j_err(f"unknown variant `{name}`, expected one of {variants_list_str(VARIANTS)}",kn)
        if name in UNIT_VARIANTS:
            if vn.kind=="null": return {name:None}
            j_err(f"invalid type: {j_unexpected(vn)}, expected unit",vn)
        payload=validate_payload_json(name,vn)
        return {name:payload}
    # number/bool/null/seq
    # serde_json expecting enum from non-string/map gives "expected value at line 1 col1" for numbers etc observed
    raise MsgError("expected value at line 1 column 1")

def validate_payload_json(name,v):
    if name in STRING_VARIANTS: return j_string(v)
    if name in USIZE_VARIANTS: return j_usize(v)
    if name in COMMAND_VARIANTS:
        fields=j_struct(v,"Command",["command","args"])
        if "command" not in fields: j_missing(v,"command")
        out={"command":j_string(fields["command"])}
        if "args" in fields:
            an=fields["args"]
            if an.kind!="seq": j_err(f"invalid type: {j_unexpected(an)}, expected a sequence",an)
            out["args"]=[j_string(x) for x in an.children]
        return out
    if name in FILTER_STRUCT_VARIANTS:
        fields=j_struct(v,"NodeFilterApplicableDeserializer",["filter","input"])
        for req in ("filter","input"):
            if req not in fields: j_missing(v,req)
        return {"filter":j_enum(fields["filter"],FILTERS),"input":j_string(fields["input"])}
    if name in FILTER_ENUM_VARIANTS: return j_enum(v,FILTERS)
    if name in SORTER_STRUCT_VARIANTS:
        fields=j_struct(v,"NodeSorterApplicable",["sorter","reverse"])
        if "sorter" not in fields: j_missing(v,"sorter")
        out={"sorter":j_enum(fields["sorter"],SORTERS)}
        if "reverse" in fields: out["reverse"]=j_bool(fields["reverse"])
        return out
    if name in SORTER_ENUM_VARIANTS: return j_enum(v,SORTERS)
    if name=="UpdateInputBuffer": return validate_input_op_json(v)
    raise MsgError("unhandled")

def validate_input_op_json(v):
    if v.kind=="string":
        s=v.value
        if s not in INPUT_OPS_ALL: j_err(f"unknown variant `{s}`, expected one of {variants_list_str(INPUT_OPS_ALL)}",v)
        if s in INPUT_OPS_UNIT: return s
        raise MsgError("invalid type: unit variant, expected newtype variant")
    if v.kind=="map":
        order=v.children.get('_order',[])
        if len(order)!=1:
            # empty -> expected value at col of inner } (__observed col23 for {"UpdateInputBuffer":{}} inner } is at 23?)
            raise MsgError(f"expected value at line 1 column {v.end-1 if v.end else 1}")
        name=order[0]; kn,vn=v.children[name]
        if name not in INPUT_OPS_ALL: j_err(f"unknown variant `{name}`, expected one of {variants_list_str(INPUT_OPS_ALL)}",kn)
        if name in INPUT_OPS_UNIT:
            if vn.kind=="null": return {name:None}
            j_err(f"invalid type: {j_unexpected(vn)}, expected unit",vn)
        if name=="SetCursor": return {"SetCursor":j_usize(vn)}
        return {"InsertCharacter":j_char(vn)}
    if v.kind=="seq": j_err("invalid type: sequence, expected variant identifier",v)
    j_err(f"invalid type: {j_unexpected(v)}, expected variant identifier",v)

# Canonical msg helpers
def msg_name(msg):
    return msg if isinstance(msg,str) else next(iter(msg.keys()))
def msg_payload(msg):
    return None if isinstance(msg,str) else next(iter(msg.values()))

# jf formatting
class JfError(Exception):
    pass

def _json_quote(s):
    # serde_json::to_string for a string
    return json.dumps(s, ensure_ascii=False, separators=(',',':'))

def jf_render(fmt,args):
    # returns substituted template string; raises JfError with message after "xplr -m: "
    out=[]; argi=0
    chars=list(fmt)
    i=0
    def col(pos): return pos+1  # 1-based char column of pos index
    while i<len(chars):
        ch=chars[i]
        if ch!='%':
            out.append(ch); i+=1; continue
        # % at i
        if i+1>=len(chars):
            raise JfError("template ended with incomplete placeholder")
        c1=chars[i+1]
        if c1=='%':
            out.append('%'); i+=2; continue
        if c1 in ('s','q'):
            if argi>=len(args):
                raise JfError(f"placeholder missing value at column {col(i)}")
            val=args[argi]; argi+=1
            out.append(val if c1=='s' else _json_quote(val)); i+=2; continue
        if c1=='*':
            if i+2>=len(chars):
                raise JfError("template ended with incomplete placeholder")
            c2=chars[i+2]
            if c2=='%':
                # weird observed: %*% treated as %% (literal %) consuming no args ? It yielded "%" with 0 args and too many with 1.
                out.append('%'); i+=3; continue
            if c2 in ('s','q'):
                rest=args[argi:]; argi=len(args)
                if c2=='s': out.append(",".join(rest))
                else: out.append(",".join(_json_quote(x) for x in rest))
                i+=3; continue
            if c2=='*':
                if i+3>=len(chars):
                    raise JfError("template ended with incomplete placeholder")
                c3=chars[i+3]
                if c3=='%':
                    out.append('%'); i+=4; continue
                if c3 in ('s','q'):
                    rest=args[argi:]
                    if len(rest)%2==1:
                        raise JfError(f"placeholder missing value at column {col(i+2)}")
                    argi=len(args)
                    parts=[]
                    for j in range(0,len(rest),2):
                        k=rest[j]; val=rest[j+1]
                        parts.append(f"{_json_quote(k)}:{val if c3=='s' else _json_quote(val)}")
                    out.append(",".join(parts)); i+=4; continue
                raise JfError(f"invalid placeholder '%**{c3}' at column {col(i+2)}, use one of '%**s' or '%**q', or escape it using '%%'")
            raise JfError(f"invalid placeholder '%*{c2}' at column {col(i+1)}, use one of '%*s' or '%*q', or escape it using '%%'")
        raise JfError(f"invalid placeholder '%{c1}' at column {col(i)}, use one of '%s' or '%q', or escape it using '%%'")
    if argi < len(args):
        raise JfError("too many positional values, not enough positional placeholders")
    return "".join(out)

def jf_to_json(fmt,args):
    # returns json string (compact) as xplr -M does; raises MsgError/JfError/YamlError prefix-handled by caller
    rendered=jf_render(fmt,args)
    from yamlmini import parse_yaml
    try:
        node=parse_yaml(rendered)
    except YamlError as e:
        raise JfError(f"yaml: {e}")
    val=generic_value(node)
    # float non-finite -> null in serde_json value conversion
    def norm(x):
        if isinstance(x,float) and (x!=x or x in (float('inf'),float('-inf'))): return None
        if isinstance(x,list): return [norm(v) for v in x]
        if isinstance(x,dict): return {k:norm(v) for k,v in x.items()}
        return x
    val=norm(val)
    # json dumps: need float formatting like serde_json (1000.0). Python separators.
    return json.dumps(val, ensure_ascii=False, separators=(',',':'))
