    return r

# ---------- YAML direct validation helpers ----------
def y_node_type_unexpected(node):
    if isinstance(node,YSeq): return "sequence"
    if isinstance(node,YMap): return "map"
    # scalar: resolved type for plain, quoted are strings
    if node.style!="plain":
        return f'string "{node.value}"'
    g=resolve_plain_scalar(node.value)
    if isinstance(g,str): return f'string "{g}"'
    return unexpected_str(g)

def y_err(path,msg,node=None):
    prefix=f"{path}: " if path else ""
    if node is not None and hasattr(node,'line'):
        raise MsgError(f"{prefix}{msg} at line {node.line} column {node.col}")
    raise MsgError(f"{prefix}{msg}")

def y_scalar_string(node,path,expected="a string"):
    if isinstance(node,YScalar):
        # serde_yaml -> String uses raw scalar content regardless plain type resolution
        return node.value
    y_err(path,f"invalid type: {y_node_type_unexpected(node)}, expected {expected}",node)

def y_scalar_bool(node,path):
    if isinstance(node,YScalar) and node.style=="plain":
        if node.value in ("true","True","TRUE"): return True
        if node.value in ("false","False","FALSE"): return False
        g=resolve_plain_scalar(node.value)
        y_err(path,f"invalid type: {unexpected_str(g) if not isinstance(g,str) else f'string \"{g}\"'}, expected a boolean",node)
    if isinstance(node,YScalar):
        y_err(path,f'invalid type: string "{node.value}", expected a boolean',node)
    y_err(path,f"invalid type: {y_node_type_unexpected(node)}, expected a boolean",node)

def y_scalar_usize(node,path):
    if isinstance(node,YScalar):
        if node.style!="plain":
            y_err(path,f'invalid type: string "{node.value}", expected usize',node)
        g=resolve_plain_scalar(node.value)
        if isinstance(g,int) and not isinstance(g,bool):
            if g>=0: return g
            y_err(path,f"invalid type: integer `{g}`, expected usize",node)
        if isinstance(g,float):
            y_err(path,f"invalid type: floating point `{format_float(g)}`, expected usize",node)
        if isinstance(g,bool):
            y_err(path,f"invalid type: boolean `{'true' if g else 'false'}`, expected usize",node)
        if g is None:
            y_err(path,f"invalid type: null, expected usize",node)
        y_err(path,f'invalid type: string "{node.value}", expected usize',node)
    y_err(path,f"invalid type: {y_node_type_unexpected(node)}, expected usize",node)

