    if name in FILTER_ENUM_VARIANTS:
        return y_enum(v,path,FILTERS)
    if name in SORTER_STRUCT_VARIANTS:
        fields=y_struct_fields(v,path,"NodeSorterApplicable",["sorter","reverse"])
        if "sorter" not in fields: y_err(path,"missing field `sorter`",v)
