    raise MsgError(f"unhandled variant {name}")

def validate_input_op_yaml(v,path):
    if isinstance(v,YScalar):
        if v.style=="plain":
            g=resolve_plain_scalar(v.value)
            if not isinstance(g,str):
                y_err(path,f"invalid type: {unexpected_str(g)}, expected enum InputOperation",v)  # approx
        s=v.value
        if s not in INPUT_OPS_ALL:
            y_err(path,f"unknown variant `{s}`, expected one of {variants_list_str(INPUT_OPS_ALL)}",v)
        if s in INPUT_OPS_UNIT:
            return s
        raise MsgError("invalid type: unit variant, expected newtype variant")
    if isinstance(v,YMap):
        if len(v.pairs)!=1:
            y_err(path,"invalid value: map, expected map with a single key",v)
        k,val=v.pairs[0]; name=k.value if isinstance(k,YScalar) else None
        if name not in INPUT_OPS_ALL:
            y_err(path,f"unknown variant `{name}`, expected one of {variants_list_str(INPUT_OPS_ALL)}",k)
        if name in INPUT_OPS_UNIT:
            raise MsgError("invalid type: map, expected unit variant")
        if name=="SetCursor":
            return {"SetCursor": y_scalar_usize(val,path+".SetCursor")}
        if name=="InsertCharacter":
            return {"InsertCharacter": y_scalar_char(val,path+".InsertCharacter")}
    if isinstance(v,YSeq):
        y_err(path,"invalid type: sequence, expected variant identifier",v)
    y_err(path,f"invalid type: {y_node_type_unexpected(v)}, expected variant identifier",v)

# ---------- JSON validation (for -m) ----------
class JNode:
    __slots__=("value","start","end","kind","children")
    def __init__(self,value,start,end,kind,children=None): self.value=value; self.start=start; self.end=end; self.kind=kind; self.children=children or {}

def parse_json_nodes(text):
    # Use json decoder with object_pairs_hook impossible positions; write tiny parser
    i=0
    def skip(i):
        while i<len(text) and text[i] in " \t\n\r": i+=1
        return i
    def parse_val(i):
        i=skip(i); start=i
        if i>=len(text): raise MsgError("expected value at line 1 column 1")
        ch=text[i]
        if ch=='"':
            # find using json decoder raw_decode
            val,end=json.JSONDecoder().raw_decode(text,i)
            return JNode(val,start,end,"string"),end
        if ch=='{':
            i+=1; obj={}; children={}; order=[]
            i=skip(i)
            if i<len(text) and text[i]=='}': return JNode(obj,start,i+1,"map",children),i+1
            while True:
                i=skip(i); key_node,i=parse_val(i); i=skip(i)
                if i>=len(text) or text[i]!=':': raise MsgError("expected `:` at line 1 column "+str(i+1))
                i+=1; val_node,i=parse_val(i); obj[key_node.value]=val_node.value; children[key_node.value]=(key_node,val_node); order.append(key_node.value)
                i=skip(i)
                if i<len(text) and text[i]==',': i+=1; continue
                if i<len(text) and text[i]=='}': i+=1; break
                raise MsgError("expected `,` or `}` at line 1 column "+str(i+1))
            node=JNode(obj,start,i,"map",children); node.children['_order']=order; return node,i
        if ch=='[':
            i+=1; arr=[]; children=[]
            i=skip(i)
            if i<len(text) and text[i]==']': return JNode(arr,start,i+1,"seq",children),i+1
            while True:
                val_node,i=parse_val(i); arr.append(val_node.value); children.append(val_node); i=skip(i)
                if i<len(text) and text[i]==',': i+=1; continue
                if i<len(text) and text[i]==']': i+=1; break
                raise MsgError("expected `,` or `]` at line 1 column "+str(i+1))
            return JNode(arr,start,i,"seq",children),i
        if text.startswith("true",i): return JNode(True,start,i+4,"bool"),i+4
        if text.startswith("false",i): return JNode(False,start,i+5,"bool"),i+5
        if text.startswith("null",i): return JNode(None,start,i+4,"null"),i+4
        m=re.match(r'-?[0-9]+(?:\.[0-9]+)?(?:[eE][-+]?[0-9]+)?',text[i:])
