cat > app/node.py << 'PYEOF'
import os, re, stat, ctypes, ctypes.util, mimetypes
from functools import cmp_to_key

MIME_MAP_BIG=None  # replaced below placeholder

def human_size(size):
    units=["B","kB","MB","GB","TB","PB","EB","ZB","YB"]
    if size < 1000:
        return f"{size} B"
    exp=0
    div=1
    while size >= div*1000 and exp < len(units)-1:
        div*=1000; exp+=1
    val=size/div
    if size % div == 0:
        return f"{int(val)} {units[exp]}"
    return f"{val:.2f} {units[exp]}"

def ext_of(path):
    name=os.path.basename(path)
    if name in ("",".",".."): return ""
    # Rust Path::extension
    if name.startswith(".") and name.count(".")==1:
        return ""
    if "." not in name: return ""
    return name.rsplit(".",1)[1]

def mime_essence_for(path, is_dir, mode):
    if is_dir:
        return "inode/directory"
    ext=ext_of(path).lower()
    mime=None
    if MIME_MAP_BIG is not None and ext in MIME_MAP_BIG:
        mime=MIME_MAP_BIG[ext] or None
    if mime is None and ext:
        if MIME_MAP_BIG is not None and ext in MIME_MAP_BIG:
            mime=None
        else:
            guessed,_=mimetypes.guess_type("file."+ext)
            mime=guessed
    if mime:
        return mime.split(";")[0].strip()
    if mode is not None and (mode & 0o111):
        return "application/x-executable"
    return ""

def permissions_dict(mode):
    if mode is None:
        return {"user_read":False,"user_write":False,"user_execute":False,"group_read":False,"group_write":False,"group_execute":False,"other_read":False,"other_write":False,"other_execute":False,"sticky":False,"setgid":False,"setuid":False}
    return {
        "user_read": bool(mode & 0o400), "user_write": bool(mode & 0o200), "user_execute": bool(mode & 0o100),
        "group_read": bool(mode & 0o040), "group_write": bool(mode & 0o020), "group_execute": bool(mode & 0o010),
        "other_read": bool(mode & 0o004), "other_write": bool(mode & 0o002), "other_execute": bool(mode & 0o001),
        "sticky": bool(mode & 0o1000), "setgid": bool(mode & 0o2000), "setuid": bool(mode & 0o4000),
    }

_libc=None
try:
    _libc=ctypes.CDLL("libc.so.6", use_errno=True)
except Exception:
    _libc=None

def btime_ns(path, follow=False):
    if _libc is None: return None
    try:
        buf=ctypes.create_string_buffer(256)
        SYS_statx=332
        AT_FDCWD=-100
        flags=0 if follow else 0x100
        mask=0x800
        # syscall is variadic; declare via CFUNCTYPE? ctypes allows calling with args if argtypes set including pointer
        syscall=_libc.syscall
        syscall.restype=ctypes.c_long
        syscall.argtypes=[ctypes.c_long, ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_uint, ctypes.c_void_p]
        ret=syscall(SYS_statx, AT_FDCWD, os.fsencode(path), flags, mask, buf)
        if ret!=0: return None
        import struct
        stx_mask=struct.unpack_from("<I",buf.raw,0)[0]
        if not (stx_mask & 0x800): return None
        sec,nsec=struct.unpack_from("<qI",buf.raw,80)
        return int(sec)*1000000000+int(nsec)
    except Exception:
        return None

def resolved_metadata(canonical_path):
    try:
        st=os.stat(canonical_path)
    except OSError:
        return None
    mode=st.st_mode
    is_dir=stat.S_ISDIR(mode); is_file=stat.S_ISREG(mode)
    return {
        "absolute_path": canonical_path,
        "extension": ext_of(canonical_path),
        "is_dir": is_dir,
        "is_file": is_file,
        "is_readonly": (mode & 0o222)==0,
        "mime_essence": mime_essence_for(canonical_path,is_dir,mode),
        "size": st.st_size,
        "human_size": human_size(st.st_size),
        "created": btime_ns(canonical_path, follow=True),
        "last_modified": st.st_mtime_ns,
        "uid": st.st_uid,
        "gid": st.st_gid,
    }

def make_node(parent, relative_path, absolute_path=None):
    if absolute_path is None:
        absolute_path=os.path.join(parent,relative_path) if parent!="/" else "/"+relative_path
    try:
        st=os.lstat(absolute_path)
        mode=st.st_mode; size=st.st_size; uid=st.st_uid; gid=st.st_gid; mtime=st.st_mtime_ns; ctime=btime_ns(absolute_path,False)
        is_dir=stat.S_ISDIR(mode); is_file=stat.S_ISREG(mode); is_symlink=stat.S_ISLNK(mode); readonly=(mode & 0o222)==0
    except OSError:
        mode=None; size=0; uid=0; gid=0; mtime=None; ctime=None; is_dir=False; is_file=False; is_symlink=False; readonly=False
    # canonical
    canonical=None; symlink=None; is_broken=False
    try:
        canon_path=os.path.realpath(absolute_path, strict=True)
        canonical=resolved_metadata(canon_path)
        if canonical is None: raise OSError("canonical meta failed")
        if is_symlink: symlink=canonical
    except Exception:
        canonical=None; symlink=None; is_broken=True
    return {
        "parent": parent,
        "relative_path": relative_path,
        "absolute_path": absolute_path,
        "extension": ext_of(absolute_path),
        "is_dir": is_dir,
        "is_file": is_file,
        "is_symlink": is_symlink,
        "is_broken": is_broken,
        "is_readonly": readonly,
        "mime_essence": mime_essence_for(absolute_path,is_dir,mode),
        "size": size,
        "human_size": human_size(size),
        "permissions": permissions_dict(mode),
        "created": ctime,
        "last_modified": mtime,
        "uid": uid,
        "gid": gid,
        "canonical": canonical,
        "symlink": symlink,
    }

def node_from_path(absolute_path):
    # absolute_path should be absolutized already. Returns None for root.
    if absolute_path=="/": return None
    parent=os.path.dirname(absolute_path) or "/"
    rel=os.path.basename(absolute_path)
