    BONUS_CAMEL=70
    SCORE_GAP_START=-3
    SCORE_GAP_EXTENSION=-1
    SCORE_MATCH=0
    BONUS_CONSECUTIVE=40
    BONUS_FIRST_MULT=8  # will multiply first char bonus?
    # Compute bonus per text position based on previous char in original text
    bonus=[0]*n
    for i,ch in enumerate(orig_text):
        if i==0:
            bonus[i]=BONUS_BOUNDARY
        else:
            prev=orig_text[i-1]
            if prev in "/-_ .\\":
                bonus[i]=BONUS_BOUNDARY
            elif prev.islower() and ch.isupper():
                bonus[i]=BONUS_CAMEL
            elif prev.isalpha()==False and ch.isalpha():
                bonus[i]=BONUS_BOUNDARY
            else:
