    # nodes already filtered and sorted by sorters (needed for index ranking / unordered)
    pattern=searcher.get("pattern","")
    algo=searcher.get("algorithm","Fuzzy")
    unordered=searcher.get("unordered",False)
    exact_mode=searcher.get("exact_mode",False)
