            results.sort(key=rank_key)
    else:
        results.sort(key=rank_key)
    return [n for _,n,_,_ in results]

def explore_dir(parent, explorer_config):
    # Returns list nodes; raises OSError if read_dir fails
    entries=[]
    with os.scandir(parent) as it:
        for entry in it:
            entries.append(entry.name)
    nodes=[]
    for name in entries:
        # os.scandir name may be str; filenames with surrogate escapes from non-utf8 stay
        nodes.append(make_node(parent,name))
    filters=explorer_config.get("filters",[]) if explorer_config else []
    if filters:
        nodes=[n for n in nodes if all(filter_applies(n,f) for f in filters)]
    sorters=explorer_config.get("sorters",[]) if explorer_config else []
    nodes=sort_nodes(nodes,sorters)
    searcher=explorer_config.get("searcher") if explorer_config else None
    if searcher is not None:
        nodes=search_nodes(nodes,searcher)
    return nodes
