import re, math, os, sys, time, random

class LuaError(Exception):
    def __init__(self, value, line=None, chunk=None, is_runtime=True):
        super().__init__(str(value))
        self.value=value; self.line=line; self.chunk=chunk; self.is_runtime=is_runtime
        self.traceback_text=None

class LuaTable:
    def __init__(self):
        self.map={}  # wrapped key -> (orig_key,value)
        self.metatable=None
    def _wrap(self,key):
        if key is None: return None
        if isinstance(key,bool): return ('b',key)
        if isinstance(key,(int,float)) and not isinstance(key,bool):
            # normalize 1.0 -> 1
            if isinstance(key,float) and key.is_integer() and abs(key)<2**63: key=int(key)
            return ('n',key)
        if isinstance(key,str): return ('s',key)
        return ('o',id(key))
    def get(self,key,default=None):
        w=self._wrap(key)
        if w in self.map: return self.map[w][1]
        return default
    def set(self,key,value):
        if key is None: raise LuaError("table index is nil")
        if isinstance(key,float) and math.isnan(key): raise LuaError("table index is NaN")
        w=self._wrap(key)
        if value is None:
            self.map.pop(w,None)
        else:
            # normalize numeric orig key int
            if isinstance(key,float) and key.is_integer() and abs(key)<2**63: key=int(key)
            self.map[w]=(key,value)
    def rawget(self,key): return self.get(key,None)
    def keys_values(self): return list(self.map.values())
    def length(self):
        n=0
        while self.get(n+1,None) is not None: n+=1
        return n
    def __repr__(self): return "table: 0x%x"%(id(self),)

class LuaUserdata:
