        self.stderr_write=lambda s: sys.stderr.write(s)
        self.stdin_read_line=lambda: sys.stdin.readline()
        self.registry={}
        self.loaded_modules={}
        self.package_path="./?.lua;./?/init.lua"
        self.package_cpath=""
