    def set_global(self,name,val): self.globals.set(name,val)
    def get_global(self,name): return self.globals.get(name,None)
    def make_table(self, pairs=None):
        t=LuaTable()
        if pairs:
            if isinstance(pairs,dict):
                for k,v in pairs.items(): t.set(k,v)
            else:
                for k,v in pairs: t.set(k,v)
