        # construct runtime LuaError with position if value string and line known? error() native handles prefix itself based level. Runtime internal errors call this with full msg.
        frame=self.frames[-1] if self.frames else None
        raise LuaError(value, line=line if line is not None else (frame.line if frame else None), chunk=frame.chunk if frame else None)
    def current_pos(self):
        f=self.frames[-1] if self.frames else None
        return (f.chunk,f.line) if f else (None,None)
    def format_error_for_log(self, e):
        # Returns mlua-like string used in xplr logs for config loading and CallLua errors.
        if isinstance(e,LuaError):
            if not e.is_runtime:
                # syntax
                msg=str(e.value)
                if e.chunk and e.line:
                    return f'syntax error: [string "{e.chunk}"]:{e.line}: {msg}'
                return f'syntax error: {msg}'
            msg=e.value
            if isinstance(msg,str):
                # if already has position prefix maybe
                base=msg
            else:
                base=lua_tostring(msg,self)
            tb=self._traceback_text(e)
            return f"runtime error: {base}\nstack traceback:\n{tb}" if tb else f"runtime error: {base}"
        return str(e)
    def _traceback_text(self,e):
        if hasattr(e,"_tb_frames") and e._tb_frames is not None:
            frames=e._tb_frames
