        lines=[]
        # For error() originating in native, original includes [C]: in ? then [C]: in function 'error'. We approximate based frames captured at raise.
        for fr in frames:
            if fr.is_native:
                if fr.name:
                    lines.append(f"\t[C]: in function '{fr.name}'")
                else:
                    lines.append("\t[C]: in ?")
            else:
                if fr.name=="__main" or fr.name is None and len(frames)<=2:
                    lines.append(f'\t[string "{fr.chunk}"]:{fr.line}: in main chunk')
                elif fr.name:
                    lines.append(f'\t[string "{fr.chunk}"]:{fr.line}: in function \'{fr.name}\'')
                else:
                    lines.append(f'\t[string "{fr.chunk}"]:{fr.line}: in function <[string "{fr.chunk}"]:{fr.line}>')
        return "\n".join(lines)

    def get_metatable(self,v):
