            e._tb_frames=[]
            raise
        func=LuaFunction([],True,ast,Scope(None),chunk_name,1,name="__main")
        if env_table is not None: func.env=env_table
        return func
    def execute(self,src,chunk_name,args=None):
        func=self.load(src,chunk_name)
