COLORS=["Reset","Black","Red","Green","Yellow","Blue","Magenta","Cyan","Gray","DarkGray","LightRed","LightGreen","LightYellow","LightBlue","LightMagenta","LightCyan","White"]
MODIFIERS=["Bold","Dim","Italic","Underlined","SlowBlink","RapidBlink","Reversed","Hidden","CrossedOut"]
BORDERS=["Top","Right","Bottom","Left"]
BORDER_TYPES=["Plain","Rounded","Double","Thick"]

