_BG={"Black":40,"Red":41,"Green":42,"Yellow":43,"Blue":44,"Magenta":45,"Cyan":46,"Gray":107,"DarkGray":100,"LightRed":101,"LightGreen":102,"LightYellow":103,"LightBlue":104,"LightMagenta":105,"LightCyan":106,"White":107,"Reset":49}
_MOD={"Bold":1,"Dim":2,"Italic":3,"Underlined":4,"SlowBlink":5,"RapidBlink":6,"Reversed":7,"Hidden":8,"CrossedOut":9}

def empty_style(): return {"fg":None,"bg":None,"add_modifiers":None,"sub_modifiers":None}

def _color_code(color,is_bg):
    if color is None: return None
    if isinstance(color,str):
        return (_BG if is_bg else _FG).get(color)
    if isinstance(color,dict):
        if "Rgb" in color:
            r,g,b=color["Rgb"]; return f"{48 if is_bg else 38};2;{r};{g};{b}"
        if "Indexed" in color:
            return f"{48 if is_bg else 38};5;{color['Indexed']}"
    return None

def style_mix(styles):
    out={}
    add=[]; sub=[]
    for s in styles or []:
        if not isinstance(s,dict): continue
        if s.get("fg") is not None: out["fg"]=s["fg"]
        if s.get("bg") is not None: out["bg"]=s["bg"]
        for m in s.get("add_modifiers") or []:
            if m not in add: add.append(m)
        for m in s.get("sub_modifiers") or []:
            if m not in sub: sub.append(m)
    # Order in original serde serialization is struct fg,bg,add,sub but Lua table conversion sets fields in this call order below.
    res={}
    if out.get("fg") is not None: res["fg"]=out["fg"]
    if out.get("bg") is not None: res["bg"]=out["bg"]
    if add: res["add_modifiers"]=add
    if sub: res["sub_modifiers"]=sub
    return res

def paint(text, style):
    if not isinstance(style,dict): return text
    codes=[]
    for m in sorted(style.get("add_modifiers") or [], key=lambda x:_MOD.get(x,99)):
        if m in _MOD: codes.append(str(_MOD[m]))
    bg=style.get("bg")
    if bg is not None and bg!="Reset":
        c=_color_code(bg,True)
        if c is not None: codes.append(str(c))
    fg=style.get("fg")
    if fg is not None and fg!="Reset":
        c=_color_code(fg,False)
        if c is not None: codes.append(str(c))
    if not codes: return text
    return "\x1b["+";".join(codes)+"m"+text+"\x1b[0m"

def style_ansi_codes(style):
    # for terminal renderer - returns list SGR params to set fg/bg/mods (no reset distinction)
    codes=[]
    if not isinstance(style,dict): return codes
    for m in style.get("add_modifiers") or []:
        if m in _MOD: codes.append(str(_MOD[m]))
    bg=_color_code(style.get("bg"),True)
    if bg is not None: codes.append(str(bg))
    fg=_color_code(style.get("fg"),False)
    if fg is not None: codes.append(str(fg))
    return codes
