from lua import LuaTable, LuaFunction, NativeFunction, LuaUserdata, lua_tostring

def python_to_lua(v, seen=None):
    if isinstance(v,(LuaTable,LuaFunction,NativeFunction,LuaUserdata)) or v is None or isinstance(v,(bool,int,float,str)):
        return v
    if isinstance(v,dict):
        t=LuaTable()
        for k,val in v.items():
            lv=python_to_lua(val)
            if lv is not None:
                t.set(k,lv)
        return t
    if isinstance(v,(list,tuple)):
        t=LuaTable()
        for i,val in enumerate(v,1):
            lv=python_to_lua(val)
            if lv is not None: t.set(i,lv)
        return t
    return v

def lua_to_python(v, seen=None):
    if seen is None: seen={}
    if isinstance(v,LuaTable):
        oid=id(v)
        if oid in seen:
            return seen[oid]
        items=v.keys_values()
        # list detection
        if items and all(isinstance(k,int) and not isinstance(k,bool) for k,_ in items):
            keys=sorted(k for k,_ in items)
            if keys==list(range(1,len(keys)+1)):
                out=[]; seen[oid]=out
                mp={k:val for k,val in items}
                for k in keys: out.append(lua_to_python(mp[k],seen))
                return out
        out={}; seen[oid]=out
        for k,val in items:
            out[lua_to_python(k,seen) if isinstance(k,LuaTable) else k]=lua_to_python(val,seen)
        return out
    return v

def lua_table_from_pairs(pairs):
    t=LuaTable()
    for k,v in pairs: 
        if v is not None: t.set(k,python_to_lua(v))
    return t
