import copy
from default_config import DEFAULT_CONFIG, ZERO_GENERAL, ZERO_NODE_TYPES
from messages import validate_message_py, MsgError, FILTERS, SORTERS, _expected_fields
from style import COLORS, MODIFIERS, BORDERS, BORDER_TYPES, empty_style

class ConfigError(Exception):
    pass

def err(msg): raise ConfigError(f"deserialize error: {msg}")
def type_name(v, table_expected=False):
    if v is None: return "unit value"
    if isinstance(v,bool): return "boolean" if table_expected else f"boolean `{'true' if v else 'false'}`"
    if isinstance(v,int): return "integer" if table_expected else f"integer `{v}`"
    if isinstance(v,float): return "float" if table_expected else f"floating point `{v}`"
    if isinstance(v,str): return "string" if table_expected else f'string "{v}"'
    if isinstance(v,list): return "sequence"
    if isinstance(v,dict): return "map"
    # Lua functions etc
    from lua import lua_type
    return lua_type(v)

def expect_table(v, struct_name=None):
    if isinstance(v,dict): return v
    if struct_name: err(f"invalid type: {type_name(v)}, expected struct {struct_name}")
    err(f"invalid type: {type_name(v,True)}, expected table")
def expect_str(v):
    if isinstance(v,str): return v
    err(f"invalid type: {type_name(v)}, expected a string")
def expect_bool(v):
    if isinstance(v,bool): return v
    err(f"invalid type: {type_name(v)}, expected a boolean")
def expect_int(v, typename="usize"):
    if isinstance(v,int) and not isinstance(v,bool): return v
    if isinstance(v,float) and v.is_integer(): return int(v)
    err(f"invalid type: {type_name(v)}, expected {typename}")
def expect_enum(v,variants):
    if isinstance(v,str):
        if v in variants: return v
        err("unknown variant `"+v+"`, expected one of "+", ".join(f"`{x}`" for x in variants))
    err(f"invalid type: {type_name(v)}, expected variant identifier")
def check_unknown(d, allowed):
    for k in d.keys():
        if k not in allowed:
            err(f"unknown field `{k}`, expected {_expected_fields(list(allowed))}")

def normalize_color(v):
    if v is None: return None
    if isinstance(v,str): return expect_enum(v,COLORS)
    if isinstance(v,dict):
        if len(v)!=1: err("invalid value: map, expected map with a single key")
        k=next(iter(v))
        if k=="Rgb":
            vals=v[k]
            if isinstance(vals,dict) and not vals: vals=[]
            if not isinstance(vals,list) or len(vals)!=3: err("invalid type: sequence, expected a tuple with 3 elements")
            rgb=[]
            for x in vals:
                n=expect_int(x,"u8")
                if n<0 or n>255: err(f"invalid value: integer `{n}`, expected u8")
                rgb.append(n)
            return {"Rgb":rgb}
        if k=="Indexed":
            n=expect_int(v[k],"u8")
            if n<0 or n>255: err(f"invalid value: integer `{n}`, expected u8")
            return {"Indexed":n}
        err(f"unknown variant `{k}`, expected `Rgb` or `Indexed`")
    err(f"invalid type: {type_name(v)}, expected variant identifier")

def normalize_modifier_list(v):
    if v is None: return None
    if isinstance(v,dict) and not v: return []
    if not isinstance(v,list): err(f"invalid type: {type_name(v,True)}, expected table")
    return [expect_enum(x,MODIFIERS) for x in v]

def normalize_style(raw):
    if raw is None: return empty_style()
    d=expect_table(raw,"Style")
    check_unknown(d,["fg","bg","add_modifiers","sub_modifiers"])
    return {"fg":normalize_color(d.get("fg")),"bg":normalize_color(d.get("bg")),"add_modifiers":normalize_modifier_list(d.get("add_modifiers")),"sub_modifiers":normalize_modifier_list(d.get("sub_modifiers"))}

def normalize_identifier(raw):
    if raw is None: return {"format":None,"style":empty_style()}
    d=expect_table(raw)
    check_unknown(d,["format","style"])
    return {"format":expect_str(d["format"]) if isinstance(d.get("format"),str) else (None if d.get("format") is None else expect_str(d.get("format"))), "style":normalize_style(d.get("style"))}

def normalize_constraints(raw):
    if raw is None: return None
    if isinstance(raw,dict) and not raw: return []
    if not isinstance(raw,list): err(f"invalid type: {type_name(raw,True)}, expected table")
    out=[]
    variants=["Percentage","Ratio","Length","LengthLessThanScreenHeight","LengthLessThanScreenWidth","LengthLessThanLayoutHeight","LengthLessThanLayoutWidth","Max","MaxLessThanScreenHeight","MaxLessThanScreenWidth","MaxLessThanLayoutHeight","MaxLessThanLayoutWidth","Min","MinLessThanScreenHeight","MinLessThanScreenWidth","MinLessThanLayoutHeight","MinLessThanLayoutWidth"]
    for item in raw:
        if not isinstance(item,dict) or len(item)!=1: err("invalid value: map, expected map with a single key")
        k=next(iter(item)); v=item[k]
        if k not in variants: err(f"unknown variant `{k}`, expected one of "+", ".join(f"`{x}`" for x in variants))
        if k=="Ratio":
            if isinstance(v,dict) and not v: v=[]
            if not isinstance(v,list) or len(v)!=2: err("invalid type: sequence, expected a tuple with 2 elements")
            out.append({"Ratio":[expect_int(v[0],"u32"),expect_int(v[1],"u32")]})
        else:
            out.append({k:expect_int(v,"u16")})
    return out

def normalize_layout_config(raw):
    if raw is None: raw={}
    d=expect_table(raw)
    check_unknown(d,["margin","horizontal_margin","vertical_margin","constraints"])
    return {"margin":expect_int(d["margin"],"u16") if "margin" in d and d["margin"] is not None else None,
            "horizontal_margin":expect_int(d["horizontal_margin"],"u16") if "horizontal_margin" in d and d["horizontal_margin"] is not None else None,
            "vertical_margin":expect_int(d["vertical_margin"],"u16") if "vertical_margin" in d and d["vertical_margin"] is not None else None,
            "constraints":normalize_constraints(d.get("constraints"))}

def normalize_panel_ui(raw):
    if raw is None: raw={}
    d=expect_table(raw)
    check_unknown(d,["title","style","borders","border_type","border_style"])
    title_raw=d.get("title")
    if title_raw is None: title={"format":None,"style":empty_style()}
    else:
        td=expect_table(title_raw); check_unknown(td,["format","style"])
        title={"format":expect_str(td["format"]) if "format" in td and td["format"] is not None else None,"style":normalize_style(td.get("style"))}
    borders=d.get("borders")
    if borders is not None:
        if isinstance(borders,dict) and not borders: borders=[]
        elif not isinstance(borders,list): err(f"invalid type: {type_name(borders,True)}, expected table")
        else: borders=[expect_enum(x,BORDERS) for x in borders]
    return {"title":title,"style":normalize_style(d.get("style")),"borders":borders,"border_type":expect_enum(d["border_type"],BORDER_TYPES) if d.get("border_type") is not None else None,"border_style":normalize_style(d.get("border_style"))}

def normalize_custom_panel(raw):
    if not isinstance(raw,dict) or len(raw)!=1:
        err("invalid value: map, expected map with a single key")
    k=next(iter(raw)); v=raw[k]
    if k not in ("CustomParagraph","CustomList","CustomTable","CustomLayout"):
        err(f"unknown variant `{k}`, expected one of `CustomParagraph`, `CustomList`, `CustomTable`, `CustomLayout`")
    if k=="CustomLayout":
        return {"CustomLayout": normalize_layout(v)}
    d=expect_table(v)
    if k=="CustomParagraph":
        check_unknown(d,["ui","body"])
        return {"CustomParagraph":{"ui":normalize_panel_ui(d["ui"]) if d.get("ui") is not None else None,"body":expect_str(d.get("body")) if "body" in d else ""}}
    if k=="CustomList":
        check_unknown(d,["ui","body"])
        body=d.get("body") or []
        if isinstance(body,dict) and not body: body=[]
        return {"CustomList":{"ui":normalize_panel_ui(d["ui"]) if d.get("ui") is not None else None,"body":[expect_str(x) for x in body]}}
    # CustomTable: Rust struct field order in YAML? Use ui,widths,col_spacing,body based docs, config default debug_error static only paragraph.
    check_unknown(d,["ui","widths","col_spacing","body"])
    body=d.get("body") or []
    if isinstance(body,dict) and not body: body=[]
    return {"CustomTable":{"ui":normalize_panel_ui(d["ui"]) if d.get("ui") is not None else None,"widths":normalize_constraints(d.get("widths")) or [],"col_spacing":expect_int(d["col_spacing"],"u16") if d.get("col_spacing") is not None else None,"body":[[expect_str(c) for c in (row if isinstance(row,list) else [])] for row in body]}}

def normalize_layout(raw):
    if isinstance(raw,str):
        return expect_enum(raw,["Nothing","Table","InputAndLogs","Selection","HelpMenu","SortAndFilter"])
    if isinstance(raw,dict):
        if len(raw)!=1: err("invalid value: map, expected map with a single key")
        k=next(iter(raw)); v=raw[k]
        if k in ("Horizontal","Vertical"):
            d=expect_table(v); check_unknown(d,["config","splits"])
            splits=d.get("splits") or []
            if isinstance(splits,dict) and not splits: splits=[]
            return {k:{"config":normalize_layout_config(d.get("config")),"splits":[normalize_layout(x) for x in splits]}}
        if k=="Static": return {"Static":normalize_custom_panel(v)}
        if k=="Dynamic": return {"Dynamic":expect_str(v)}
        if k=="CustomContent":
            # deprecated: payload is CustomPanel (?) keep normalized as custom panel
            try: return {"CustomContent":normalize_custom_panel(v)}
            except ConfigError: return {"CustomContent":v}
        err(f"unknown variant `{k}`, expected one of `Nothing`, `Table`, `InputAndLogs`, `Selection`, `HelpMenu`, `SortAndFilter`, `Static`, `Dynamic`, `Horizontal`, `Vertical`, `CustomContent`")
    err(f"invalid type: {type_name(raw)}, expected variant identifier")

def normalize_action(raw):
    if raw is None: return None
    d=expect_table(raw)
    check_unknown(d,["help","messages"])
    msgs=d.get("messages") or []
    if isinstance(msgs,dict) and not msgs: msgs=[]
    if not isinstance(msgs,list) and msgs is not None: err(f"invalid type: {type_name(msgs,True)}, expected table")
    out_msgs=[]
    for m in msgs or []:
        try: out_msgs.append(validate_message_py(m))
        except MsgError as e: err(str(e))
    return {"help":expect_str(d["help"]) if d.get("help") is not None else None,"messages":out_msgs}

def normalize_keybindings(raw):
    if raw is None: raw={}
    d=expect_table(raw)
    fields=["on_key","on_alphabet","on_number","on_alphanumeric","on_special_character","on_character","on_navigation","on_function","default"]
    check_unknown(d,fields)
    on_key_raw=d.get("on_key") or {}
    if not isinstance(on_key_raw,dict): err(f"invalid type: {type_name(on_key_raw,True)}, expected table")
    on_key={}
    for k,v in on_key_raw.items():
        # keys can be int in Lua? Config keys are strings in YAML; lua number keys to serde map key string? mlua may convert int key to string? Keep str(k)
        on_key[str(k)]=normalize_action(v)
    out={"on_key":on_key}
    for f in fields[1:]: out[f]=normalize_action(d.get(f)) if d.get(f) is not None else None
    return out

def normalize_mode(raw):
    if raw is None: raw={}
    d=expect_table(raw)
    check_unknown(d,["name","help","extra_help","key_bindings","layout","prompt"])
    return {"name":expect_str(d["name"]) if d.get("name") is not None else "",
            "help":expect_str(d["help"]) if d.get("help") is not None else None,
            "extra_help":expect_str(d["extra_help"]) if d.get("extra_help") is not None else None,
            "key_bindings":normalize_keybindings(d.get("key_bindings")),
            "layout":normalize_layout(d["layout"]) if d.get("layout") is not None else None,
            "prompt":expect_str(d["prompt"]) if d.get("prompt") is not None else None}

def normalize_node_type(raw):
    if raw is None: raw={}
    d=expect_table(raw)
    check_unknown(d,["style","meta"])
    meta=d.get("meta") or {}
    if not isinstance(meta,dict): err(f"invalid type: {type_name(meta,True)}, expected table")
    meta_out={}
    for k,v in meta.items(): meta_out[str(k)]=expect_str(v) if v is not None else None
    return {"style":normalize_style(d.get("style")),"meta":meta_out}

def normalize_sorter_applicable(v):
    d=expect_table(v); check_unknown(d,["sorter","reverse"])
    if "sorter" not in d: err("missing field `sorter`")
    return {"sorter":expect_enum(d["sorter"],SORTERS),"reverse":expect_bool(d["reverse"]) if "reverse" in d and d["reverse"] is not None else False}

def normalize_like(path, raw, sample, zero):
    # dispatch special paths
    if path==("general","initial_sorting"):
        if raw is None: return None
        if isinstance(raw,dict) and not raw: return []
        if not isinstance(raw,list): err(f"invalid type: {type_name(raw,True)}, expected table")
        return [normalize_sorter_applicable(x) for x in raw]
    if path==("general","global_key_bindings"):
        return normalize_keybindings(raw)
    if path in [("general","search","algorithm")]:
        return expect_enum(raw,["Fuzzy","Regex"])
    if path==("general","search","rank_criteria"):
        if raw is None: return None
        if isinstance(raw,dict) and not raw: return []
        vals=["Score","NegScore","Begin","NegBegin","End","NegEnd","Length","NegLength","Index","NegIndex"]
        return [expect_enum(x,vals) for x in raw]
    if path==("general","sort_and_filter_ui","sorter_identifiers"):
        return normalize_identifier_map(raw,SORTERS)
    if path==("general","sort_and_filter_ui","filter_identifiers"):
        return normalize_identifier_map(raw,FILTERS)
    if path==("general","sort_and_filter_ui","search_identifiers"):
        return normalize_identifier_map(raw,["Fuzzy","Regex"])
    if isinstance(sample,dict) and set(sample.keys())=={"fg","bg","add_modifiers","sub_modifiers"}:
        return normalize_style(raw)
    if len(path)>=2 and path[-2]=="panel_ui": # shouldn't happen, panel handled in general below
        return normalize_panel_ui(raw)
    if path[:2]==("general","panel_ui") and len(path)==3:
        return normalize_panel_ui(raw)
    if isinstance(sample,bool): return expect_bool(raw)
    if isinstance(sample,int) and not isinstance(sample,bool):
        return expect_int(raw,"u16")
    if isinstance(sample,str) or sample is None:
        # None sample in default means nullable string/int/enum. Some int nullable fields: identify by name
        if path[-1] in ("height","margin","horizontal_margin","vertical_margin","col_spacing","scroll_padding"):
            return expect_int(raw,"u16") if raw is not None else None
        if raw is None: return None
        return expect_str(raw)
    if isinstance(sample,list):
        if raw is None: return None
        if isinstance(raw,dict) and not raw: return []
        if not isinstance(raw,list): err(f"invalid type: {type_name(raw,True)}, expected table")
        if path==("general","table","col_widths"):
            return normalize_constraints(raw)
        elem_sample=sample[0] if sample else None
        elem_zero=zero[0] if isinstance(zero,list) and zero else None
        return [normalize_like(path+(f"[{i}]",),x,elem_sample,elem_zero) for i,x in enumerate(raw)]
    if isinstance(sample,dict):
        if raw is None: return copy.deepcopy(zero)
        d=expect_table(raw)
        if not sample:
            # arbitrary map; values keep generic normalize to raw (identifier maps handled above)
            return copy.deepcopy(raw)
        check_unknown(d,list(sample.keys()))
        out=copy.deepcopy(zero) if isinstance(zero,dict) else {}
        # ensure all sample keys present in out in sample order
        result={}
        for k in sample.keys():
            if k in d:
                result[k]=normalize_like(path+(k,),d[k],sample[k],zero.get(k) if isinstance(zero,dict) else None)
            else:
                result[k]=copy.deepcopy(zero.get(k) if isinstance(zero,dict) else None)
        return result
    return raw

def normalize_identifier_map(raw,keys):
    if raw is None: return {}
    d=expect_table(raw)
    out={}
    for k,v in d.items():
        ek=expect_enum(k,keys); out[ek]=normalize_identifier(v)
    return out

def normalize_general(raw):
    if raw is None: raw={}
    d=expect_table(raw)
    sample=DEFAULT_CONFIG["general"]; check_unknown(d,list(sample.keys()))
    out={}
    for k in sample.keys():
        if k in d: out[k]=normalize_like(("general",k),d[k],sample[k],ZERO_GENERAL.get(k))
        else: out[k]=copy.deepcopy(ZERO_GENERAL.get(k))
    return out

def normalize_node_types(raw):
    if raw is None: raw={}
    d=expect_table(raw)
    check_unknown(d,["directory","file","symlink","mime_essence","extension","special"])
    out={}
    for k in ("directory","file","symlink"):
        out[k]=normalize_node_type(d[k]) if k in d else copy.deepcopy(ZERO_NODE_TYPES[k])
    # mime_essence: map<string,map<string,NodeType>>
    mime=d.get("mime_essence") or {}
    if not isinstance(mime,dict): err(f"invalid type: {type_name(mime,True)}, expected table")
    mime_out={}
    for maj,sub in mime.items():
        if not isinstance(sub,dict): err(f"invalid type: {type_name(sub,True)}, expected table")
        mime_out[str(maj)]={str(minor):normalize_node_type(nt) for minor,nt in sub.items()}
    out["mime_essence"]=mime_out
    for field in ("extension","special"):
        mp=d.get(field) or {}
        if not isinstance(mp,dict): err(f"invalid type: {type_name(mp,True)}, expected table")
        out[field]={str(k):normalize_node_type(v) for k,v in mp.items()}
    # field order as DEFAULT
    return {k:out[k] for k in DEFAULT_CONFIG["node_types"].keys()}

def normalize_layouts(raw):
    if raw is None: raw={}
    d=expect_table(raw); check_unknown(d,["builtin","custom"])
    out={}
    for sec in ("builtin","custom"):
        mp=d.get(sec) or {}
        if not isinstance(mp,dict): err(f"invalid type: {type_name(mp,True)}, expected table")
        out[sec]={str(k):normalize_layout(v) for k,v in mp.items()}
    return out

def normalize_modes(raw):
    if raw is None: raw={}
    d=expect_table(raw); check_unknown(d,["builtin","custom"])
    out={}
    for sec in ("builtin","custom"):
        mp=d.get(sec) or {}
        if not isinstance(mp,dict): err(f"invalid type: {type_name(mp,True)}, expected table")
        out[sec]={str(k):normalize_mode(v) for k,v in mp.items()}
    return out

def normalize_config(raw):
    if raw is None:
        err("invalid type: unit value, expected table")
    d=expect_table(raw)
    check_unknown(d,["general","node_types","layouts","modes"])
    return {
        "general":normalize_general(d.get("general")),
        "node_types":normalize_node_types(d.get("node_types")),
        "layouts":normalize_layouts(d.get("layouts")),
        "modes":normalize_modes(d.get("modes")),
    }

HOOK_FIELDS=["on_load","on_directory_change","on_focus_change","on_mode_switch","on_layout_switch","on_selection_change"]
def normalize_hooks(raw):
    result={k:[] for k in HOOK_FIELDS}
    if raw is None: return result
    if not isinstance(raw,dict):
        err(f"invalid type: {type_name(raw,True)}, expected table")
    check_unknown(raw,HOOK_FIELDS)
    for k in HOOK_FIELDS:
        if k not in raw: continue
        v=raw[k]
        if isinstance(v,dict) and not v: v=[]
        if not isinstance(v,list):
            err(f"invalid type: {type_name(v,True)}, expected table")
        msgs=[]
        for m in v:
            try: msgs.append(validate_message_py(m))
            except MsgError as e: err(str(e))
        result[k]=msgs
    return result
