# ---------- Validate messages from Python (Lua converted) values ----------
def _py_unexpected(v, for_table=False):
    if for_table:
        if isinstance(v,bool): return "boolean"
        if isinstance(v,int): return "integer"
        if isinstance(v,float): return "float"
        if isinstance(v,str): return "string"
        if v is None: return "unit value"
        return type(v).__name__
    return unexpected_str(v)

def _expected_fields(fields):
    if len(fields)==1: return f"`{fields[0]}`"
    if len(fields)==2: return f"`{fields[0]}` or `{fields[1]}`"
    return "one of "+", ".join(f"`{f}`" for f in fields)

def _py_string(v):
    if isinstance(v,str): return v
    raise MsgError(f"invalid type: {_py_unexpected(v)}, expected a string")
def _py_bool(v):
    if isinstance(v,bool): return v
    raise MsgError(f"invalid type: {_py_unexpected(v)}, expected a boolean")
def _py_usize(v):
    if isinstance(v,int) and not isinstance(v,bool):
        if v>=0: return v
        raise MsgError(f"invalid value: integer `{v}`, expected usize")
    if isinstance(v,float) and v.is_integer() and v>=0: return int(v)
    raise MsgError(f"invalid type: {_py_unexpected(v)}, expected usize")
def _py_char(v):
    if isinstance(v,str):
        if len(v)==1: return v
        raise MsgError(f'invalid value: string "{v}", expected a character')
    raise MsgError(f"invalid type: {_py_unexpected(v)}, expected a character")
def _py_enum(v,variants):
    if isinstance(v,str):
        if v in variants: return v
        raise MsgError(f"unknown variant `{v}`, expected one of {variants_list_str(variants)}")
    raise MsgError(f"invalid type: {_py_unexpected(v)}, expected variant identifier")
def _py_struct(v,struct_name,allowed):
    if not isinstance(v,dict):
        raise MsgError(f"invalid type: {_py_unexpected(v)}, expected struct {struct_name}")
    for k in v.keys():
        if k not in allowed:
            raise MsgError(f"unknown field `{k}`, expected {_expected_fields(allowed)}")
    return v

def _validate_input_op_py(v):
    if isinstance(v,str):
        if v not in INPUT_OPS_ALL: raise MsgError(f"unknown variant `{v}`, expected one of {variants_list_str(INPUT_OPS_ALL)}")
        if v in INPUT_OPS_UNIT: return v
        raise MsgError("invalid type: unit variant, expected newtype variant")
    if isinstance(v,dict):
        if len(v)!=1: raise MsgError("invalid value: map, expected map with a single key")
        name=next(iter(v)); val=v[name]
        if name not in INPUT_OPS_ALL: raise MsgError(f"unknown variant `{name}`, expected one of {variants_list_str(INPUT_OPS_ALL)}")
        if name in INPUT_OPS_UNIT:
            if val is None: return {name:None}
            raise MsgError("invalid type: map, expected unit variant")
        if name=="SetCursor": return {"SetCursor":_py_usize(val)}
        return {"InsertCharacter":_py_char(val)}
    raise MsgError(f"invalid type: {_py_unexpected(v)}, expected variant identifier")

def validate_message_py(v):
    if isinstance(v,str):
        if v not in VARIANTS: raise MsgError(f"unknown variant `{v}`, expected one of {variants_list_str(VARIANTS)}")
        if v in UNIT_VARIANTS: return v
        raise MsgError("invalid type: unit variant, expected newtype variant")
    if isinstance(v,dict):
        if len(v)!=1: raise MsgError("invalid value: map, expected map with a single key")
        name=next(iter(v)); val=v[name]
        if not isinstance(name,str) or name not in VARIANTS:
            raise MsgError(f"unknown variant `{name}`, expected one of {variants_list_str(VARIANTS)}")
        if name in UNIT_VARIANTS:
            # Lua {Quit=nil} can't exist; a dict val could be {} etc
            raise MsgError("invalid type: map, expected unit variant")
        return {name:_validate_payload_py(name,val)}
    raise MsgError(f"invalid type: {_py_unexpected(v)}, expected enum ExternalMsg")

def _validate_payload_py(name,val):
    if name in STRING_VARIANTS: return _py_string(val)
    if name in USIZE_VARIANTS: return _py_usize(val)
    if name in COMMAND_VARIANTS:
        f=_py_struct(val,"Command",["command","args"])
        if "command" not in f: raise MsgError("missing field `command`")
        out={"command":_py_string(f["command"])}
        if "args" in f:
            if not isinstance(f["args"],list): raise MsgError(f"invalid type: {_py_unexpected(f['args'])}, expected a sequence")
            out["args"]=[_py_string(x) for x in f["args"]]
        return out
    if name in FILTER_STRUCT_VARIANTS:
        f=_py_struct(val,"NodeFilterApplicableDeserializer",["filter","input"])
        for req in ("filter","input"):
            if req not in f: raise MsgError(f"missing field `{req}`")
        return {"filter":_py_enum(f["filter"],FILTERS),"input":_py_string(f["input"])}
    if name in FILTER_ENUM_VARIANTS: return _py_enum(val,FILTERS)
    if name in SORTER_STRUCT_VARIANTS:
        f=_py_struct(val,"NodeSorterApplicable",["sorter","reverse"])
        if "sorter" not in f: raise MsgError("missing field `sorter`")
        out={"sorter":_py_enum(f["sorter"],SORTERS)}
        if "reverse" in f: out["reverse"]=_py_bool(f["reverse"])
        return out
    if name in SORTER_ENUM_VARIANTS: return _py_enum(val,SORTERS)
    if name=="UpdateInputBuffer": return _validate_input_op_py(val)
    raise MsgError("unhandled variant")
