    return {"sorter":expect_enum(d["sorter"],SORTERS),"reverse":expect_bool(d["reverse"]) if "reverse" in d and d["reverse"] is not None else False}

def normalize_like(path, raw, sample, zero):
    # dispatch special paths
    if path==("general","initial_sorting"):
        if raw is None: return None
        if isinstance(raw,dict) and not raw: return []
        if not isinstance(raw,list): err(f"invalid type: {type_name(raw,True)}, expected table")
        return [normalize_sorter_applicable(x) for x in raw]
    if path==("general","global_key_bindings"):
        return normalize_keybindings(raw)
    if path in [("general","search","algorithm")]:
        return expect_enum(raw,["Fuzzy","Regex"])
    if path==("general","search","rank_criteria"):
        if raw is None: return None
        if isinstance(raw,dict) and not raw: return []
        vals=["Score","NegScore","Begin","NegBegin","End","NegEnd","Length","NegLength","Index","NegIndex"]
        return [expect_enum(x,vals) for x in raw]
    if path==("general","sort_and_filter_ui","sorter_identifiers"):
        return normalize_identifier_map(raw,SORTERS)
    if path==("general","sort_and_filter_ui","filter_identifiers"):
        return normalize_identifier_map(raw,FILTERS)
    if path==("general","sort_and_filter_ui","search_identifiers"):
        return normalize_identifier_map(raw,["Fuzzy","Regex"])
    if isinstance(sample,dict) and set(sample.keys())=={"fg","bg","add_modifiers","sub_modifiers"}:
        return normalize_style(raw)
    if len(path)>=2 and path[-2]=="panel_ui": # shouldn't happen, panel handled in general below
        return normalize_panel_ui(raw)
    if path[:2]==("general","panel_ui") and len(path)==3:
        return normalize_panel_ui(raw)
    if isinstance(sample,bool): return expect_bool(raw)
    if isinstance(sample,int) and not isinstance(sample,bool):
        return expect_int(raw,"u16")
    if isinstance(sample,str) or sample is None:
        # None sample in default means nullable string/int/enum. Some int nullable fields: identify by name
        if path[-1] in ("height","margin","horizontal_margin","vertical_margin","col_spacing","scroll_padding"):
            return expect_int(raw,"u16") if raw is not None else None
        if raw is None: return None
        return expect_str(raw)
    if isinstance(sample,list):
        if raw is None: return None
        if isinstance(raw,dict) and not raw: return []
        if not isinstance(raw,list): err(f"invalid type: {type_name(raw,True)}, expected table")
        if path==("general","table","col_widths"):
            return normalize_constraints(raw)
        elem_sample=sample[0] if sample else None
        elem_zero=zero[0] if isinstance(zero,list) and zero else None
        return [normalize_like(path+(f"[{i}]",),x,elem_sample,elem_zero) for i,x in enumerate(raw)]
    if isinstance(sample,dict):
        if raw is None: return copy.deepcopy(zero)
        d=expect_table(raw)
        if not sample:
            # arbitrary map; values keep generic normalize to raw (identifier maps handled above)
            return copy.deepcopy(raw)
        check_unknown(d,list(sample.keys()))
        out=copy.deepcopy(zero) if isinstance(zero,dict) else {}
        # ensure all sample keys present in out in sample order
        result={}
        for k in sample.keys():
            if k in d:
                result[k]=normalize_like(path+(k,),d[k],sample[k],zero.get(k) if isinstance(zero,dict) else None)
            else:
                result[k]=copy.deepcopy(zero.get(k) if isinstance(zero,dict) else None)
        return result
    return raw

def normalize_identifier_map(raw,keys):
    if raw is None: return {}
    d=expect_table(raw)
    out={}
    for k,v in d.items():
        ek=expect_enum(k,keys); out[ek]=normalize_identifier(v)
    return out

def normalize_general(raw):
    if raw is None: raw={}
    d=expect_table(raw)
    sample=DEFAULT_CONFIG["general"]; check_unknown(d,list(sample.keys()))
    out={}
    for k in sample.keys():
        if k in d: out[k]=normalize_like(("general",k),d[k],sample[k],ZERO_GENERAL.get(k))
        else: out[k]=copy.deepcopy(ZERO_GENERAL.get(k))
    return out

def normalize_node_types(raw):
    if raw is None: raw={}
    d=expect_table(raw)
    check_unknown(d,["directory","file","symlink","mime_essence","extension","special"])
    out={}
    for k in ("directory","file","symlink"):
        out[k]=normalize_node_type(d[k]) if k in d else copy.deepcopy(ZERO_NODE_TYPES[k])
    # mime_essence: map<string,map<string,NodeType>>
    mime=d.get("mime_essence") or {}
    if not isinstance(mime,dict): err(f"invalid type: {type_name(mime,True)}, expected table")
    mime_out={}
    for maj,sub in mime.items():
        if not isinstance(sub,dict): err(f"invalid type: {type_name(sub,True)}, expected table")
        mime_out[str(maj)]={str(minor):normalize_node_type(nt) for minor,nt in sub.items()}
    out["mime_essence"]=mime_out
    for field in ("extension","special"):
        mp=d.get(field) or {}
        if not isinstance(mp,dict): err(f"invalid type: {type_name(mp,True)}, expected table")
        out[field]={str(k):normalize_node_type(v) for k,v in mp.items()}
    # field order as DEFAULT
    return {k:out[k] for k in DEFAULT_CONFIG["node_types"].keys()}

def normalize_layouts(raw):
    if raw is None: raw={}
    d=expect_table(raw); check_unknown(d,["builtin","custom"])
    out={}
    for sec in ("builtin","custom"):
        mp=d.get(sec) or {}
        if not isinstance(mp,dict): err(f"invalid type: {type_name(mp,True)}, expected table")
        out[sec]={str(k):normalize_layout(v) for k,v in mp.items()}
    return out

def normalize_modes(raw):
    if raw is None: raw={}
    d=expect_table(raw); check_unknown(d,["builtin","custom"])
    out={}
    for sec in ("builtin","custom"):
        mp=d.get(sec) or {}
        if not isinstance(mp,dict): err(f"invalid type: {type_name(mp,True)}, expected table")
        out[sec]={str(k):normalize_mode(v) for k,v in mp.items()}
    return out

def normalize_config(raw):
    if raw is None:
        err("invalid type: unit value, expected table")
    d=expect_table(raw)
    check_unknown(d,["general","node_types","layouts","modes"])
    return {
        "general":normalize_general(d.get("general")),
        "node_types":normalize_node_types(d.get("node_types")),
        "layouts":normalize_layouts(d.get("layouts")),
        "modes":normalize_modes(d.get("modes")),
    }

HOOK_FIELDS=["on_load","on_directory_change","on_focus_change","on_mode_switch","on_layout_switch","on_selection_change"]
def normalize_hooks(raw):
    result={k:[] for k in HOOK_FIELDS}
    if raw is None: return result
    if not isinstance(raw,dict):
        err(f"invalid type: {type_name(raw,True)}, expected table")
    check_unknown(raw,HOOK_FIELDS)
    for k in HOOK_FIELDS:
        if k not in raw: continue
        v=raw[k]
        if isinstance(v,dict) and not v: v=[]
        if not isinstance(v,list):
            err(f"invalid type: {type_name(v,True)}, expected table")
        msgs=[]
        for m in v:
            try: msgs.append(validate_message_py(m))
            except MsgError as e: err(str(e))
        result[k]=msgs
    return result
