def home_dir():
    return os.path.expanduser("~")

def path_absolute(path, cwd=None):
    return absolutize(path, cwd or os.getcwd())

def path_components(path):
    # Rust Path.components on Unix: RootDir, CurDir omitted except initial? Examples: .././foo => [..,foo]; ./foo => [foo]? Rust components normalizes away . except at beginning? It yields CurDir for "./" alone.
    # Implement normalized components preserving .. tokens, removing . and empty, retain leading /
    is_abs=path.startswith("/")
    parts=[]
    for p in path.split("/"):
        if p in ("","."): continue
        parts.append(p)
    return (["/"]+parts) if is_abs else parts

def relpath_components(path_abs, base_abs):
    p=path_components(path_abs); b=path_components(base_abs)
    # remove root markers for comparison but both absolute
    if p and p[0]=="/": p=p[1:]
    if b and b[0]=="/": b=b[1:]
    i=0
    while i<len(p) and i<len(b) and p[i]==b[i]: i+=1
    rel=[".."]*(len(b)-i)+p[i:]
    return rel

def relative_to(path, base=None, with_prefix_dots=False, without_suffix_dots=False, cwd=None):
    trailing=path.endswith("/") and len(path)>1
    p_abs=path_absolute(path,cwd)
    b_abs=path_absolute(base,cwd) if base else (cwd or os.getcwd())
    rel=relpath_components(p_abs,b_abs)
    if not rel:
        result="."
        if without_suffix_dots:
            base_name=os.path.basename(p_abs)
            result="../"+base_name if base_name else ".."
    else:
        result="/".join(rel)
        if without_suffix_dots and all(x==".." for x in rel):
            base_name=os.path.basename(p_abs)
            if base_name:
                result=result+"/../"+base_name
    if with_prefix_dots and not result.startswith("."):
        result="./"+result
    if trailing and not result.endswith("/"):
        result+="/"
    return result

def shorten(path, options=None, cwd=None):
    options=options or {}
    base=options.get("base") if isinstance(options,dict) else None
    with_dots=options.get("with_prefix_dots") if isinstance(options,dict) else None
    without_dots=options.get("without_suffix_dots") if isinstance(options,dict) else None
    trailing=path.endswith("/") and len(path)>1
    p_abs=path_absolute(path,cwd)
    abs_candidate=p_abs+("/" if trailing else "")
    rel_candidate=relative_to(path,base=base,with_prefix_dots=bool(with_dots),without_suffix_dots=bool(without_dots),cwd=cwd)
    candidates=[]
    # home candidate
    home=home_dir()
    home_candidate=None
    if home and home!="/":
        if p_abs==home:
            home_candidate="~"+("/" if trailing else "")
        elif p_abs.startswith(home+"/"):
            home_candidate="~/"+p_abs[len(home)+1:]+("/" if trailing else "")
    # Choose shortest; tie preference home, relative, absolute based observed examples
    cand=[]
    if home_candidate: cand.append(home_candidate)
    cand.append(rel_candidate); cand.append(abs_candidate)
    return min(cand, key=lambda x: len(x))

def resolve_node_type(node, node_types):
    # node_types normalized config
    styles=[]; metas=[]
    if node is None:
        return {"style":{},"meta":{}}
    base=None
    if node.get("is_symlink"): base=node_types.get("symlink")
    elif node.get("is_dir"): base=node_types.get("directory")
    elif node.get("is_file"): base=node_types.get("file")
    if base: styles.append(base.get("style") or {}); metas.append(base.get("meta") or {})
    # mime
    mime=node.get("mime_essence") or ""
    mime_cfg=node_types.get("mime_essence") or {}
    chosen=None
    if "/" in mime:
        maj,minr=mime.split("/",1)
        sub=mime_cfg.get(maj) or {}
        if isinstance(sub,dict):
            if minr in sub: chosen=sub[minr]
            elif "*" in sub: chosen=sub["*"]
    if chosen: styles.append(chosen.get("style") or {}); metas.append(chosen.get("meta") or {})
    ext=node.get("extension") or ""
    ext_cfg=node_types.get("extension") or {}
    if ext in ext_cfg and isinstance(ext_cfg[ext],dict):
        styles.append(ext_cfg[ext].get("style") or {}); metas.append(ext_cfg[ext].get("meta") or {})
    spec=node_types.get("special") or {}
    rel=node.get("relative_path")
    if rel in spec and isinstance(spec[rel],dict):
        styles.append(spec[rel].get("style") or {}); metas.append(spec[rel].get("meta") or {})
    style=py_style_mix(styles)
    # style_mix returns only non-null fields; host table conversion expects that.
    meta={}
    for m in metas: meta.update(m)
    return {"style":style,"meta":meta}

def permissions_rwx(perm):
    if not isinstance(perm,dict): perm={}
    def tri(u,read,write,exec_,special,lower,upper):
        out=""
        out+="r" if perm.get(read) else "-"
        out+="w" if perm.get(write) else "-"
        x=bool(perm.get(exec_)); sp=bool(perm.get(special))
        if sp: out+= lower if x else upper
        else: out+= "x" if x else "-"
        return out
    return tri(0,"user_read","user_write","user_execute","setuid","s","S")+tri(0,"group_read","group_write","group_execute","setgid","s","S")+tri(0,"other_read","other_write","other_execute","sticky","t","T")

def permissions_octal(perm):
    if not isinstance(perm,dict): perm={}
    def val(r,w,x): return (4 if perm.get(r) else 0)+(2 if perm.get(w) else 0)+(1 if perm.get(x) else 0)
    special=(4 if perm.get("setuid") else 0)+(2 if perm.get("setgid") else 0)+(1 if perm.get("sticky") else 0)
    return [special,val("user_read","user_write","user_execute"),val("group_read","group_write","group_execute"),val("other_read","other_write","other_execute")]

class LuaHost:
