        # dirname("foo") returns "" in probe (quoted empty) - lambda above returns "" for foo. For "/" it returns None (empty return in show). Good.
        self._reg_util("basename", lambda st,args:[os.path.basename(args[0].rstrip("/")) if args and args[0]!="/" and os.path.basename(args[0].rstrip("/"))!="" else None])
        self._reg_util("absolute", lambda st,args:[path_absolute(args[0])])
