    def _deep_clone(self,v,seen=None):
        if seen is None: seen={}
        if isinstance(v,LuaTable):
            if id(v) in seen: return seen[id(v)]
            t=LuaTable(); seen[id(v)]=t; t.metatable=v.metatable
            for k,val in v.keys_values(): t.set(self._deep_clone(k,seen) if isinstance(k,LuaTable) else k,self._deep_clone(val,seen))
            return t
        return v
    def _util_debug(self,st,args):
        v=args[0] if args else None
        s=lua_inspect(v,st)
        # original prints to console - during CallLua stdout is terminal, during config it's process stdout before UI
        st.stdout_write(s+"\n")
        return [s]
    def _util_node(self,st,args):
        path=args[0] if args else ""
        abs_path=path_absolute(path)
        if abs_path=="/": return [None]
        n=node_from_path(abs_path)
        return [python_to_lua(n) if n else None]
    def _util_node_type(self,st,args):
        node=lua_to_python_generic(args[0]) if args else None
        if len(args)>1 and args[1] is not None:
            raw=lua_to_python_generic(args[1])
            try: nts=normalize_node_types(raw)
            except Exception: nts=self.config_snapshot.get("node_types",{})
        else:
            # get global xplr.config.node_types as per docs, but fall back snapshot
            try:
                cfg_table=self.xplr.get("config"); nt_table=cfg_table.get("node_types") if isinstance(cfg_table,LuaTable) else None
                raw=lua_to_python_generic(nt_table); nts=normalize_node_types(raw)
            except Exception:
                nts=self.config_snapshot.get("node_types",{})
        return [python_to_lua(resolve_node_type(node,nts))]
