        return [shorten(path,opts if isinstance(opts,dict) else {})]
    def _util_explore(self,st,args):
        path=args[0] if args else "."
        cfg=lua_to_python_generic(args[1]) if len(args)>1 and args[1] is not None else {}
        explorer={"filters":[],"sorters":[],"searcher":None}
        if isinstance(cfg,dict):
            if isinstance(cfg.get("filters"),list): explorer["filters"]=cfg["filters"]
            if isinstance(cfg.get("sorters"),list): explorer["sorters"]=[{"sorter":s.get("sorter"),"reverse":bool(s.get("reverse",False))} if isinstance(s,dict) else s for s in cfg["sorters"]]
            if cfg.get("searcher") is not None:
                sch=dict(cfg["searcher"]) if isinstance(cfg["searcher"],dict) else {}
                sch.setdefault("algorithm","Fuzzy"); sch.setdefault("unordered",False); sch.setdefault("exact_mode",False); sch.setdefault("rank_criteria",None); sch.setdefault("recoverable_focus",None)
                explorer["searcher"]=sch
        abs_path=path_absolute(path)
        try: nodes=explore_dir(abs_path,explorer)
        except OSError as e: raise LuaError(os_error_str(e))
        return [python_to_lua(nodes)]
    def _util_shell_execute(self,st,args):
        prog=args[0]; a=lua_to_python_generic(args[1]) if len(args)>1 and args[1] is not None else []
