    def _deep_clone(self,v,seen=None):
        if seen is None: seen={}
        if isinstance(v,LuaTable):
            if id(v) in seen: return seen[id(v)]
            t=LuaTable(); seen[id(v)]=t; t.metatable=v.metatable
            for k,val in v.keys_values(): t.set(self._deep_clone(k,seen) if isinstance(k,LuaTable) else k,self._deep_clone(val,seen))
            return t
        return v
    def _util_debug(self,st,args):
        v=args[0] if args else None
        s=lua_inspect(v,st)
        # original prints to console - during CallLua stdout is terminal, during config it's process stdout before UI
        st.stdout_write(s+"\n")
        return [s]
    def _util_node(self,st,args):
        path=args[0] if args else ""
        abs_path=path_absolute(path)
        if abs_path=="/": return [None]
        n=node_from_path(abs_path)
        return [python_to_lua(n) if n else None]
    def _util_node_type(self,st,args):
        node=lua_to_python_generic(args[0]) if args else None
        if len(args)>1 and args[1] is not None:
            raw=lua_to_python_generic(args[1])
            try: nts=normalize_node_types(raw)
            except Exception: nts=self.config_snapshot.get("node_types",{})
        else:
            # get global xplr.config.node_types as per docs, but fall back snapshot
            try:
                cfg_table=self.xplr.get("config"); nt_table=cfg_table.get("node_types") if isinstance(cfg_table,LuaTable) else None
                raw=lua_to_python_generic(nt_table); nts=normalize_node_types(raw)
            except Exception:
                nts=self.config_snapshot.get("node_types",{})
        return [python_to_lua(resolve_node_type(node,nts))]
    def _util_relative_to(self,st,args):
        path=args[0]; opts=lua_to_python_generic(args[1]) if len(args)>1 and args[1] is not None else {}
        if not isinstance(opts,dict): opts={}
        return [relative_to(path,base=opts.get("base"),with_prefix_dots=bool(opts.get("with_prefix_dots")),without_suffix_dots=bool(opts.get("without_suffix_dots")))]
    def _util_shorten(self,st,args):
        path=args[0]; opts=lua_to_python_generic(args[1]) if len(args)>1 and args[1] is not None else {}
        return [shorten(path,opts if isinstance(opts,dict) else {})]
    def _util_explore(self,st,args):
        path=args[0] if args else "."
        cfg=lua_to_python_generic(args[1]) if len(args)>1 and args[1] is not None else {}
        explorer={"filters":[],"sorters":[],"searcher":None}
        if isinstance(cfg,dict):
            if isinstance(cfg.get("filters"),list): explorer["filters"]=cfg["filters"]
            if isinstance(cfg.get("sorters"),list): explorer["sorters"]=[{"sorter":s.get("sorter"),"reverse":bool(s.get("reverse",False))} if isinstance(s,dict) else s for s in cfg["sorters"]]
            if cfg.get("searcher") is not None:
                sch=dict(cfg["searcher"]) if isinstance(cfg["searcher"],dict) else {}
                sch.setdefault("algorithm","Fuzzy"); sch.setdefault("unordered",False); sch.setdefault("exact_mode",False); sch.setdefault("rank_criteria",None); sch.setdefault("recoverable_focus",None)
                explorer["searcher"]=sch
        abs_path=path_absolute(path)
        try: nodes=explore_dir(abs_path,explorer)
        except OSError as e: raise LuaError(os_error_str(e))
        return [python_to_lua(nodes)]
    def _util_shell_execute(self,st,args):
        prog=args[0]; a=lua_to_python_generic(args[1]) if len(args)>1 and args[1] is not None else []
        if isinstance(a,dict) and not a: a=[]
        try:
            p=subprocess.run([prog]+list(a),capture_output=True,text=True,encoding='utf-8',errors='surrogateescape')
            rc=p.returncode if p.returncode>=0 else None
            return [python_to_lua({"stdout":p.stdout,"stderr":p.stderr,"returncode":rc})]
        except OSError as e:
            return [python_to_lua({"stdout":"","stderr":str(e),"returncode":None})]
    def _util_from_json(self,st,args):
        try: v=json.loads(args[0])
        except Exception as e: raise LuaError(str(e))
        return [python_to_lua_generic(v)]
    def _util_to_json(self,st,args):
        v=lua_to_python_generic(args[0]) if args else None
        opts=lua_to_python_generic(args[1]) if len(args)>1 and args[1] is not None else {}
        pretty=isinstance(opts,dict) and opts.get("pretty")
        if pretty: return [json.dumps(v,ensure_ascii=False,indent=2)]
        return [json.dumps(v,ensure_ascii=False,separators=(',',':'))]
    def _util_from_yaml(self,st,args):
        try: node=parse_yaml(args[0]); v=generic_value(node)
        except YamlError as e: raise LuaError(str(e))
        return [python_to_lua_generic(v)]
    def _util_lscolor(self,st,args):
        path=args[0] if args else ""
        return [python_to_lua(lscolor_style(path))]
    def _util_textwrap(self,st,args):
        text=args[0] if args else ""; opts=args[1] if len(args)>1 else 0
        if isinstance(opts,(int,float)):
            width=int(opts); initial=""; subsequent=""; break_words=True
        elif isinstance(opts,LuaTable):
            width=int(opts.get("width") or 0); initial=opts.get("initial_indent") or ""; subsequent=opts.get("subsequent_indent") or ""; break_words=opts.get("break_words"); break_words=True if break_words is None else bool(break_words)
        else:
            width=0; initial=""; subsequent=""; break_words=True
        if width<=0: return [python_to_lua([text])]
        # textwrap crate behavior: try not split words unless break_words.
        wrapper=_textwrap.TextWrapper(width=width,initial_indent=initial,subsequent_indent=subsequent,break_long_words=break_words,break_on_hyphens=False,expand_tabs=False,replace_whitespace=False,drop_whitespace=True)
        lines=wrapper.wrap(text) or [""]
        return [python_to_lua(lines)]
    def _util_layout_replace(self,st,args):
        layout=lua_to_python_generic(args[0]); target=lua_to_python_generic(args[1]); repl=lua_to_python_generic(args[2])
        def rec(x):
            if x==target: return copy.deepcopy(repl)
            if isinstance(x,dict): return {k:rec(v) for k,v in x.items()}
            if isinstance(x,list): return [rec(v) for v in x]
            return x
        return [python_to_lua(rec(layout))]
    # ---------- config loading ----------
    def lua_config_python(self):
        cfg=self.xplr.get("config")
        return lua_to_python_generic(cfg)
    def load_config_file(self,path):
        """Returns error message string or None. Modifies snapshot/hooks on success."""
        try:
            with open(path,"rb") as f: data=f.read()
        except OSError as e:
            return os_error_str(e)
        try:
            result=self.state.execute_file_contents(data,path)
        except LuaError as e:
            return self.state.format_error_for_log(e)
        # deserialize hooks from return value
        ret=result[0] if result else None
        try:
            hooks=normalize_hooks(lua_to_python_generic(ret))
        except ConfigError as e:
            return str(e)
        # version check
        ver=self.state.globals.get("version")
        if not isinstance(ver,str):
            return f"'version' must be defined globally in {path}"
        vcheck=check_version(ver,path)
        if vcheck: return vcheck
        # deserialize config
        try:
            raw=self.lua_config_python()
            new_config=normalize_config(raw)
        except ConfigError as e:
            return str(e)
        except Exception as e:
            return f"deserialize error: {e}"
        self.config_snapshot=new_config
        for k in self.hooks: self.hooks[k].extend(hooks.get(k,[]))
        return None
    def get_lua_function(self, dotted):
        # dotted relative to xplr.fn: e.g. "custom.foo", "builtin.fmt..."
        parts=dotted.split(".") if dotted else []
        cur=self.xplr.get("fn")
        for p in parts:
            if isinstance(cur,LuaTable): cur=cur.get(p)
            else: return None
        return cur
    def call_lua_function(self,dotted,app_context_lua):
        fn=self.get_lua_function(dotted)
        if fn is None:
            raise LuaError(f"function '{dotted}' not found")
        return self.state.call_value(fn,[app_context_lua])
    def lua_eval(self,code,app_context_lua=None):
        # Original semantics: load code as chunk; if result callable, call with app context; else result is messages / nil.
        # Chunk name? Probe later: use "LuaEval" maybe.
        result=self.state.execute(code,"LuaEval")
        first=result[0] if result else None
        if isinstance(first,(LuaFunction,NativeFunction)) or (first is not None and self.state.get_metamethod(first,"__call") is not None):
            return self.state.call_value(first,[app_context_lua])
        return result

def check_version(ver,path):
    # Parse like Rust: split on '.' and '-'? Deduced behaviour: see probes.
    # Implement parser: split string by '.'; first three components parse as u16 but patch may contain '-' suffix ignored? 1.1.0-1 passed; 1.1.-1 gave empty parse.
    # Approach: tokens = re.split('[.-]', ver) ? 1.1.0-1 => [1,1,0,1]; compat if first3 componentwise major==, minor<=, patch<= and len(tokens)==3? But 1.1.0-1 len4 passed while 1.1.0.0 len4 via dots failed incompatible.
    # Maybe parser: split('.') => parts; for patch part split('-')[0]; if len(parts)!=3 => incompatible (not parse error if >3, parse error if <3 due get_or empty).
    parts=ver.split(".")
    def parse_int(s):
        if s=="": raise ValueError("cannot parse integer from empty string")
        if not re.match(r'^[0-9]+$',s): raise ValueError("invalid digit found in string")
        n=int(s)
        if n>65535: raise ValueError("number too large to fit in target type")
        return n
    try:
        major=parse_int(parts[0] if len(parts)>0 else "")
        minor=parse_int(parts[1] if len(parts)>1 else "")
        patch_raw=parts[2] if len(parts)>2 else ""
        patch=parse_int(patch_raw.split("-")[0])
        # If patch_raw has '-' and the part before came from "1.1.-1": parts[2] is "-1"? split '.' gives ['1','1','-1'], split('-')[0] is "" => empty error matches probe.
        # Extra dot parts: still parse them? 1.1.0.0 -> incompatible below due len.
        for extra in parts[3:]:
            parse_int(extra.split("-")[0])
    except ValueError as e:
        return str(e)
    req=(1,1,0)
    compatible = (major==req[0] and minor<=req[1] and patch<=req[2] and len(parts)==3)
    if compatible: return None
    return f"incompatible script version in: {path}. The script version is: {ver}, the required version is: {VERSION}. Visit https://xplr.dev/en/upgrade-guide"

def shell_quote(s):
    # Observed always single quotes even simple strings
    return "'" + s.replace("'","'\"'\"'") + "'"
def shell_escape(s):
    # shell_words / shlex? Observed simple abc unquoted, a'b"c -> "a'b\"c"
    if s and re.match(r'^[a-zA-Z0-9_\-./:]+$',s): return s
    return '"' + s.replace('\\','\\\\').replace('"','\\"').replace('$','\\$').replace('`','\\`') + '"'

def lua_inspect(v,st,indent=0,seen=None):
    if seen is None: seen=set()
    pad="  "*(indent+1)
    if isinstance(v,LuaTable):
        if id(v) in seen: return "{...}"
        seen.add(id(v))
        items=v.keys_values()
        if not items: return "{}"
        lines=["{"]
        # positional first? original inspect sorts keys maybe by string repr. Use insertion but sort string keys? Debug output observed foo,list,n (hash). Use sorted by tostring key for determinism.
        def key_repr(k):
            if isinstance(k,str) and re.match(r'^[A-Za-z_][A-Za-z0-9_]*$',k): return k
            if isinstance(k,int): return None  # positional no key
            return "["+lua_inspect(k,st,indent+1,seen)+"]"
        # Print array items in order then others as stored
        for k,val in items:
            kr=key_repr(k)
            prefix=(kr+" = ") if kr else ""
            lines.append(pad+prefix+lua_inspect(val,st,indent+1,seen)+",")
        lines.append("  "*indent+"}")
        return "\n".join(lines)
    if isinstance(v,str):
        return '"' + v.replace('\\','\\\\').replace('"','\\"').replace('\n','\\n') + '"'
    return lua_tostring(v,st)

def lscolor_style(path):
    # Parse LS_COLORS (gnu) plus lscolors crate defaults minimal.
    env=os.environ.get("LS_COLORS")
    defaults={"di":"01;34","ln":"01;36","pi":"33","so":"01;35","ex":"01;32","bd":"01;33","cd":"01;33","or":"","mi":"","fi":"0","*.tar":"01;31","*.zip":"01;31","*.jpg":"01;35","*.png":"01;35"}
    mapping=dict(defaults)
    if env:
        for part in env.split(":"):
            if "=" in part:
                k,v=part.split("=",1); mapping[k]=v
    # Determine indicator
    try:
        lst=os.lstat(path)
    except OSError:
        code=mapping.get("mi") or mapping.get("or") or ""
        return ansi_to_style(code)
    import stat as _stat
    mode=lst.st_mode
    code=""
    if _stat.S_ISLNK(mode):
        if not os.path.exists(path) and mapping.get("or"): code=mapping["or"]
        else: code=mapping.get("ln","")
    elif _stat.S_ISDIR(mode): code=mapping.get("di","")
    elif _stat.S_ISFIFO(mode): code=mapping.get("pi","")
    elif _stat.S_ISSOCK(mode): code=mapping.get("so","")
    elif _stat.S_ISBLK(mode): code=mapping.get("bd","")
    elif _stat.S_ISCHR(mode): code=mapping.get("cd","")
    else:
        # extension pattern
        name=os.path.basename(path)
        matched=None
        for k,v in mapping.items():
            if k.startswith("*.") and name.endswith(k[1:]):
                matched=v; break
            if k.startswith("*") and name.endswith(k[1:]):
                matched=v
        if matched is not None: code=matched
        elif mode & 0o111: code=mapping.get("ex","")
        else: code=mapping.get("fi","")
    return ansi_to_style(code)

def ansi_to_style(code):
    if not code: return {}
    nums=[]
    for p in code.split(";"):
        try: nums.append(int(p) if p!="" else 0)
        except: pass
    style={}; i=0
    named={30:"Black",31:"Red",32:"Green",33:"Yellow",34:"Blue",35:"Magenta",36:"Cyan",37:"Gray",90:"DarkGray",91:"LightRed",92:"LightGreen",93:"LightYellow",94:"LightBlue",95:"LightMagenta",96:"LightCyan",97:"White"}
    bg_named={40:"Black",41:"Red",42:"Green",43:"Yellow",44:"Blue",45:"Magenta",46:"Cyan",47:"Gray",100:"DarkGray",101:"LightRed",102:"LightGreen",103:"LightYellow",104:"LightBlue",105:"LightMagenta",106:"LightCyan",107:"White"}
    while i<len(nums):
        n=nums[i]
        if n in named: style["fg"]=named[n]
        elif n in bg_named: style["bg"]=bg_named[n]
        elif n==39: style.pop("fg",None)
        elif n==49: style.pop("bg",None)
        elif n==38 and i+1<len(nums):
            if nums[i+1]==5 and i+2<len(nums): style["fg"]={"Indexed":nums[i+2]}; i+=2
            elif nums[i+1]==2 and i+4<len(nums): style["fg"]={"Rgb":[nums[i+2],nums[i+3],nums[i+4]]}; i+=4
        elif n==48 and i+1<len(nums):
            if nums[i+1]==5 and i+2<len(nums): style["bg"]={"Indexed":nums[i+2]}; i+=2
            elif nums[i+1]==2 and i+4<len(nums): style["bg"]={"Rgb":[nums[i+2],nums[i+3],nums[i+4]]}; i+=4
        i+=1
    return style
