def now_log_created():
    now=datetime.datetime.now().astimezone()
    # nanoseconds from time.time_ns fractional align
    ns=time.time_ns()%1000000000
    offset=now.utcoffset() or datetime.timedelta(0)
    total=int(offset.total_seconds())
    sign=1
    # serde time OffsetDateTime components (hours, minutes, seconds as signed each?) For UTC all zero. For negative offsets each component may be negative; approximate.
    oh=total//3600; rem=total-oh*3600; om=rem//60; os_=rem-om*60
    if total<0:
        # Components in time crate UtcOffset are (h,m,s) all with sign of offset - recompute
        a=abs(total); oh=-(a//3600); om=-((a%3600)//60); os_=-(a%60)
    return [now.year, now.timetuple().tm_yday, now.hour, now.minute, now.second, ns, oh, om, os_]

def format_log_timestamp(created):
    y,ordinal,h,mi,s,ns,oh,om,os_ = created
    date=datetime.date(y,1,1)+datetime.timedelta(days=ordinal-1)
    # offset display signs: time crate formats +00:00:00; for negative all components negative (?) construct sign from oh
    sign="+" if (oh,om,os_)==(0,0,0) or oh>=0 and not (oh==0 and om<0) else "-"
    return f"{date.isoformat()} {h}:{mi:02d}:{s:02d}.{ns:09d} {sign}{abs(oh):02d}:{abs(om):02d}:{abs(os_):02d}"

