    def _focus_path_internal_no_cd(self,abs_path):
        # Focus a path expected in current pwd, without history pushes (for Accept/Cancel search after explore)
        if abs_path=="/": return
        parent=os.path.dirname(abs_path) or "/"
        if parent!=self.pwd:
            # Use focus path without history to navigate
            self._focus_path_internal(abs_path,push_history=False); return
        self._focus_by_file_name_internal(os.path.basename(abs_path),push_history=False)
    def _set_searcher(self,pattern,kind):
        general_search=self.config["general"].get("search") or {}
        if kind=="Search":
            algo=general_search.get("algorithm") or "Fuzzy"; unordered=bool(general_search.get("unordered",False))
        elif kind=="SearchFuzzy": algo="Fuzzy"; unordered=False
        elif kind=="SearchFuzzyUnordered": algo="Fuzzy"; unordered=True
        elif kind=="SearchRegex": algo="Regex"; unordered=False
        elif kind=="SearchRegexUnordered": algo="Regex"; unordered=True
        else: algo="Fuzzy"; unordered=False
        existing=self.explorer_config.get("searcher")
        if existing and existing.get("recoverable_focus") is not None:
            recover=existing.get("recoverable_focus")
        else:
            focused=self.focused_node(); recover=focused["absolute_path"] if focused else None
        self.explorer_config["searcher"]={
            "pattern":pattern,
            "recoverable_focus":recover,
            "algorithm":algo,
            "unordered":unordered,
            "exact_mode":bool(general_search.get("exact_mode",False)),
            "rank_criteria":copy.deepcopy(general_search.get("rank_criteria")),
        }
    def _focus_next(self,step=1):
        db=self.directory_buffer
        if not db or not db["nodes"]: return
        total=len(db["nodes"]); idx=db["focus"]+step
        if self.config["general"].get("enforce_bounded_index_navigation"):
            idx=max(0,min(idx,total-1))
        else:
            idx=idx%total
        db["focus"]=idx
    def _focus_selection(self,next_=True):
        if not self.selection: return
        focused=self.focused_node(); cur_abs=focused["absolute_path"] if focused else None
        idx=None
        for i,n in enumerate(self.selection):
            if n["absolute_path"]==cur_abs: idx=i; break
        if idx is None:
            target=self.selection[0] if next_ else self.selection[-1]
        else:
            target=self.selection[(idx+1)%len(self.selection)] if next_ else self.selection[(idx-1)%len(self.selection)]
        # Original navigates to selected path even outside dir. Use focus_path but only if parent exists as dir (avoid log spam for nonexist selections probe: it did nothing)
        parent=os.path.dirname(target["absolute_path"]) or "/"
        if os.path.isdir(parent):
            self._focus_path_internal(target["absolute_path"],True)
    def _visited(self,delta):
        self._save_last_focus()
        h=self.history
        if not h["paths"]: return
        if delta<0 and h["loc"]>0: h["loc"]-=1
        elif delta>0 and h["loc"] < len(h["paths"])-1: h["loc"]+=1
        target=h["paths"][h["loc"]]
        self._visit_path_no_history(target)
    def _visit_path_no_history(self,target):
        # Directory entries end with '/' except root '/'
        if target=="/" or (target.endswith("/") and os.path.isdir(target)):
            path=target.rstrip("/") or "/"
            if path!=self.pwd:
                self._change_directory_internal(path,push_history_entry=False)
            else:
                # Re-explore / refocus based on last_focus saved
                self._explore_pwd()
        else:
            self._focus_path_internal(target,push_history=False)
    def _deep_branch(self,delta):
