    # ----- input helpers -----
    def _key_char(self):
        k=self._last_key
        if isinstance(k,dict):
            if k.get("char") and len(k["char"])==1 and not k.get("ctrl") and not k.get("alt"):
                return k["char"]
            if k.get("name")=="space": return " "
        return None
    def _update_input_from_key(self):
        k=self._last_key
        if not isinstance(k,dict): return
        name=k.get("name"); ch=k.get("char")
        ctrl=bool(k.get("ctrl")); alt=bool(k.get("alt"))
        op=None; arg=None
        if alt:
            return
        if ctrl:
            mapping={"a":"GoToStart","e":"GoToEnd","b":"GoToPreviousCharacter","f":"GoToNextCharacter","h":"DeletePreviousCharacter","d":"DeleteNextCharacter","w":"DeletePreviousWord","u":"DeleteLine","k":"DeleteTillEnd"}
            if name in ("ctrl-left",): op="GoToPreviousWord"
            elif name in ("ctrl-right",): op="GoToNextWord"
            elif ch in mapping: op=mapping[ch]
            else: return
            self._update_input_buffer(op); return
        if name=="backspace": op="DeletePreviousCharacter"
        elif name=="delete": op="DeleteNextCharacter"
        elif name=="left": op="GoToPreviousCharacter"
        elif name=="right": op="GoToNextCharacter"
        elif name=="home": op="GoToStart"
        elif name=="end": op="GoToEnd"
        elif ch and len(ch)==1:
            self._update_input_buffer({"InsertCharacter":ch}); return
        elif name=="space":
            self._update_input_buffer({"InsertCharacter":" "}); return
        else:
            return
        self._update_input_buffer(op)
    def _update_input_buffer(self,op_payload):
        # op_payload is string or {SetCursor:n}/{InsertCharacter:c}
        b=self.input.get("buffer")
        if isinstance(op_payload,dict):
            if "InsertCharacter" in op_payload:
                ch=op_payload["InsertCharacter"]
                if b is None:
                    self.input["buffer"]={"value":ch,"cursor":1}; return
                val=b["value"]; cur=b["cursor"]; b["value"]=val[:cur]+ch+val[cur:]; b["cursor"]=cur+1; return
            if "SetCursor" in op_payload:
                if b is not None: b["cursor"]=max(0,min(int(op_payload["SetCursor"]),len(b["value"])))
                return
            return
        op=op_payload
        if b is None: return
        val=b["value"]; cur=b["cursor"]
        if op=="GoToPreviousCharacter": b["cursor"]=max(0,cur-1)
        elif op=="GoToNextCharacter": b["cursor"]=min(len(val),cur+1)
        elif op=="GoToStart": b["cursor"]=0
        elif op=="GoToEnd": b["cursor"]=len(val)
        elif op=="GoToPreviousWord": b["cursor"]=_word_prev(val,cur)
        elif op=="GoToNextWord": b["cursor"]=_word_next(val,cur)
        elif op=="DeletePreviousCharacter":
            if cur>0: b["value"]=val[:cur-1]+val[cur:]; b["cursor"]=cur-1
        elif op=="DeleteNextCharacter":
            if cur<len(val): b["value"]=val[:cur]+val[cur+1:]
        elif op=="DeletePreviousWord":
            nc=_word_prev(val,cur); b["value"]=val[:nc]+val[cur:]; b["cursor"]=nc
        elif op=="DeleteNextWord":
            nc=_word_next(val,cur); b["value"]=val[:cur]+val[nc:]
        elif op=="DeleteLine": b["value"]=""; b["cursor"]=0
        elif op=="DeleteTillEnd": b["value"]=val[:cur]
    def _try_complete_path(self):
        s=self.input_buffer_value()
        if s is None: return
        completed=try_complete_path_str(s,self.pwd)
        if completed is not None:
            self.input["buffer"]={"value":completed,"cursor":len(completed)}
    # ----- Lua calls helpers for runner -----
    def messages_from_lua_result(self,result):
        # result is list of lua return values (first is expected list of messages or nil)
        if not result or result[0] is None: return []
        first=result[0]
        py=lua_to_python_generic(first)
        if py is None: return []
        if isinstance(py,dict) and not py: return []
        if not isinstance(py,list):
            # deserialize error wording observed for boolean return from LuaEval
            from messages import _py_unexpected
            raise MsgError(f"deserialize error: invalid type: {_py_unexpected(first,True) if False else _lua_type_name(first)}, expected table")
        msgs=[]
        for m in py:
            msgs.append(validate_message_py(m))
        return msgs

def _lua_type_name(v):
    from lua import lua_type as lt
    t=lt(v)
    return {"boolean":"boolean","number":"integer" if isinstance(v,int) else "float","string":"string","table":"table","function":"function","nil":"unit value"}.get(t,t)
def _word_prev(s,cur):
    i=cur
    while i>0 and s[i-1].isspace(): i-=1
    while i>0 and not s[i-1].isspace(): i-=1
    return i
def _word_next(s,cur):
    i=cur; n=len(s)
    while i<n and not s[i].isspace(): i+=1
    while i<n and s[i].isspace(): i+=1
    return i
def _remove_last_word(s):
    # Removes last word where word separators include spaces and / ? Probe: a/b/c -> a/b/ ; hi there -> hi ; hi there_ -> hi
    # Logic likely: trim trailing separators? Let's restore: if s ends with separator(s), strip them then strip word? hi there<space> gave hi<space>, not strip space then word only => It finds last separator index after trimming? Algorithm: find last occurrence of separator (space or /) in rstrip? For "hi there " rstrip -> "hi there": last space at2 => keep s[:3] "hi ".
    if s=="": return s
    core=s.rstrip(" /")
    # find last separator in core
    idx=max(core.rfind(" "),core.rfind("/"))
    if idx<0: return ""
    return core[:idx+1]

def try_complete_path_str(s,pwd):
    # Approximate xplr builtin try_complete_path (from message handling)
    if s=="": return s
    # Determine directory part and prefix as typed
    # Use posix path split preserving trailing /
    if s.endswith("/"):
        dir_part=s; prefix=""
    else:
        idx=s.rfind("/")
        if idx>=0: dir_part=s[:idx+1]; prefix=s[idx+1:]
        else: dir_part=""; prefix=s
    # Dir to list: absolute or relative to pwd
    list_dir=absolutize(dir_part if dir_part else ".",pwd) if not dir_part.startswith("/") else absolutize(dir_part)
    try:
        entries=os.listdir(list_dir)
    except OSError:
        return s
    cands=[]
    for name in entries:
        if name.startswith(prefix): cands.append(name)
    cands.sort()
    if not cands:
        # Original transforms /tmp/x with no (?) there are cands x... For no cand, likely keeps input? It transformed absolute to relative in all cases using relative_to.
        # Determine full target path given and make relative with prefix dots.
        target_abs=absolutize(s,pwd)
        return relative_to(target_abs,with_prefix_dots=True,cwd=pwd)
    if len(cands)==1:
        completed_name=cands[0]; is_dir=os.path.isdir(os.path.join(list_dir,completed_name))
