    # ---------- Snapshot for hooks ----------
    def _snapshot(self):
        focused=self.focused_node()
        return {
            "pwd":self.pwd,
            "focus":focused["absolute_path"] if focused else None,
            "mode":self.mode.get("name"),
            "layout_repr":repr(self.layout),
            "selection":tuple(n["absolute_path"] for n in self.selection),
        }
    def _hook_messages_for_changes(self,before):
        after=self._snapshot(); msgs=[]
        if before["focus"]!=after["focus"]:
            msgs.extend(copy.deepcopy(self.hooks.get("on_focus_change",[])))
        if before["pwd"]!=after["pwd"]:
            msgs.extend(copy.deepcopy(self.hooks.get("on_directory_change",[])))
        if before["mode"]!=after["mode"]:
            msgs.extend(copy.deepcopy(self.hooks.get("on_mode_switch",[])))
        if before["layout_repr"]!=after["layout_repr"]:
            msgs.extend(copy.deepcopy(self.hooks.get("on_layout_switch",[])))
        if before["selection"]!=after["selection"]:
            msgs.extend(copy.deepcopy(self.hooks.get("on_selection_change",[])))
        return msgs

    # ---------- Public process one external message ----------
    def process_message(self,msg, runner=None):
        """Process one message, executing runner effects synchronously via runner.handle_effect if provided.
        Returns list of effects if runner is None (for tests). Runner handling may enqueue additional messages (pipe/lua returns) which we process here recursively before returning.
        Hook messages for state changes are processed immediately after this message (and its effects) before return.
        """
        before=self._snapshot()
        effects=self._handle_message(msg)
        all_effects=[]
        # Execute effects in order. Quit effects should stop further hook processing? Original quit message probably no hooks after.
        quit_seen=False
        for eff in effects:
            if runner is not None:
                extra_messages=runner.handle_effect(eff,self) or []
                # handle_effect may raise SystemExit-like runner quit control via effect field handled flag.
                if eff.get("type") in ("quit","print_app_state_and_quit"):
                    quit_seen=True
                for em in extra_messages:
                    self.process_message(em,runner=runner)
                    if runner.should_quit():
                        quit_seen=True; break
            else:
                all_effects.append(eff)
                if eff.get("type") in ("quit","print_app_state_and_quit"): quit_seen=True
            if quit_seen: break
        if not quit_seen:
            hook_msgs=self._hook_messages_for_changes(before)
            for hm in hook_msgs:
                if runner is not None:
                    self.process_message(hm,runner=runner)
                    if runner.should_quit(): break
                else:
                    # In headless/no runner mode, process hooks internally and collect effects
                    all_effects.extend(self.process_message(hm,runner=None))
        return all_effects

