            if text[i]=="\x1b":
                # CSI
                if i+1<len(text) and text[i+1]=="[":
                    j=i+2
                    while j<len(text) and not text[j].isalpha(): j+=1
                    if j<len(text):
                        params=text[i+2:j]; final=text[j]
                        if final=="m": cur_style=apply_sgr(cur_style,params,style)
                        i=j+1; continue
                elif i+1<len(text) and text[i+1]=="]":
                    # OSC skip to BEL or ST
                    j=text.find("\x07",i); k=text.find("\x1b\\",i)
                    cand=[p for p in [j,k] if p>=0]
                    i=(min(cand)+ (1 if min(cand)==j else 2)) if cand else len(text); continue
                i+=1; continue
            ch=text[i]
            if ch=="\n": break
            if ch=="\t": ch=" "
            cw=char_width(ch)
            if cw==0:
                # combining append to previous cell string
                if cx>x: 
                    prev=self.cells[y][cx-1]
                    prev.ch+=ch
                i+=1; continue
            if cx+cw>max_x: break
            self.set(cx,y,ch,cur_style); cx+=cw; i+=1
        return cx
    def write_wrapped(self,rect,text,style):
        x,y,w,h=rect
        lines=wrap_text(text,w)
        for i,line in enumerate(lines[:h]):
            self.write(x,y+i,line,style,w)

def apply_sgr(current,params,base):
    out=copy.deepcopy(current)
    if params.strip()=="":
        return copy.deepcopy(base)
    parts=[]
    for p in params.split(";"):
        try: parts.append(int(p) if p!="" else 0)
        except: parts.append(0)
    i=0
    fg_names={30:"Black",31:"Red",32:"Green",33:"Yellow",34:"Blue",35:"Magenta",36:"Cyan",37:"Gray",90:"DarkGray",91:"LightRed",92:"LightGreen",93:"LightYellow",94:"LightBlue",95:"LightMagenta",96:"LightCyan",97:"White"}
    bg_names={40:"Black",41:"Red",42:"Green",43:"Yellow",44:"Blue",45:"Magenta",46:"Cyan",47:"Gray",100:"DarkGray",101:"LightRed",102:"LightGreen",103:"LightYellow",104:"LightBlue",105:"LightMagenta",106:"LightCyan",107:"White"}
    mods_by_code={1:"Bold",2:"Dim",3:"Italic",4:"Underlined",5:"SlowBlink",6:"RapidBlink",7:"Reversed",8:"Hidden",9:"CrossedOut"}
    while i<len(parts):
        n=parts[i]
        if n==0: out=copy.deepcopy(base)
        elif n in fg_names: out["fg"]=fg_names[n]
        elif n in bg_names: out["bg"]=bg_names[n]
        elif n==39: out["fg"]="Reset"
        elif n==49: out["bg"]="Reset"
        elif n in (38,48):
            target="fg" if n==38 else "bg"
            if i+1<len(parts) and parts[i+1]==5 and i+2<len(parts): out[target]={"Indexed":parts[i+2]}; i+=2
            elif i+1<len(parts) and parts[i+1]==2 and i+4<len(parts): out[target]={"Rgb":[parts[i+2],parts[i+3],parts[i+4]]}; i+=4
        elif n in mods_by_code:
            mods=list(out.get("add_modifiers") or [])
            if mods_by_code[n] not in mods: mods.append(mods_by_code[n])
            out["add_modifiers"]=mods
        elif n in (22,23,24,25,27,28,29):
            remove={22:["Bold","Dim"],23:["Italic"],24:["Underlined"],25:["SlowBlink","RapidBlink"],27:["Reversed"],28:["Hidden"],29:["CrossedOut"]}[n]
            out["add_modifiers"]=[m for m in (out.get("add_modifiers") or []) if m not in remove] or None
        i+=1
    return out

def wrap_text(text,width):
    if width<=0: return []
    out=[]
    for para in text.split("\n"):
        # ratatui wrap trim true approximate with word wrap in display widths, preserving leading spaces? It trims leading whitespace on wrapped lines.
        words=re.findall(r'\s+|\S+',para)
        line=""
        for word in words:
            if str_width(line+word)<=width:
                line+=word
            else:
                if line.strip()!="": out.append(line.rstrip())
                # long word break
                while str_width(word)>width:
                    part=trunc_str(word,width); out.append(part); word=word[len(part):]
                line=word.lstrip() if line else word
        out.append(line.rstrip())
    return out

class Rect:
    pass

def solve_constraints(total, constraints, count, spacing=0, screen_w=0,screen_h=0,layout_w=0,layout_h=0,vertical=False):
    if count<=0: return []
    if not constraints:
        constraints=[{"Percentage":100//count} for _ in range(count)]
    cons=list(constraints)
    while len(cons)<count: cons.append({"Percentage":0})
    cons=cons[:count]
    available=max(total-spacing*(count-1),0)
    desired=[]; mins=[]; maxs=[]; flexible=[]
    for c in cons:
        if isinstance(c,dict) and len(c)==1:
            k=next(iter(c)); v=c[k]
        elif isinstance(c,str): k=c; v=0
        else: k="Percentage"; v=0
        # transform LessThan
        base_kind=k; limit=None
        suffix_map=[("LessThanScreenHeight",screen_h),("LessThanScreenWidth",screen_w),("LessThanLayoutHeight",layout_h),("LessThanLayoutWidth",layout_w)]
        for suf,lim in suffix_map:
            if k.endswith(suf):
                base_kind=k[:-len(suf)]; limit=lim; break
        if limit is not None and isinstance(v,int): v=min(v,limit)
        mn=0; mx=10**9; flex=True; des=0
        if base_kind=="Percentage": des=available*int(v)/100 if isinstance(v,(int,float)) else 0
        elif base_kind=="Ratio":
            if isinstance(v,(list,tuple)) and len(v)==2 and v[1]: des=available*v[0]/v[1]
        elif base_kind=="Length": des=int(v); mn=mx=int(v); flex=False
        elif base_kind=="Min": des=int(v); mn=int(v)
        elif base_kind=="Max": des=int(v); mx=int(v)
        else: des=0
        desired.append(float(des)); mins.append(mn); maxs.append(mx); flexible.append(flex)
    # scale flexible desired to fit available after fixed
    fixed_sum=sum(desired[i] for i in range(count) if not flexible[i])
    flex_sum=sum(desired[i] for i in range(count) if flexible[i])
    remaining=available-fixed_sum
    if flex_sum>0 and remaining>=0:
        scale=remaining/flex_sum
        # Only scale if flexible are percentages/ratios/mins needing fill: Ratatui solver would expand mins too.
        for i in range(count):
            if flexible[i]: desired[i]*=scale
    widths=[]
    for i in range(count):
        w=int(desired[i])  # floor
        w=max(mins[i],min(w,maxs[i])); widths.append(w)
    # distribute remaining one by one: prefer columns with largest fractional desired, tie order; skip maxed.
    def frac(i): return desired[i]-math.floor(desired[i])
    order=sorted(range(count),key=lambda i:(-frac(i),i))
    total_w=sum(widths)
    idx=0
    while total_w<available:
        progressed=False
        for i in order:
            if total_w>=available: break
            if widths[i]<maxs[i] and flexible[i]:
                widths[i]+=1; total_w+=1; progressed=True
        if not progressed: break
    while total_w>available:
        progressed=False
        for i in reversed(range(count)):
            if total_w<=available: break
            if widths[i]>mins[i]:
                widths[i]-=1; total_w-=1; progressed=True
        if not progressed: break
    return widths

def split_rect(rect,direction,config,count,screen_size):
    x,y,w,h=rect
    cfg=config or {}
    margin=cfg.get("margin")
    hm=cfg.get("horizontal_margin") if cfg.get("horizontal_margin") is not None else margin
    vm=cfg.get("vertical_margin") if cfg.get("vertical_margin") is not None else margin
    hm=int(hm) if isinstance(hm,(int,float)) else 0; vm=int(vm) if isinstance(vm,(int,float)) else 0
    x+=hm; y+=vm; w=max(w-2*hm,0); h=max(h-2*vm,0)
    cons=cfg.get("constraints")
    if direction=="Horizontal":
        widths=solve_constraints(w,cons,count,0,screen_size[0],screen_size[1],w,h,False)
        rects=[]; cx=x
        for wd in widths: rects.append((cx,y,wd,h)); cx+=wd
        # any leftover due constraints where max etc: last rect may leave blank at right (ratatui does)
        return rects
    else:
        heights=solve_constraints(h,cons,count,0,screen_size[0],screen_size[1],w,h,True)
        rects=[]; cy=y
        for ht in heights: rects.append((x,cy,w,ht)); cy+=ht
        return rects

BORDER_CHARS={
    "Plain":("┌","┐","└","┘","─","│"),
    "Rounded":("╭","╮","╰","╯","─","│"),
    "Double":("╔","╗","╚","╝","═","║"),
    "Thick":("┏","┓","┗","┛","━","┃"),
}

def resolve_panel_ui(app,specific=None,custom_ui=None):
    general=app.config["general"]; panel_ui=general.get("panel_ui") or {}
    default=panel_ui.get("default") or {}
    spec={}
    if specific: spec=panel_ui.get(specific) or {}
    if custom_ui is not None: spec=custom_ui or {}
    # title
    def title_obj(src): return src.get("title") or {}
    # Format: custom/specific format if not None else default format
    fmt=None
    for src in (spec,default):
        if (src.get("title") or {}).get("format") is not None: fmt=src["title"]["format"]; break
    title_style=mix_styles([(default.get("title") or {}).get("style"),(spec.get("title") or {}).get("style")])
    style=mix_styles([default.get("style"),spec.get("style")])
    borders=spec.get("borders")
    if borders is None: borders=default.get("borders")
    border_type=spec.get("border_type") or default.get("border_type") or "Rounded"
    border_style=mix_styles([default.get("border_style"),spec.get("border_style")])
    return {"title_format":fmt,"title_style":title_style,"style":style,"borders":borders or [],"border_type":border_type,"border_style":border_style}

def draw_block(grid,rect,panel,title_text):
    x,y,w,h=rect
    if w<=0 or h<=0: return rect
    grid.fill_rect(rect,panel["style"])
    borders=set(panel.get("borders") or [])
    chars=BORDER_CHARS.get(panel.get("border_type") or "Rounded",BORDER_CHARS["Rounded"])
    tl,tr,bl,br,hch,vch=chars
    bs=panel["border_style"]
    if "Top" in borders:
        for xx in range(x,x+w): grid.set(xx,y,hch,bs)
    if "Bottom" in borders and h>1:
        for xx in range(x,x+w): grid.set(xx,y+h-1,hch,bs)
    if "Left" in borders:
        for yy in range(y,y+h): grid.set(x,yy,vch,bs)
    if "Right" in borders and w>1:
        for yy in range(y,y+h): grid.set(x+w-1,yy,vch,bs)
    if "Top" in borders and "Left" in borders: grid.set(x,y,tl,bs)
    if "Top" in borders and "Right" in borders and w>1: grid.set(x+w-1,y,tr,bs)
    if "Bottom" in borders and "Left" in borders and h>1: grid.set(x,y+h-1,bl,bs)
    if "Bottom" in borders and "Right" in borders and w>1 and h>1: grid.set(x+w-1,y+h-1,br,bs)
    # title on top border if present else on first row? Ratatui draws title at top regardless border? We'll draw if title_text
    if title_text:
        tx=x+1 if "Left" in borders else x
        maxw=max(w-(tx-x)- (1 if "Right" in borders else 0),0)
        grid.write(tx,y,title_text,panel["title_style"],maxw)
    inner=(x+(1 if "Left" in borders else 0), y+(1 if "Top" in borders else 0), max(w-(1 if "Left" in borders else 0)-(1 if "Right" in borders else 0),0), max(h-(1 if "Top" in borders else 0)-(1 if "Bottom" in borders else 0),0))
    return inner

def generate_help_rows(app,mode):
    # returns list of (key,remaps,action) or lines if custom help (handled outside)
    kb=mode.get("key_bindings") or {}
    on_key=kb.get("on_key") or {}
    groups=[]  # list dict {keys:[], help, messages}
    for key in sorted(on_key.keys()):
        action=on_key[key]
        if not isinstance(action,dict): continue
        help_text=action.get("help")
        if help_text is None: continue
        found=None
        if not app.config["general"].get("hide_remaps_in_help_menu"):
            for g in groups:
                if g["help"]==help_text and g["messages"]==(action.get("messages") or []):
                    found=g; break
        if found: found["keys"].append(key)
        else: groups.append({"keys":[key],"help":help_text,"messages":action.get("messages") or []})
    rows=[]
    for g in groups:
        rows.append((g["keys"][0]," ".join(g["keys"][1:]),g["help"]))
    # on_* categories after on_key
    labels={"on_alphabet":"[a-z]","on_number":"[0-9]","on_alphanumeric":"[a-z0-9]","on_special_character":"[special]","on_character":"[character]","on_navigation":"[navigation]","on_function":"[function]","default":"[default]"}
    # Labels for old modes in default docs: number mode on_number represented [0-9]; action on_number grouped.
    for field,label in labels.items():
        action=kb.get(field)
        if isinstance(action,dict) and action.get("help") is not None:
            # Hide a duplicate if this action exactly same as a groups? Default action mode on_number help go to index is separate.
            rows.append((label,"",action["help"]))
    return rows

def global_help_lines(app):
    lines=[]
    def append_section(heading,mode):
        lines.append(f"### {heading}")
        lines.append("")
        if mode.get("help") is not None:
            lines.extend(str(mode["help"]).split("\n"))
        else:
            lines.append(" key             | remaps                    | action\n --------------- | ------------------------- | ------")
            for k,remaps,act in generate_help_rows(app,mode):
                lines.append(f" {k:<15} | {remaps:<25} | {act}")
        if mode.get("extra_help"):
            lines.extend(str(mode["extra_help"]).split("\n"))
        lines.append(""); lines.append("")
    # current mode first by display name, sanitized mode
    append_section(app.mode.get("name"),app.mode)
    modes=app.config.get("modes",{})
    for sec in ("builtin","custom"):
        for key,mode in (modes.get(sec) or {}).items():
            append_section(key,mode)
    return lines

class Renderer:
    def __init__(self,app):
        self.app=app; self.table_scrolltop=0; self.last_table_parent=None; self.grid=None
    def render(self,width,height):
        grid=Grid(width,height); self.grid=grid
        # background default style?
        layout=self.app.mode.get("layout") if self.app.mode.get("layout") is not None else self.app.layout
        self._render_layout(layout,(0,0,width,height),(width,height))
        return grid
    def _render_layout(self,layout,rect,screen):
        app=self.app; grid=self.grid
        if layout is None: return
        if isinstance(layout,str):
            if layout=="Nothing":
                panel=resolve_panel_ui(app,None); draw_block(grid,rect,panel,panel["title_format"] or "")
            elif layout=="Table": self._render_table(rect)
            elif layout=="InputAndLogs": self._render_input_logs(rect)
            elif layout=="Selection": self._render_selection(rect)
            elif layout=="HelpMenu": self._render_help(rect)
            elif layout=="SortAndFilter": self._render_sort_filter(rect)
            return
        if isinstance(layout,dict) and len(layout)==1:
            k=next(iter(layout)); v=layout[k]
            if k in ("Horizontal","Vertical"):
                splits=v.get("splits") or []
                rects=split_rect(rect,k,v.get("config"),len(splits),screen)
                for child,r in zip(splits,rects): self._render_layout(child,r,screen)
            elif k=="Static":
                self._render_custom_panel(v,rect,screen)
            elif k=="Dynamic":
                panel_data=self._call_dynamic(v,rect,screen)
                if panel_data is not None: self._render_custom_panel(panel_data,rect,screen)
            elif k=="CustomContent":
                self._render_custom_panel(v,rect,screen)
    def _call_dynamic(self,fn_name,rect,screen):
        app=self.app
        fn=app.host.get_lua_function(fn_name)
        if fn is None: return None
        ctx={
            "layout_size":{"x":rect[0],"y":rect[1],"width":rect[2],"height":rect[3]},
            "screen_size":{"x":0,"y":0,"width":screen[0],"height":screen[1]},
            "scrolltop":self.table_scrolltop,
            "app":app.lua_context(lightweight=True),
        }
        res=app.host.state.call_value(fn,[python_to_lua(ctx)])
        if not res: return None
        py=lua_to_python_generic(res[0])
        try: return normalize_custom_panel(py)
        except Exception:
            return py
    def _render_custom_panel(self,panel_data,rect,screen):
        grid=self.grid; app=self.app
        if not isinstance(panel_data,dict) or len(panel_data)!=1: return
        k=next(iter(panel_data)); v=panel_data[k]
        if k=="CustomLayout":
            self._render_layout(v,rect,screen); return
        if not isinstance(v,dict): return
        ui=v.get("ui") if isinstance(v,dict) else None
        panel=resolve_panel_ui(app,None,custom_ui=ui)
        title=panel["title_format"] or ""
        inner=draw_block(grid,rect,panel,title)
        style=panel["style"]
        if k=="CustomParagraph":
            grid.write_wrapped(inner,str(v.get("body") or ""),style)
        elif k=="CustomList":
            x,y,w,h=inner
            for i,line in enumerate(v.get("body") or []):
                if i>=h: break
                grid.write(x,y+i,str(line),style,w)
        elif k=="CustomTable":
            rows=v.get("body") or []; widths_spec=v.get("widths") or []
            cols=max((len(r) for r in rows),default=0)
            spacing=v.get("col_spacing"); spacing=1 if spacing is None else int(spacing)
            widths=solve_constraints(inner[2],widths_spec,cols,spacing,screen[0],screen[1],inner[2],inner[3])
            x,y,w,h=inner
            for ri,row in enumerate(rows[:h]):
                cx=x
                for ci,cell in enumerate(row):
                    if ci>=len(widths): break
                    grid.write(cx,y+ri,str(cell),style,widths[ci]); cx+=widths[ci]+spacing
    def _render_sort_filter(self,rect):
        app=self.app; grid=self.grid
        panel=resolve_panel_ui(app,"sort_and_filter")
        items=[]
        sfui=app.config["general"].get("sort_and_filter_ui") or {}
        count=0
        parts=[]  # (text,style)
        sep=sfui.get("separator") or {}
        def add_part(text,style):
            nonlocal count; count+=1; parts.append((text,style))
        for f in app.explorer_config.get("filters",[]):
            ident=(sfui.get("filter_identifiers") or {}).get(f.get("filter")) or sfui.get("default_identifier") or {}
            txt=(ident.get("format") or "")+str(f.get("input",""))
            add_part(txt,mix_styles([panel["style"],ident.get("style")]))
        sch=app.explorer_config.get("searcher")
        if sch:
            ident=(sfui.get("search_identifiers") or {}).get(sch.get("algorithm")) or sfui.get("default_identifier") or {}
            dir_idents=sfui.get("search_direction_identifiers") or {}
            dobj=dir_idents.get("unordered" if sch.get("unordered") else "ordered") or {}
            txt=(ident.get("format") or "")+str(sch.get("pattern",""))+(dobj.get("format") or "")
            add_part(txt,mix_styles([panel["style"],ident.get("style"),dobj.get("style")]))
        for s in app.explorer_config.get("sorters",[]):
            ident=(sfui.get("sorter_identifiers") or {}).get(s.get("sorter")) or sfui.get("default_identifier") or {}
            dir_idents=sfui.get("sort_direction_identifiers") or {}
            dkey="reverse" if s.get("reverse") else "forward"; dobj=dir_idents.get(dkey) or {}
            txt=(ident.get("format") or "")+(dobj.get("format") or "")
            add_part(txt,mix_styles([panel["style"],ident.get("style"),dobj.get("style")]))
        title=panel["title_format"]
        if title is None:
            title=f" Sort & filter ({count}) " if count else " Sort & filter "
            # original shows a leading space before title in border? Capture '╭ Sort...' - title begins immediately after corner with space included in string.
            title=title[1:] if False else title
        inner=draw_block(grid,rect,panel,title)
        x,y,w,h=inner
        cx=x
        sep_text=sep.get("format") or ""; sep_style=mix_styles([panel["style"],sep.get("style")])
        for idx,(txt,style) in enumerate(parts):
            if idx>0:
                cx=grid.write(cx,y,sep_text,sep_style,x+w-cx)
            cx=grid.write(cx,y,txt,style,x+w-cx)
    def _render_selection(self,rect):
        app=self.app; grid=self.grid; panel=resolve_panel_ui(app,"selection")
        n=len(app.selection)
        title=panel["title_format"] if panel["title_format"] is not None else (f" Selection ({n}) " if n else " Selection ")
        inner=draw_block(grid,rect,panel,title)
        x,y,w,h=inner
        fmt_name=(app.config["general"].get("selection") or {}).get("item",{}).get("format") if isinstance((app.config["general"].get("selection") or {}).get("item"),dict) else None
        # general.selection.item may be {format,style}
        item_cfg=(app.config["general"].get("selection") or {}).get("item") or {}
        item_style=mix_styles([panel["style"],item_cfg.get("style") if isinstance(item_cfg,dict) else None])
        for i,node in enumerate(app.selection[:h]):
            text=self._format_with_lua(fmt_name,node,node.get("absolute_path",""))
            grid.write(x,y+i,text,item_style,w)
    def _format_with_lua(self,fmt_name,arg,fallback):
        if not fmt_name: return fallback
        fn=self.app.host.get_lua_function(fmt_name)
        if fn is None: return fmt_name
        res=self.app.host.state.call_value(fn,[python_to_lua(copy.deepcopy(arg))])
        if res and isinstance(res[0],str): return res[0]
        if res and res[0] is not None: return lua_tostring(res[0],self.app.host.state) if False else str(res[0])
        return ""
    def _render_help(self,rect):
        app=self.app; grid=self.grid; panel=resolve_panel_ui(app,"help_menu")
        title=panel["title_format"] if panel["title_format"] is not None else f" Help [{app.mode.get('name','')}] "
        inner=draw_block(grid,rect,panel,title)
        x,y,w,h=inner
        mode=app.mode
        if mode.get("help") is not None:
            text=str(mode["help"])
            if mode.get("extra_help"): text=text+"\n"+str(mode["extra_help"])
            grid.write_wrapped(inner,text,panel["style"]); return
        rows=generate_help_rows(app,mode)
        if mode.get("extra_help"):
            # appended as extra lines after table in panel if fits - handled after rows as text lines
            pass
        widths=solve_constraints(w,[{"Percentage":20},{"Percentage":20},{"Percentage":60}],3,spacing=1)
        for i,(k,remap,act) in enumerate(rows[:h]):
            cx=x
            for ci,cell in enumerate((k,remap,act)):
                grid.write(cx,y+i,cell,panel["style"],widths[ci]); cx+=widths[ci]+1
        if mode.get("extra_help") and len(rows)<h:
            lines=str(mode["extra_help"]).split("\n")
            for j,line in enumerate(lines[:h-len(rows)]): grid.write(x,y+len(rows)+j,line,panel["style"],w)
    def _render_input_logs(self,rect):
        app=self.app; grid=self.grid; panel=resolve_panel_ui(app,"input_and_logs")
        nsel=len(app.selection); sel_suffix=f" {{{nsel} sel}}" if nsel else ""
        buf=app.input.get("buffer")
        if panel["title_format"] is not None: title=panel["title_format"]
        elif buf is not None: title=f" Input [{app.mode.get('name','')}] "
        else:
            if app.logs: title=f" Logs ({len(app.logs)}) [{app.mode.get('name','')}]" + sel_suffix + " "
            else: title=f" Logs [{app.mode.get('name','')}]" + sel_suffix + " "
