def _calc_scrolltop(current,focus,total,visible,general):
    if visible<=0 or total<=0: return 0
    max_top=max(total-visible,0)
    if general.get("paginated_scrolling"):
        return min((focus//visible)*visible,max_top)
    pad=general.get("scroll_padding")
    pad=int(pad) if isinstance(pad,(int,float)) else 0
    top=current
    # clamp existing
    top=max(0,min(top,max_top))
    if focus < top+pad:
        top=focus-(pad-1) if pad>0 else focus
    elif focus > top+visible-pad:
        top=focus-(visible-pad)
    # If focus outside visible entirely after above (jumps), formulas cover due thresholds trigger.
    return max(0,min(top,max_top))

def _substring_by_width(s,start_width,width):
    out=[]; pos=0
    for ch in s:
        cw=char_width(ch)
        if pos+cw<=start_width: pos+=cw; continue
        if pos>=start_width+width: break
        out.append(ch); pos+=cw
    return "".join(out)

