def char_width(ch):
    if unicodedata.combining(ch): return 0
    if unicodedata.east_asian_width(ch) in ("W","F"): return 2
    if ord(ch)<32: return 0
    return 1
def str_width(s): return sum(char_width(c) for c in s)
