def style_key(style):
    if not isinstance(style,dict): return (None,None,(),())
    def color_key(c):
        if isinstance(c,dict):
            if "Rgb" in c: return ("Rgb",tuple(c["Rgb"]))
            if "Indexed" in c: return ("Indexed",c["Indexed"])
        return c
