def patch_style(base,patch):
    if not isinstance(patch,dict): return copy.deepcopy(base)
    out=copy.deepcopy(base) if isinstance(base,dict) else empty_style()
    if patch.get("fg") is not None: out["fg"]=copy.deepcopy(patch["fg"])
    if patch.get("bg") is not None: out["bg"]=copy.deepcopy(patch["bg"])
    mods=list(out.get("add_modifiers") or [])
    for m in patch.get("add_modifiers") or []:
        if m not in mods: mods.append(m)
    for m in patch.get("sub_modifiers") or []:
        if m in mods: mods.remove(m)
    out["add_modifiers"]=mods if mods else None
    out["sub_modifiers"]=None
    return out

