    top=max(0,min(top,max_top))
    if focus < top+pad:
        top=focus-(pad-1) if pad>0 else focus
    elif focus > top+visible-pad:
        top=focus-(visible-pad)
    # If focus outside visible entirely after above (jumps), formulas cover due thresholds trigger.
    return max(0,min(top,max_top))

