def find_key_action(mode,key):
    kb=mode.get("key_bindings") or {}
    on_key=kb.get("on_key") or {}
    name=key.get("name")
    if name in on_key and on_key[name] is not None:
        return on_key[name]
    # alternate representations: tab <-> ctrl-i, enter <-> ctrl-m, backspace <-> ctrl-h, space etc
    alt_names=[]
    if name=="tab": alt_names=["ctrl-i"]
    elif name=="enter": alt_names=["ctrl-m"]
    elif name=="backspace": alt_names=["ctrl-h"]
    for an in alt_names:
        if an in on_key and on_key[an] is not None: return on_key[an]
    ch=key.get("char"); ctrl=key.get("ctrl"); alt=key.get("alt")
    is_char=(ch is not None and len(ch)==1 and not ctrl and not alt) or name=="space"
    if is_char:
        c=ch if ch is not None else " "
        if c.isalpha() and kb.get("on_alphabet") is not None: return kb["on_alphabet"]
        if c.isdigit() and kb.get("on_number") is not None: return kb["on_number"]
        if c.isalnum() and kb.get("on_alphanumeric") is not None: return kb["on_alphanumeric"]
        if (not c.isalnum()) and kb.get("on_special_character") is not None: return kb["on_special_character"]
        if kb.get("on_character") is not None: return kb["on_character"]
    if name in ("left","right","up","down","home","end","page-up","page-down","back-tab","delete","insert") or (name and name.startswith("ctrl-") and name.split("-",1)[1] in ("left","right","up","down","home","end")):
        if kb.get("on_navigation") is not None: return kb["on_navigation"]
    if name and re.match(r'f\d+$',name):
        if kb.get("on_function") is not None: return kb["on_function"]
    if kb.get("default") is not None: return kb["default"]
    return None

def parse_input(data):
    events=[]; i=0; n=len(data)
    while i<n:
        b=data[i]
        # ESC sequences
        if b==0x1b:
            if i+1>=n:
                events.append(key_event("esc")); i+=1; break
            nxt=data[i+1]
            if nxt==ord('['):
                # CSI parse until final byte @-~
                j=i+2
                while j<n and not (0x40<=data[j]<=0x7e): j+=1
                if j>=n: break  # incomplete, leave in buf
                final=chr(data[j]); params=data[i+2:j].decode('ascii','ignore')
                ev=parse_csi(final,params)
                if ev: events.append(ev)
                i=j+1; continue
            if nxt==ord('O'):
                if i+2>=n: break
                final=chr(data[i+2]); ev=parse_ss3(final)
                if ev: events.append(ev)
                i+=3; continue
            # Alt + next char (decode utf8)
            ch,consumed=decode_char(data,i+1)
            if ch is None: break
            events.append(key_event(alt_key_name(ch),char=ch,alt=True)); i+=1+consumed; continue
        if b in (13,10): events.append(key_event("enter")); i+=1; continue
        if b==9: events.append(key_event("tab",char="\t")); i+=1; continue
        if b in (8,127): events.append(key_event("backspace")); i+=1; continue
        if 1<=b<=26:
            ch=chr(ord('a')+b-1); events.append(key_event(f"ctrl-{ch}",char=ch,ctrl=True)); i+=1; continue
        if b==0: events.append(key_event("ctrl-space",char="\0",ctrl=True)); i+=1; continue
        ch,consumed=decode_char(data,i)
        if ch is None: break
        if ch==" ": events.append(key_event("space",char=" "))
        else: events.append(key_event(ch,char=ch))
        i+=consumed
    return events,data[i:]

def decode_char(data,i):
    # utf8 decode one char
    for l in range(1,5):
        try:
            s=data[i:i+l].decode('utf-8')
            if len(s)==1: return s,l
        except Exception: continue
    return None,0

def key_event(name,char=None,ctrl=False,alt=False):
    return {"type":"key","name":name,"char":char,"ctrl":ctrl,"alt":alt}
def alt_key_name(ch):
    if ch==" ": return "alt-space"
