def parse_ss3(final):
    mp={'P':'f1','Q':'f2','R':'f3','S':'f4','A':'up','B':'down','C':'right','D':'left','H':'home','F':'end'}
    return key_event(mp[final]) if final in mp else None
def parse_csi(final,params):
    # SGR mouse CSI < b ; x ; y M/m
    if params.startswith("<") and final in "Mm":
        try:
            b,x,y=[int(p) for p in params[1:].split(";")]
            return {"type":"mouse","button":b,"x":x,"y":y,"press":final=="M"}
        except Exception: return None
    parts=params.split(";") if params else []
    def pi(idx,default=1):
        try: return int(parts[idx]) if idx<len(parts) and parts[idx] else default
        except: return default
    code=pi(0,1); mod=pi(1,1)
    ctrl=mod in (5,6,7,8); alt=mod in (3,4,7,8); shift=mod in (2,4,6,8)
    def name_for(base):
        if ctrl: return f"ctrl-{base}"
        if alt: return f"alt-{base}"
        return base
    if final in "ABCD":
        base={'A':'up','B':'down','C':'right','D':'left'}[final]; return key_event(name_for(base),ctrl=ctrl,alt=alt)
    if final=='H': return key_event(name_for('home'),ctrl=ctrl,alt=alt)
    if final=='F': return key_event(name_for('end'),ctrl=ctrl,alt=alt)
    if final=='Z': return key_event("back-tab")
    if final=='~':
