        app=self.app
        try:
            with open(app.pipe["msg_in"],"rb") as f: data=f.read()
        except OSError as e:
            raise AppFatal(os_error_str(e))
        finally:
            # delete pipe dir after reading attempt? If read fails original session remains with pipe? It terminated fatal and session left - deletion of pipe probably not. Only delete on success below.
            pass
        parts=data.split(delim.encode())
        msgs=[]; errors=[]
