            tty=self.tty
            st.stdout_write=lambda s: (tty.write(s.encode('utf-8','surrogateescape')),tty.flush())
            st.stderr_write=lambda s: (tty.write(s.encode('utf-8','surrogateescape')),tty.flush())
            st.stdin_read_line=self._tty_readline
