            app.add_log("ERROR",str(e)); ret_msgs=[]
        except Exception as e:
            app.add_log("ERROR",str(e)); ret_msgs=[]
        return pipe_msgs+ret_msgs
    # FIFO
    def _fifo_effect(self,eff):
        action=eff.get("action"); path=eff.get("path")
        if action=="stop": self._fifo_stop(); return
