                self._fifo_stop(); return
            # If a different fifo active, toggle maybe stops regardless path? Original ToggleFifo starts if stopped else stops. If active with different path, likely stop (not switch). Approximate: stop.
            if self.fifo_file is not None:
                self._fifo_stop(); return
