            verb="toggle" if action=="toggle" else "start"
            # Original path in message for relative? Use as given? Probe used absolute.
            shown=abs_path if os.path.isabs(path) else path
            self.app.add_log("ERROR",f'could not {verb} fifo "{shown}": {os_error_str(e)}')
    def _fifo_stop(self):
