    # Async explore completion
    def process_async(self):
        app=self.app
        pending=app._pending_async[:]; app._pending_async.clear()
        for eff in pending:
            if eff.get("parents"):
                # Explore current and parents: update last_focus for parents and current buffer
                paths=[]
                p=app.pwd
                while True:
                    paths.append(p)
                    if p=="/": break
                    p=os.path.dirname(p) or "/"
                for parent in paths:
                    try: nodes=__import__("node").explore_dir(parent,app.explorer_config)
                    except Exception: continue
                    if parent==app.pwd:
                        app._set_directory_buffer(parent,nodes)
                    else:
                        if parent not in app.last_focus:
                            app.last_focus[parent]=nodes[0]["relative_path"] if nodes else None
            else:
                app._explore_pwd()
            self.draw()
    # Input event parsing
    def run_loop(self):
        app=self.app
        # start fifo from config
        if app.config["general"].get("start_fifo"):
            self._fifo_effect({"action":"start","path":app.config["general"]["start_fifo"]})
        initial=[]
        initial.extend(copy.deepcopy(app.hooks.get("on_load",[])))
        # initial focus hook approximated after on_load
        if app.hooks.get("on_focus_change"):
            initial.extend(copy.deepcopy(app.hooks["on_focus_change"]))
        initial.extend(copy.deepcopy(self.cli.on_load))
        for msg in initial:
            if self.quit: break
            app.process_message(msg,runner=self)
        if not self.quit:
            self.process_async(); self.draw()
        buf=b""
        while not self.quit:
            if self._resize_pending:
                self._resize_pending=False; self.need_full_redraw=True; self.draw()
            try:
                r,_,_=select.select([self.tty],[],[],0.05)
            except Exception:
                break
            if not r:
                if app._pending_async: self.process_async()
                continue
            try: data=os.read(self.tty.fileno(),4096)
            except OSError: break
            if not data: break
            buf+=data
            events,buf=parse_input(buf)
            for ev in events:
                self.handle_event(ev)
                if self.quit: break
            if app._pending_async: self.process_async()
    def handle_event(self,ev):
        app=self.app
        if ev.get("type")=="resize":
            self.need_full_redraw=True; self.draw(); return
        if ev.get("type")=="mouse":
            if not self.mouse_enabled: return
            btn=ev.get("button")
            if btn==64: # scroll up in SGR
                app.process_message("FocusPrevious",runner=self)
            elif btn==65:
                app.process_message("FocusNext",runner=self)
            return
        if ev.get("type")!="key": return
        key=ev
        app._last_key=key
        action=find_key_action(app.mode,key)
        if action is None:
            if app.config["general"].get("enable_recover_mode") and app.mode.get("name")!="recover":
                raw=None
                from core import get_mode_from_config
                raw=get_mode_from_config(app.config,"recover","builtin")
                if raw is not None:
                    app.process_message({"SwitchModeBuiltin":"recover"},runner=self)
            return
        for msg in action.get("messages") or []:
            app.process_message(copy.deepcopy(msg),runner=self)
            if self.quit: break
        app._last_key=None

def style_sgr(style):
    codes=style_ansi_codes(style)
    if not codes: return b"\x1b[0m"
    return ("\x1b[0;"+";".join(codes)+"m").encode()

def find_key_action(mode,key):
    kb=mode.get("key_bindings") or {}
    on_key=kb.get("on_key") or {}
    name=key.get("name")
    if name in on_key and on_key[name] is not None:
        return on_key[name]
    # alternate representations: tab <-> ctrl-i, enter <-> ctrl-m, backspace <-> ctrl-h, space etc
    alt_names=[]
    if name=="tab": alt_names=["ctrl-i"]
    elif name=="enter": alt_names=["ctrl-m"]
    elif name=="backspace": alt_names=["ctrl-h"]
    for an in alt_names:
        if an in on_key and on_key[an] is not None: return on_key[an]
    ch=key.get("char"); ctrl=key.get("ctrl"); alt=key.get("alt")
    is_char=(ch is not None and len(ch)==1 and not ctrl and not alt) or name=="space"
    if is_char:
        c=ch if ch is not None else " "
        if c.isalpha() and kb.get("on_alphabet") is not None: return kb["on_alphabet"]
        if c.isdigit() and kb.get("on_number") is not None: return kb["on_number"]
        if c.isalnum() and kb.get("on_alphanumeric") is not None: return kb["on_alphanumeric"]
        if (not c.isalnum()) and kb.get("on_special_character") is not None: return kb["on_special_character"]
        if kb.get("on_character") is not None: return kb["on_character"]
    if name in ("left","right","up","down","home","end","page-up","page-down","back-tab","delete","insert") or (name and name.startswith("ctrl-") and name.split("-",1)[1] in ("left","right","up","down","home","end")):
        if kb.get("on_navigation") is not None: return kb["on_navigation"]
    if name and re.match(r'f\d+$',name):
        if kb.get("on_function") is not None: return kb["on_function"]
    if kb.get("default") is not None: return kb["default"]
    return None

def parse_input(data):
    events=[]; i=0; n=len(data)
    while i<n:
        b=data[i]
        # ESC sequences
        if b==0x1b:
            if i+1>=n:
                events.append(key_event("esc")); i+=1; break
            nxt=data[i+1]
            if nxt==ord('['):
                # CSI parse until final byte @-~
                j=i+2
                while j<n and not (0x40<=data[j]<=0x7e): j+=1
                if j>=n: break  # incomplete, leave in buf
                final=chr(data[j]); params=data[i+2:j].decode('ascii','ignore')
                ev=parse_csi(final,params)
                if ev: events.append(ev)
                i=j+1; continue
            if nxt==ord('O'):
                if i+2>=n: break
                final=chr(data[i+2]); ev=parse_ss3(final)
                if ev: events.append(ev)
                i+=3; continue
            # Alt + next char (decode utf8)
            ch,consumed=decode_char(data,i+1)
            if ch is None: break
            events.append(key_event(alt_key_name(ch),char=ch,alt=True)); i+=1+consumed; continue
        if b in (13,10): events.append(key_event("enter")); i+=1; continue
        if b==9: events.append(key_event("tab",char="\t")); i+=1; continue
        if b in (8,127): events.append(key_event("backspace")); i+=1; continue
        if 1<=b<=26:
            ch=chr(ord('a')+b-1); events.append(key_event(f"ctrl-{ch}",char=ch,ctrl=True)); i+=1; continue
        if b==0: events.append(key_event("ctrl-space",char="\0",ctrl=True)); i+=1; continue
        ch,consumed=decode_char(data,i)
        if ch is None: break
        if ch==" ": events.append(key_event("space",char=" "))
        else: events.append(key_event(ch,char=ch))
        i+=consumed
    return events,data[i:]

def decode_char(data,i):
    # utf8 decode one char
    for l in range(1,5):
        try:
            s=data[i:i+l].decode('utf-8')
            if len(s)==1: return s,l
        except Exception: continue
    return None,0

def key_event(name,char=None,ctrl=False,alt=False):
    return {"type":"key","name":name,"char":char,"ctrl":ctrl,"alt":alt}
def alt_key_name(ch):
    if ch==" ": return "alt-space"
    return f"alt-{ch}"
def parse_ss3(final):
    mp={'P':'f1','Q':'f2','R':'f3','S':'f4','A':'up','B':'down','C':'right','D':'left','H':'home','F':'end'}
    return key_event(mp[final]) if final in mp else None
def parse_csi(final,params):
    # SGR mouse CSI < b ; x ; y M/m
    if params.startswith("<") and final in "Mm":
        try:
            b,x,y=[int(p) for p in params[1:].split(";")]
            return {"type":"mouse","button":b,"x":x,"y":y,"press":final=="M"}
        except Exception: return None
    parts=params.split(";") if params else []
    def pi(idx,default=1):
        try: return int(parts[idx]) if idx<len(parts) and parts[idx] else default
        except: return default
    code=pi(0,1); mod=pi(1,1)
    ctrl=mod in (5,6,7,8); alt=mod in (3,4,7,8); shift=mod in (2,4,6,8)
    def name_for(base):
        if ctrl: return f"ctrl-{base}"
        if alt: return f"alt-{base}"
        return base
    if final in "ABCD":
        base={'A':'up','B':'down','C':'right','D':'left'}[final]; return key_event(name_for(base),ctrl=ctrl,alt=alt)
