    app=None; runner=None
    try:
        app=App(cli)
        runner=Runner(app,cli)
        # SIGWINCH handler sets flag
        def on_winch(signum,frame): runner._resize_pending=True
        try: signal.signal(signal.SIGWINCH,on_winch)
        except Exception: pass
        runner.open_terminal()
        runner.draw()
        runner.run_loop()
        runner._fifo_stop()
        runner._restore_terminal()
        # remove session dir
