def _extract_variant_name(text):
    s=text.lstrip(" \t\r\n")
    if s.startswith("---"):
        rest=s[3:]
        if rest[:1] in (" ","\n"): s=rest.lstrip(" \t\n")
    if not s: return None
    if s[0]=="[":
        raise MsgError("invalid type: sequence, expected enum ExternalMsg")
    def parse_quoted_name(q):
        qch=q[0]; out=""; i=1
        while i<len(q):
            if qch=="'" and q[i]=="'":
                if i+1<len(q) and q[i+1]=="'": out+="'"; i+=2; continue
                return out
            if qch=='"' and q[i]=='"': return out
            if qch=='"' and q[i]=='\\' and i+1<len(q): out+=q[i+1]; i+=2; continue
            out+=q[i]; i+=1
        return out
    if s[0]=="{":
        inner=s[1:].lstrip()
        if not inner or inner[0]=="}": return None
        if inner[0] in "'\"": return parse_quoted_name(inner)
        m=re.match(r'([^:,}]+)',inner)
        return m.group(1).strip() if m else None
    first=s.split("\n",1)[0]
    if first[:1] in "'\"":
        return parse_quoted_name(first)
    idx=-1
    for i,ch in enumerate(first):
        if ch==':' and (i+1>=len(first) or first[i+1] in " \t"): idx=i; break
        if ch=='#' and i>0 and first[i-1] in " \t": break
    if idx>=0:
        return first[:idx].strip()
    token=first.strip()
    if " #" in token: token=token.split(" #",1)[0].rstrip()
    return token

def validate_external_from_yaml_text(text):
    name=_extract_variant_name(text)
    if isinstance(name,str) and name:
        if resolve_plain_scalar(name) == name and name not in VARIANTS:
            raise MsgError(f"unknown variant `{name}`, expected one of {variants_list_str(VARIANTS)}")
    from yamlmini import parse_yaml as _py
    return validate_from_yaml_node(_py(text))
